window.__D("text/likkutei-sichot/c107",{"p":[[1300161357,"וואַרום בנדרים „הלך אחר לשון בני אדם\"<sup data-n=\"18\">18</sup>, ובלשון בני אדם, אויב א מענטש זאגט „ז' אדר\" (א זמן רב) לאחרי מיתת משה, מיינט ער געוויס ווי דאס איז בזמן האמירה — לאחר מיתתו. ואעפ\"כ איז דא א סברא אז ער מיינט א יום<sup data-n=\"19\">19</sup> שמחה<sup data-n=\"20\">20</sup>].\nנאך שטארקער איז די שאלה: די גמרא זאגט אין מגילה<sup data-n=\"21\">21</sup>, „כיון שנפל פור בחודש אדר שמח (המן) שמחה גדולה אמר נפל לי פור בירח שמת בו משה ולא הי' יודע שבשבעה באדר מת ובשבעה באדר נולד\". איז פון דער גמרא משמע אז דער „בשבעה באדר נולד\" האט גובר געווען דעם „בשבעה באדר מת\" און עס איז געווען „ונהפוך הוא\" — דער נס פון פורים, שמחה.\nזעט מען דאך אז יום לידת משה איז א (גורם צו א) יום שמחה בכל הזמנים,\nובפרט ע\"פ פירש\"י שם<sup data-n=\"22\">22</sup> „כדאי הוא יום הלידה שיכפר<sup data-n=\"23\">23</sup> על המיתה\"<sup data-n=\"24\">24</sup> — איז גאר משמע אז ס'איז נאר א יום שמחה.\nד. וועט מען דאס פארשטיין בהקדם דברי הגמרא<sup data-n=\"25\">25</sup>, „כשם שמשנכנס אב ממעטין בשמחה כך משנכנס אדר מרבין בשמחה\". ויש לברר: דער ענין פון „מרבין בשמחה\"<sup data-n=\"26\">26</sup> אין א שנה מעוברת — צי עס איז אויך באדר ראשון אדער נאר באדר שני<sup data-n=\"27\">27</sup> ?\nלכאורה איז דאס מבואר ע\"פ פירש\"י<sup data-n=\"28\">28</sup>, וואס איז מפרש די גמרא משנכנס אדר „ימי ניסים היו לישראל פורים ופסח\" — וואס דאס איז נאר באדר שני<sup data-n=\"29\">29</sup>. אבער י\"ל אז פון דעם פירוש רש\"י איז ניט קיין ראי', ואדרבה: מען קען גאר מדייק זיין להיפך.\nובהקדם השאלה הידועה: וואס איז רש\"י דא מוסיף „פסח\" — וואס פאר א שייכות האט דא פסח ?\nפאראן מפרשים<sup data-n=\"30\">30</sup> וואס זאגן, אז רש\"י איז אויסן דערמיט צו פארענטפערן",[["18","18","נדרים ל, ב. וש\"נ."],["19","19","ובפי' הרא\"ש (ועד\"ז בתוסף' הרא\"ש בשטמ\"ק) נזיר שם מפורש „שהרי גם בז' באדר נולד וכמו כן הוא יום משתה ושמחה\". ועד\"ז בשיטה לחכמי איוורא נזיר שם „והוה יום משתה ושמחה\"."],["20","20","במאירי נזיר שם: „הן שיכוין לומר על משה שמת בו ולא שתה יין בכל אותו היום כלומר שיום מותו ודאי לא נתעסק בצרכי גופו כלל\". ועפ\"ז לכאורה י\"ל גם לאידך, שכוונתו „כמשה בשבעה באדר\" כמו שמצינו „ששמח משה\" ביום מותו — ראה פרש\"י תבא כט, ג. אבל — אינו, כי שמחת משה אז הי' מזה שאמרו בנ\"י „אף אנו עמדנו בסיני כו'\", ופשיטא שאין מקום לומר שיהי' יום ז' באדר יום שמחה לכל הדורות מפני שאז אמרו בנ\"י כו' (כמו שלא קבעו יום שמחה ביום דויחן ישראל נגד ההר, כשנדבו דם והותר למשכן בב' ימים (במדב\"ר פי\"ב, טז. וראה רמב\"ן ויקהל לו, ג). ועוד זאת — עד כ\"כ שזה יבטל הצער שמת אז ! בסגנון אחר: הצער שמת קשור בז' אדר. משא\"כ אמירת בנ\"י הנ\"ל — ה\"ז גילוי מעמדם שהם דבקים וחפצים במקום. ופשוט."],["21","21","יג, ב."],["22","22","ד\"ה ובשבעה."],["23","23","להעיר משייכות פורים לכפרה ע\"פ מש\"כ בתקו\"ז (תכ\"א (נז, ב)) ד„כפורים\" הוא „כ-פורים\"."],["24","24","כ\"ה ברש\"י שבעי'. וברש\"י שבש\"ס — בשינוי לשון קצת."],["25","25","תענית כט, סע\"א."],["26","26","הובא במג\"א סי' תרפ\"ו סק\"ה. וכבר שקו\"ט בהטעם שלא כתבו הרמב\"ם ולא בטושו\"ע (ראה שו\"ת חת\"ס או\"ח סק\"ס. ומה שהקשה על דבריו בנמוקי או\"ח סי' תרפו). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111345\" data-slug=\"likkutei-sichot\" data-id=\"1300111345\">לקו\"ש חי\"א ע' 338</a> בהערה. ובארוכה — שיחת פורים וש\"פ תשא תשל\"א. ואכ\"מ."],["27","27","ראה שאילת יעב\"ץ שבהערה 29. ומזה גופא מוכח שאי\"ז פשוט כ\"כ."],["28","28","תענית שם ד\"ה משנכנס."],["29","29","ראה שו\"ת שאילת יעב\"ץ ח\"ב ספ\"ח „וי\"ל עוד כו'\"."],["30","30","א\"ר או\"ח סי' תרפה פק\"ת."]]],[1300161358,"פארוואס „מרבין בשמחה\" איז נאר אין חודש אדר מצד דעם נס פורים, און ניט אין חודש ניסן מצד די ניסים פון פסח ?\nאיז דעריבער רש\"י מוסיף „ופסח\" — אז אין הכי נמי, אויך בניסן איז מען מרבה בשמחה מצד פסח שבו.\nאבער עס איז מובן, אז ס'איז שווער אזוי איינצולערנען אין רש\"י, וואַרום אויב רש\"י וויל זאגן א דבר חדש ובפרט וואס איז נוגע למעשה (אז אויך ניסן דארף זיין „מרבין בשמחה\"), האט ער דאס געדארפט זאגן ברור, און ניט פאר־לאזן זיך אז מען וועט עס פארשטיין פון א רמז פון א ווארט<sup data-n=\"31\">31</sup>.\nאויך: לפי\"ז האט מען דאך געדארפט מרבה זיין בשמחה אויך אין חודש כסלו מצד דעם נס חנוכה<sup data-n=\"32\">32</sup> [ואדרבה: ווי־באלד אז חנוכה איז בלויז מדרבנן, וואס דברי סופרים צריכין חיזוק<sup data-n=\"33\">33</sup> — האט\nמען דאך דאן געדארפט מרבה זיין בשמחה נאך מער ווי בניסן (וואס פסח איז מדברי תורה ואין צריכין חיזוק<sup data-n=\"33\">33</sup>, און אפילו מער פון אדר — וואס קריאת המגילה פון פורים איז דאך (ניט א סתם דרבנן, נאר) מדברי קבלה<sup data-n=\"34\">34</sup>].\nאנדערע לערנען<sup data-n=\"35\">35</sup>, אז מיטן זאגן „פורים ופסח\" מיינט רש\"י, אז היות ווי בחודש אדר האבן זיך אנגעהויבן ימי ניסים רצופים ותכופים זל\"ז דעריבער איז דוקא „משנכנס אדר מרבין בשמחה\" (משא\"כ בכסלו ווען ס'זיינען ניט געווען ניסים „רצופים ותכופין זל\"ז\").\nאבער אויך דאס פאדערט ביאור: וואס איז די שייכות (סמיכות בתוכן) צווישן פסח און חודש אדר, אז צוליב דער סמיכות פון אדר צו פסח זאל מען שוין אין התחלת אדר מרבה זיין בשמחה<sup data-n=\"36\">36</sup>.\nה. איז דער ביאור אין דעם: די גמרא זאגט „משנכנס אדר מרבין בשמחה\" — אז גלייך פון התחלת החודש איז מען מרבה בשמחה [און „הלכך בר ישראל דאית לי' דינא בהדי",[["31","31","ולהעיר מהמדובר כמ\"פ (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151294\" data-slug=\"likkutei-sichot\" data-id=\"1300151294\">לקו\"ש חי\"ה ע' 281</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101026\" data-slug=\"likkutei-sichot\" data-id=\"1300101026\">ח\"י ע' 26</a>) שהלכה צריך לומר בלשון ברור (ואפילו אם הוא לשון מגונה)."],["32","32","בפשטות י\"ל כי אי אפשר שיהא בהמסובב מה שאין בהסיבה, כי גם ימי חנוכה עצמם לא קבעום למשתה ושמחה כ\"א בהלל והודאה (שבת כא, ב. טושו\"ע או\"ח סי' עתר ס\"ב), משא\"כ פורים שקבעו למשתה ושמחה (וידוע דברי הלבוש וט\"ז שם סק\"ג בטעם החילוק). אבל להעיר: א) לדעת הרמב\"ם (הל' חנוכה פ\"ג ה\"ג) ועוד — גם חנוכה הם ימי שמחה (ראה הוספות לשו\"ע אדה\"ז חאו\"ח סתר\"ע — מבעהמ\"ס דברי נחמי' (וש\"נ)). וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101142\" data-slug=\"likkutei-sichot\" data-id=\"1300101142\">לקו\"ש ח\"י ע' 142</a> ואילך. ב) ה„מרבין בשמחה\" (המדובר בפנים „משנכנס אדר\") הוא לא „שמחה ומשתה\" (ריבוי סעודות וכיו\"ב) כבפורים, כ\"א איזו שמחה שתהי', גם שמחה בעניני הרשות (ראה לקו\"ש ח\"ד ע' 1274. נמוקי או\"ח שם בסופו). וראה לקמן בפנים מהיעב\"ץ."],["33","33","תענית יז, ב. ר\"ה יט א (ושם, שלכן הימים הכתובים במגילת תענית שם לפניהם ולאחריהם אסורין, משא\"כ שבתות ויו\"ט)."],["34","34","ראה בעל המאור ספ\"א דמגילה, דבפורים (לבני ארביסר) לא נאסר יום שלפניו בתענית דדברי קבלה אין צריכין חיזוק. וראה אחרונים בשו\"ע או\"ח סתר\"ע, שאסור להתענות לפניו בחנוכה. וראה ב\"ח או\"ח סי' תרפ\"ז."],["35","35","שו\"ת שאילת יעב\"ץ ח\"ב שם. וראה שו\"ת חת\"ס שם."],["36","36","בשאילת יעב\"ץ שם „דאי משום פורים גרידא א\"כ לימא נמי ניסן וכסלו אלא ע\"כ משום שהתחילו ימי ניסים רצופים ותכופים זל\"ז\". ולכאורה י\"ל שמפרש „משנכנס אדר\" היינו „משנכנס אדר\" ואילך — כולל חודש ניסן, אבל (נוסף על השאלה שבפנים: מהי השייכות ל„משנכנס אדר\" — להתחלת אדר — הרי) אי\"ז דומה ל„משנכנס אב\" שפשיטא שקאי רק על אב (ולא על החודש שלאח\"ז). ואם כוונת רש\"י דמרבין בשמחה קאי גם על חודש ניסן (דלא כ„משנכנס אב כו'\") הו\"ל לפרש זה בלשון ברור, וכנ\"ל בפנים."]]],[1300161359,"נכרי לישתמיט מינ' באב כו' ולימצי נפשי' באדר (סתם — אויך אין אנהויב חודש) דבריא מזלי'\"] — ולכאורה: דער נס איז דאך געווען בי\"ג אדר, היינט פארוואס דארף זיין די שמחה שוין פון התחלת אדר ?\nאון כאטש אז דער ביטול הגזירה פון אחשורוש איז געווען א סך פריער ווי י\"ג אדר, וכמש\"נ<sup data-n=\"37\">37</sup> „בחודש השלישי הוא חודש סיון בשלושה ועשרים בו גו' ויכתב בשם המלך אחשורוש ויחתם בטבעת המלך גו' אשר נתן המלך ליהודים גו' להקהל ולעמוד על נפשם\" — איז אבער ממנ\"פ: די כתיבה וחתימה איז געווען נאך בחודש השלישי גו' און דער בפועל וואס ביז דאמאלס איז דאס געווען מחוסר מעשה, ומעשה רב — מען האט געדארפט אנקומען צו מלחמה „להקהל ולעמוד על נפשם\", און „נקהלו היהודים בעריהם גו' לשלוח יד במבקשי רעתם\"<sup data-n=\"38\">38</sup> — און ערשט בי\"ג אדר איז געווען דער נס און בי\"ד באדר נחו מאויביהם<sup data-n=\"39\">39</sup>, איז פארוואס תיכף משנכנס אדר, נאך איידער ס'איז געווען די הצלה, איז מען שוין מרבה בשמחה ?\n[און אזוי איז אויך שווער וואס עס שטייט אין דער מגילה<sup data-n=\"40\">40</sup> „והחודש אשר נהפך להם מיגון לשמחה\", אז דער גאנצער חודש איז נהפך געווארן לשמחה, ומצד דעם זאגט דער ירושלמי<sup data-n=\"41\">41</sup> אז (אויב איינער קען ניט\nוואַרטן צו לייענען די מגילה בי\"ד, קען ער זי לייענען מתחילת החודש (ווייל) „כל החודש כשר לקריאת המגילה\" (און דער רמ\"א<sup data-n=\"42\">42</sup> זאגט אויף דעם „והכי נהוג\"). ולכאורה איז דאך די הצלה געווען ערשט בי\"ג ?].\nאון אט די שוועריקייט ווערט פאר־ענטפערט מיט רש\"י'ס לשון „ימי נסים היו לישראל פורים ופסח\", כדלקמן.\nו. די הסברה בזה<sup data-n=\"43\">43</sup>: פון דעם מאמר הגמרא „כשם שמשנכנס אב ממעטין בשמחה כך משנכנס אדר מרבין בשמחה\" איז מובן, אז „מרבין בשמחה\" אין חודש אדר איז דער זעלבער גדר ווי ממעטין בשמחה אין חודש אב.\nאין דעם אונטערשייד צווישן חודש אב לגבי די אנדערע חדשים ווען עס זיינען פארגעקומען מאורעות בלתי רצויים — וואס דוקא ביי אב זאגט מען „ממעטין בשמחה\" — געפינט מען צוויי ענינים: (א) „הוכפלו בו צרות\"<sup data-n=\"44\">44</sup>. (ב) ס'איז א „יום חייב\", ווי די גמרא<sup data-n=\"45\">45</sup> זאגט אויף דעם אז אויך בשני חרב הבית בט' באב ווייל „מגלגלין זכות ליום זכאי וחובה ליום חייב\" — וואס י\"ל אז דאס איז ניט בלויז מצד דעם חורבן הבית בראשונה באותו יום, נאר אויך נאך פון פריער, כמאמר הגמרא<sup data-n=\"45\">45</sup> אויף „ויבכו העם בלילה ההוא\"<sup data-n=\"46\">46</sup> — „תשעה באב הי' אמר להם הקב\"ה אתם בכיתם בכי' של חנם ואני קובע לכם בכי' לדורות\".",[["37","37","אסתר ח, ט ואילך."],["38","38","ט, ב. וראה מנות הלוי (למגילת אסתר שם) מכמה מפרשים, דאגרות השניות לא הי' ביטול הגזירה שבאגרות הראשונות. וראה תרו\"א (קכ, ד) שבני ישראל היו בסכנה מפני גזירת המן „שנמשך הזמן כמעט משך שנה היו כולם בבחי' מס\"נ ממש\"."],["39","39","שם טו, יז."],["40","40","שם כב."],["41","41","מגילה פ\"א ה\"א."],["42","42","אור\"ח סתרפ\"ח ס\"ז."],["43","43","להעיר משו\"ת חת\"ס שם. וראה עיון יעקב לע\"י תענית שם."],["44","44","ר\"ה יח, ב. משא\"כ בשבעה עשר בתמוז כבתוס' שם ד\"ה הואיל."],["45","45","בתענית שם."],["46","46","שלח יד, א."]]],[1300161360,"לויט דעם קומט אויס, אז דער „מרבין בשמחה\" פון חודש אדר איז אויך עד\"ז: ס'איז הוכפלו בו הניסים און ס'איז א יום זכאי.\nוואו געפינט מען אט די באזונדער־קייט פון חודש אדר ? איז דאס אין דער גמרא הנ\"ל אין מגילה: „כיון שנפל פור בחודש אדר שמח שמחה גדולה אמר נפל לי פור בירח שמת בו משה ולא הי' יודע שבשבעה באדר מת ובשבעה באדר נולד\". זעט מען פון דעם, אז די סיבה וואס האט געבראכט דעם נס פורים בחודש אדר איז דער טאג ז' אדר, ד.ה. דאס וואס דער גורל איז אויס־געפאלן בחודש אדר, דאס גופא האט מבטל געווען די גזירת המן אויף דעם חודש, ובמילא איז אין דעם חודש געווען דער נס פורים.\nדער אויפטו פון ז' אדר איז וואס נולד „מושיען של ישראל\"<sup data-n=\"47\">47</sup> וואס האט ארויסגענומען אידן פון גלות מצרים.\nקומט דאך אויס, אז בחודש אדר זיינען דא ביידע ענינים הנ\"ל: ס'איז א (חודש וואס האט א) יום זכאי — ז' אדר: און ס'איז הוכפלו בו הניסים וגאולות — ווארום דער טאג ז' אדר איז דער מקור וסיבה פון צוויי גאולות: די (ישועה ו)גאולה פון מצרים און די גאולה פון פורים<sup data-n=\"48\">48</sup>.\nוי\"ל אז דאס מיינט רש\"י מיטן מוסיף זיין „(פורים ו)פסח\": דער גדר פון\n„משנכנס אדר מרבין בשמחה\" איז ניט (נאר) מצד שמחת פורים (יד אדר), נאר ווייל דער חודש איז א חודש זכאי<sup data-n=\"49\">49</sup> וואס האט געבראכט צו „ימי ניסים היו לישראל\" — אויך צו פסח (וכנ\"ל אז ישועת ישראל בפסח איז לידתה התחלתה וסיבתה ב(ז') אדר)<sup data-n=\"50\">50</sup>, און דערפאר איז תיכף משנכנס אדר מרבין בשמחה<sup data-n=\"51\">51</sup>.\n[און דערמיט איז מובן פארוואס מען זאגט „החודש<sup data-n=\"52\">52</sup> אשר נהפך להם גו'\" (און „כל החודש כשר לקריאת המגילה\") — ווארום דער נס פורים האט זיך אנגעהויבן ניט פון יום יג אדר, נאר גלייך בתחילת הגזירה איז שוין געווען צוגעגרייט דער נס מצד דעם גורל וואס איז אויסגעפאלן בחודש אדר וואס אין אים איז ז' אדר]<sup data-n=\"53\">53</sup>.",[["47","47","וכבסוטה שם: ראו שמושיען של ישראל במים הוא לוקה עמדו וגזרו כל הבן כו' כיון דשדיוהו למשה כו'."],["48","48","וי\"ל שעפ\"ז הרי זה מתאים לפי' הב' בתוס' ר\"ה שם דצרה אחת הוכפלה בו (ראה טו\"א שם דפי' ב' עיקר. וראה חי' הריטב\"א שם). ועד\"ז בנדר\"ד דהיו ב' גאולות (ראה מגילה ו, סע\"ב „מסמך גאולה לגאולה\")."],["49","49","להעיר שגם יום הולדת האבות פעל על כל החודש, שנק' „ירח האיתנים\" (ר\"ה יא, א)."],["50","50","ואין רש\"י צריך לפרטו בפירוש כי מאחר שמעתיק תיבת „משנכנס אדר\" „ימי נסים היו לישראל פורים\" ויודעים השייכות דפורים (פרשת הנס דפורים) ל„משנכנס אדר\" — לכל ימי חודש אדר, אותה השייכות יש גם לפסח לה„משנכנס אדר\"."],["51","51","להעיר על השייכות דפורים לפסח דביום ב' דפסח בסעודת אסתר נתלה המן, ועד שגם עכשיו „טוב לעשות איזה דבר בסעודה ביום ב' לזכר\" זה (מג\"א או\"ח רסת\"ז. שו\"ע אדה\"ז שם ס\"ב)."],["52","52","כן להעיר מתרגום שני עה\"פ דרך הפלת הפור מחודש לחודש עלתה בידו ולא ד„מיום ליום\" דמפרשו יום בשבוע (ולא כפרש\"י). וצע\"ק — היום בחודש לא נקבע ע\"פ הפור."],["53","53","ע\"פ כהנ\"ל יומתק המשך הגמרא בתענית שם „אר\"פ הלכך בר ישראל דאית לי' דינא בהדי נכרי לישתמיט מינ' באב דריע מזלי' ולימצי נפשי' באדר דבריא מזלי'\" ובתוס' שם ד\"ה אמר ר\"פ „פירוש משום דאמר לעיל מגלגלין חובה ליום החייב\" (ראה שו\"ת חת\"ס שם „ונדחקו התוס' דקאי אלעיל דמגלגלין כו' ורמב\"ם ס\"ל כפשוטו אדרב קאי\"), ועפ\"ה הנ\"ל י\"ל [נוסף על הפשוט שגם לתוס'"]]],[1300161361,"ז. והנה דעם טעם אויף די ימי התענית וואס ווערן אויסגערעכנט אין שו\"ע<sup data-n=\"54\">54</sup> „אלו הימים שאירעו בהם צרות לאבותינו וראוי להתענות בהם\" (וז' אדר בתוכם) קען מען מסביר זיין אויף צוויי אופנים:\nא) וויבאלד אז „אלו הימים שאירעו בהם צרות לאבותינו\" זיינען זיי היפך השמחה, ימים חייבים, ובמילא „ראוי להתענות בהם\" אויף צו באוואַרענען עס זאלן ניט זיין קיין ענינים בלתי רצויים [וואַרום כאטש „אין מזל לישראל\"<sup data-n=\"55\">55</sup> איז דאך דער פירוש אז „ע\"י תפלה וזכות משתנה מזלו לטובה\", ווי רש\"י זאגט<sup data-n=\"56\">56</sup>, ובמילא דארף אין די טעג זיין א תענית אויף אראפנעמען דעם ענין פון „חייב\"].\nב) וויבאלד אז אין די טעג האבן געטראפן ענינים היפך השמחה, ובפרט הסתלקות של צדיקים, דארף זיין „והחי יתן אל לבו\"<sup data-n=\"57\">57</sup>, און דעריבער איז מתענין, „כדי לעורר הלבבות לפתוח דרכי התשובה\"<sup data-n=\"58\">58</sup>.\nדי נפק\"מ צווישן ביידע הסברות איז: אין א טאג ווען ס'זיינען דא ביידע\nענינים, סיי שמחה און סיי היפך השמחה: לויטן ערשטן טעם — אז דער תענית איז ווייל ס'איז א יום חייב — דארף מען ניט פאסטן, וואַרום ווי־באלד אז דאס איז אויך א יום שמחה (עס האבן געטראפן ענינים טובים), ווייזט עס דאך אז ער איז ניט קיין יום חייב. משא\"כ לויטן צווייטן טעם — אז דער תענית איז צוליב ענין התשובה — דארף מען פאסטן, ווייל עס מוז זיין דער „והחי יתן אל לבו\" — „לפתוח דרכי התשובה\" [וואַרום דאס וואס ער איז אויך א יום שמחה איז ניט קיין סתירה צום ענין התשובה — ואדרבה, מ'געפינט בא שמחת בית השואבה, וואס „מי שלא ראה שמחת ביה\"ש לא ראה שמחה מימיו\"<sup data-n=\"59\">59</sup> האט מען מעורר געווען אויף תשובה „מי שחטא ישוב וימחול לו\"<sup data-n=\"60\">60</sup>].\nעפ\"ז איז אויך פארשטאנדיק בנוגע לז' אדר: ווי־באלד אז מען געפינט אז דאס איז א יום שמחה, ביז אזא יום זכאי וואס האט גורם געווען דעם גאנצן נס פורים, און — ביז אז דאס פועלט אז דער גאנצער חודש ווערט א זמן פון (מרבין ב)שמחה — איז מובן, אז דער תענית פון ז' אדר ווייל בו מת משה רבינו איז ניט מצד דעם וואס ער איז א יום חייב, נאר „לפתוח בדרכי התשובה\". און דאס וואס ביום זה נולד איז אדרבה גאר מסייע אז די תשובה זאל זיין אין א העכערן און בעסערן אופן, מתוך שמחה<sup data-n=\"61\">61</sup>, פונקט ווי אלע מצות דארפן געטאן ווערן מתוך שמחה<sup data-n=\"62\">62</sup>.",[["","","קאי „הלכך\" אדרב, אלא שמוסיף בטעם ר\"פ „משום דאמר לעיל מגלגלין\" לכן כיון שבאב ממעטין ובאדר מרבין „הלכך\" באב לישתמיט כו', אבל זה לבד אינו מספיק כי דוחק לומר שרק מצד הענין דממעטין או מרבין בשמחה יקרא יום זכאי ויום חייב, ועפ\"ז הנ\"ל י\"ל] שקאי בהמשך לתוכן הסברא דרב, שזה שמרבין בשמחה באדר הוא מצד ימים זכאין כו' שנלמד מהפכו באב, ולא רק מצד הדין ד„מרבין בשמחה\". וראה ריטב\"א שם."],["54","54","אור\"ח סי' תקפ."],["55","55","שבת קנו, א."],["56","56","שם ד\"ה אין מזל. וכ\"מ מדברי ר\"י אמר רב שם „צא מאיצטגנינות שלך וכו' מהדרנא ומוקמינא לי' במזרח\" דיש מזל. וכן מוכח מהמשך כל הסוגיא שם."],["57","57","קהלת ז, ב."],["58","58","לשון הרמב\"ם רפ\"ה מהל' תעניות."],["59","59","סוכה נא, א (במשנה)."],["60","60","שם נג, רע\"א."],["61","61","ראה אגה\"ת פי\"א. ובכ\"מ."],["62","62","ראה רמב\"ם סוף הלכות לולב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>. ובכ\"מ."]]],[1300161362,"און ווי רש\"י זאגט בנוגע לנס פורים, „כדאי הוא יום הלידה שיכפר על המיתה\" ד.ה. אז אויך דער יום המיתה ווערט באווירקט פון יום הלידה.\nח. עפ\"ז איז מובן בנוגע לשנה מעוברת: היות אז לויטן מג\"א איז דער תענית ז' אדר באדר ראשון, וואס דער־פון איז מובן אז אויך דער ענין השמחה, וואס ער איז א יום זכאי מצד לידת משה, איז אויך בז' אדר ראשון (כנ\"ל, אז הקב\"ה יושב וממלא שנותיהם של צדיקים מיום ליום)<sup data-n=\"63\">63</sup>,\nקומט דאך אויס, אז אויך משנכנס אדר ראשון דארף זיין אן ענין פון מרבין בשמחה<sup data-n=\"64\">64</sup>, מצד דעם ביאור הנ\"ל פון רש\"י, ווי־באלד אז אין דעם חודש<sup data-n=\"65\">65</sup> איז דא דער יום זכאי פון ז' אדר וואס האט געבראכט די ימי ניסים לישראל פורים ופסח<sup data-n=\"66\">66</sup>, ובפרט אז די „ימי ניסים\n„לישראל\" זיינען שוין פארזן אויך אין חודש אדר ראשון — אין פורים ושושן פורים קטן וואס „ימי נס והצלה הם\"<sup data-n=\"67\">67</sup> [כאטש כמובן, אז דאס קומט ניט צו דעם „מרבין בשמחה\" פון דעם אדר ווען מ'פראווענט פורים ממש, וואס דאן זיינען דא די „ימי ניסים לישראל\" בפועל ממש].\nט. ע\"פ הנ\"ל אין מעלת יום ז' אדר אלס לידת משה, ווערט לכאורה ערשט ניט פארשטאנדיק: פארוואס געפינט מען אין שו\"ע נאר דאס וואס מתענים בז' אדר שבו מת משה, און מען געפינט ניט קיין שום ענין פון שמחה אלס זכר צו לידתו בז' אדר ?\nוי\"ל אז היא הנותנת: ווי־באלד אז דער ענין פון יום זכאי פון דעם טאג איז אן ענין נעלה ביותר, קען דאס ניט אראפ־קומען בגילוי למטה אין א שמחה גלוי', נאר דאס בלייבט בהעלמו און עס פועלט בדרך סיבה<sup data-n=\"68\">68</sup> באופן נבדל.\nדוגמא לדבר בהלכה: יו\"ט וואס איז (נאר) מקרא קודש און מען איז מבדיל",[["63","63","וגם: הרי הקב\"ה מקדים רפואה למכה (ראה מגילה שם) וכדאי הוא יום הלידה שיכפר על המיתה (כפרש\"י מגילה שם) שלכן גם יום זכאי דלידה מובן ש(ענינו) הוא באדר א'. ועפ\"ז הנ\"ל דיום ז' אדר הוא בעצם יום זכאי כו' (שהביא להניסים), י\"ל שזהו כמו שנעשה לו נס באדר פשוטה וקבל עליו לעשותו יום שמחה בכל שנה — שיעשה אותו באדר ראשון (י\"א במג\"א סתרפ\"ו סק\"ה. וכן פסק בפרמ\"ג או\"ח סו\"ס תרצ\"ז), ולהעיר מהוכחת התרומת הדשן שם (הובא במג\"א סי' תקס\"ח סק\"כ) בתענית יום שמת בו אביו שהוא באדר א' מדאמרינן בגמרא מגילה ו, ב. עיי\"ש. ולפי הנ\"ל י\"ל דאין שייך בזה הסברא „אקדומי פורענותא לא מקדימין\" ועושין בשני (ראה שו\"ת חת\"ס שם סי' קסג), כיון שהוא יום שמחה וגם התענית אינו מחמת צער וכו' כנ\"ל."],["64","64","ולא כמ\"ש בשאילת יעב\"ץ שם ח\"ב."],["65","65","ולהעיר דאדר ראשון נקרא אדר סתם לענין שטרות ונדרים משא\"כ אדר ב' (דעת ר\"י בנדרים סג, א. וכ\"ה להלכה טור או\"ח סי' תכח. רמ\"א שם סתכ\"ז. טושו\"ע חו\"מ סי' מג סכ\"ח)."],["66","66","ולהעיר מירושלמי מגילה פ\"א ה\"ה (הובא בשו\"ת חת\"ס שם) אותה השנה היתה מעוברת וא\"כ הנס הי' באד\"ר. וגם לפי פירוש החת\"ס שם שהי' מובן שראוי להתעבר ונמלכו ב\"ד ולא עברוהו להאי שתא (וראה עד\"ז ביערות דבש ח\"ב דרשה ב' (צד, ג) מירושלמי, דגזירת המן הי' על אדר ראשון כו', ומרדכי צוה כו'), הרי ע\"פ הנ\"ל ממגילה (יג, ב) דז' אדר הפך הגזירה תיכף כשהפיל הגורל מיגון לשמחה, נמצא שפעולתו היתה בא\"ר א', וראה שו\"ת חת\"ס שם. ויערות דבש שם."],["67","67","ב\"י סו\"ס תרצו. וראה ב\"י שם דלכמה דיעות הם ימי משתה ושמחה. ובדרכי משה שם ממנהגים וממהרי\"ל. וראה חמד משה שם סק\"א שאם אמר ועל הניסים ב\"ד אדר אין מחזירין אותו שהרי מדינא הי' ראוי לעשות באדר א' כו' אלא שמסמך גאולה כו' עדיף א\"כ מ\"מ הוה מעין המאורע."],["68","68","ראה ביאור החילוק דסיבת הסיבות ועילת העילות (מאמרי אדה\"ז — הנחות הר\"פ ע' קלא. אוה\"ת יתרו ע' תשלה ואילך. ביאוה\"ז (להצ\"צ) ע' לט. המשך תער\"ב פפ\"ב. ובכ\"מ)."]]],[1300161363,"בין קודש שלו לקודש דשבת איז מ\"ע מה\"ת ושמחת בחגך<sup data-n=\"69\">69</sup>, משא\"כ בשבת וואס קודש היא (ביז בהבדלה פון קדושת יו\"ט ועד כדי כך אז דאס קומט בהמשך צו די אנדערע הבדלות<sup data-n=\"70\">70</sup>.\nיו\"ד. די הסברה אין דעם וועט מען פארשטיין בהקדים, וואס „הקב\"ה יושב וממלא שנותיהם של צדיקים מיום ליום\" — אז מתים ביום שנולדו. וואס דער טעם פנימי בזה י\"ל<sup data-n=\"71\">71</sup>, ווייל ביי צדיקים איז זייער שלימות ותכלית ענין הלידה (זייער לידה והתגלות) ביום הסתלקותם. ווארום דעמאלט ווערט נתגלה (צו די תלמידים) פון „רוח רבם העצמיות\"<sup data-n=\"72\">72</sup> מערער און העכער ווי בעת נשמתו איז געווען מלובש אין גוף, און דעמאלט איז מאיר נאך א העכערע הארה, וואס איז מאיר מלמעלה „מעלית רוחו ונשמתו למקור חוצבו כו'\" און די הארה איז „מאירה על כל תלמידיו שנעשו עובדי הוי'<sup data-n=\"73\">73</sup> און „מכנסת בלבם הרהורי תשובה ומעשים טובים\", נאר די הארה איז „בהעלם והסתר גדול כמו שמש המאיר לכוכבים מתחת לארץ כדאיתא בתיקונים על משה רבינו ע\"ה שאחר פטירתו מתפשטת הארתו בכל דרא ודרא לששים רבוא נשמות כמו שמש המאיר מתחת לארץ לששים רבוא כוכבים\"<sup data-n=\"74\">74</sup>.\nמשא\"כ בעת הלידה איז דאך ניטא דער גילוי פון דעם צדיק<sup data-n=\"75\">75</sup>, עס איז בלויז בכח, און דעריבער איז די שלימות ענין הלידה וההתגלות פון צדיק ביום הסתלקותו<sup data-n=\"76\">76</sup>.\nועפ\"ז איז מובן וואס מען געפינט ניט אין שו\"ע וועגן מאכן א שמחה בז' אדר יום הולדת משה רבינו<sup data-n=\"77\">77</sup>, ווארום די שלימות הגילוי וההמשכה פון יום ההולדת ווערט ביום ההסתלקות און דעמאלט איז דאס א המשכה נעלית ביותר באופן של רוממות<sup data-n=\"78\">78</sup>, און בגילוי אין לבושי עוה\"ז זעט זיך נאר דער ענין",[["69","69","ראה טז, יד."],["70","70","להעיר ממגילה (יז, ב) רש\"י ד\"ה אתחלתא „כיון דשם גאולה עלה כו'\"."],["71","71","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051098\" data-slug=\"likkutei-sichot\" data-id=\"1300051098\">לקו\"ש ח\"ה ע' 86</a> (שוה\"ג הא' להערה 1) מספר רסיסי לילה. אלא דשם הוא לעניין עליות הצדיק עצמו משא\"כ בהמבואר לקמן בפנים גם לענין השפעתו לצאן מרעיתו."],["72","72","כן הוא בהדפוסים שראיתי — ולכאורה צ\"ל „העצמיות\" וכמוש\"כ תיכף בהמשך הענין."],["73","73","עפ\"ז מובן ביותר ביאור הנ\"ל בפנים בתענית ז' אדר."],["74","74","אדה\"ז באגה\"ק ביאור לסי' זי\"ך. וראה דרושי ל\"ג בעומר שם סידור (דש, ב-ג). ובכ\"מ."],["75","75","אפילו בלידת משה „שנתמלאה כל הבית כולה אור\" (סוטה יג, א (וראה שם יב, א). וראה אוה\"ת עה\"פ) אין זה בדומה כלל להגילוי שלאח\"ז, כמובן."],["76","76","עפ\"ז יש לבאר (בפנימיות הענינים) מה שאיתא במגילה שם „ולא הי' יודע שבז' באדר מת ובשבעה באדר נולד\" דלכאורה: א) הרי שבז' באדר מת — ידע, והו\"ל „ולא הי' יודע שבז' באדר נולד\" ב) באמרו ב' הענינים הו\"ל בסדר הפוך, שהרי הלידה לפני המיתה — אלא שהמן לא הי' יודע ענינה של מיתת משה (מיתת צדיקים), שבז' באדר שמת אז בא לידי שלימות ענין הלידה והגילוי שלו (וזה פעל שהחודש יהפך כו'). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061374\" data-slug=\"likkutei-sichot\" data-id=\"1300061374\">לקו\"ש ח\"ו ע' 362</a>. וראה יערות דבש ח\"א דרשה ח (מה, סע\"ב ובכ\"מ שם). חכ\"י ע' 1 ואילך. חת\"ס עה\"ת פרשתנו (דרוש לז' אדר א', תקצט ד\"ה ותרא אותו ואילך). ובכ\"מ."],["77","77","להעיר שגם כפשוטו — יש ללמוד מתוך הכתובים שבז' אדר מת (ראה קידושין לח, א), משא\"כ לידתו בז' אדר, נלמד רק במדרש חכמים כו' (חדא\"ג מגילה שם), וכן הי' בנוגע ללידתו כפשוטה, שהוצרך להיות „ותצפנהו\" (שמות ב, ב. סוטה שם יב, ב), משא\"כ מיתתו הי' מפורסמת „ויבכו בנ\"י\" (ברכה לד, ח. וראה סוטה יג, סע\"ב)."],["78","78","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370403\" data-slug=\"torah-or\" data-id=\"3901370403\">תו\"א פט, ד</a>. ד\"ה באתי לגני השי\"ת פ\"א, דגילוי הסוכ\"ע שלמעלה מעולמות נק' בשם אסתלק כי הגילוי הוא בבחי' רוממות. *) וי\"ג כן (ראה דק\"ם שם)."]]],[1300161364,"המיתה, און מצד דעם איז דאס א יום תענית<sup data-n=\"79\">79</sup>, והחי יתן אל לבו.\nיא. לפי\"ז איז מובן דער רמז ושייכות פון עניני ז' אדר צו פ' „ואתה תצוה\" 79*): בגלוי שטייט טאקע ניט אין דער סדרה משה'ס נאמען, ווארום דער ענין פון ז' אדר ווי דאס איז בגילוי איז אן ענין פון יום התענית — הסתלקות.\nלאידך, איז בפנימיות דאס וואס עס שטייט ניט שמו של משה ווייל עס איז מאיר עצמיות פון משה וואס איז העכער פון שם (וגילוי), און דאס דריקט זיך אויס אין דעם נאמען פון דער סדרה\n„ואתה תצוה\": דער לשון „ואתה\" ווייזט אויף עצמיות וואס איז העכער פון שם ותואר<sup data-n=\"80\">80</sup>, „תצוה\" איז (אויך) פון לשון צוותא וחיבור<sup data-n=\"81\">81</sup>, ד.ה. די צוותא וחיבור פון אידן (המצווים) מיט די עצמיות פון משה, וואס פארבינדט אידן מיט עצמות א\"ס (המדבר אל ה„ואתה\")<sup data-n=\"82\">82</sup> —\nאון דאס איז דער תוכן הפנימי פון ז' אדר, אז דעמאלט איז דער תכלית השלימות אין לידת והתגלות משה צו אלע אידן, העכער פון שם וגילוי, באופן של „ואתה תצוה\".\n(משיחות ש\"פ תצוה (ח' אד\"ר), ש\"פ תשא (שושן פורים קטן) — תשכ\"ז)",[["79","79","עפ\"ז יובן זה שנשיאי חב\"ד — לאחרי שקבלו הנשיאות (כידוע סיפור החסידים בחילוק הנהגת כ\"ק אדמו\"ר מהר\"ש בז' אדר בעברו לפני התיבה לאחרי פטירת אמו, ולאח\"ז — בהסתלקות אביו כ\"ק אדמו\"ר הצ\"צ) לא היו אומרים תחנון בשבעה באדר, כי באתפשטותא דמשה (— נשיא בכל דרא ודרא (ת\"ז תס\"ט) — מאיר בחי' משה בלי הסתרים וא\"כ בהם נמצאת בגילוי שלימות הלידה דבחי' משה. *79) ראה גם בארוכה לקו\"ש חכ\"י ע' 204 ואילך. וראה לקו\"ש חכ\"א הנ\"ל הערה 2."],["80","80","ראה ד\"ה זאת תורת הבית תרפ\"ט פ\"א (סה\"מ קונטרסים — ח\"א ע' מה). וראה גם כלי יקר ריש פרשתנו „לכך נאמר ואתה תצוה שני נוכחיות לומר ואתה כו'\"."],["81","81","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א פרשתנו פב, א</a>. מאור עינים פרשתנו."],["82","82","ד\"ה זאת תורת הבית שם. וראה אוה\"ת פרשתנו ע' א'תקנא."]]],[1300161365,"<h3>פורים</h3>\nא. די גמרא זאָגט אין מגילה<sup data-n=\"1\">1</sup>: „שלחה להם אסתר לחכמים קבעוני לדורות\" — אסתר האָט געבעטן מען זאָל קובע זיין י״ד וט״ו אדר „ליום טוב ולקריי״ להיות לי לשם\"<sup data-n=\"2\">2</sup>.\nדערנאָך ברענגט די גמרא אַ צווייטן מאמר אין דעם: „שלחה להם אסתר לחכמים כתבוני לדורות\" — אסתר האָט געבעטן, אַז מען זאָל די מגילה (וואָס איז אויף איר נאָמען) פאַרשרייבן „עם שאר הכתובים\"<sup data-n=\"3\">3</sup>.\nד.ה.<sup data-n=\"4\">4</sup> פריער האָט זי נאָר געבעטן „קבעוני לדורות\" — „ליו״ט ולקריי״\" — מען זאָל יעדעס יאָר לייענען דעם סיפור פון פורים, עס מוז אָבער ניט געלייענט ווערן מתוך הכתב<sup data-n=\"5\">5</sup>; דערנאָך האָט זי געבעטן אַז די מגילה זאָל ווערן פאַרשריבן לדורות און זיין אַ חלק פון „כתובים\" — וואָס דערפאַר מוז מען לייענען די מגילה מתוך הכתב און „קראה ע״פ לא יצא\"<sup data-n=\"6\">6</sup>.\nב. אין ירושלמי<sup data-n=\"7\">7</sup> זאָגט ער: „מרדכי ואסתר כתבו אגרת ושלחו לרבותינו שכן אמרו להם מקבלין אתם עליכם שני ימים הללו בכל שנה כו'\" — ד.ה. ביידע, מרדכי ואסתר, האָבן (געשריבן און) געבעטן וועגן זכרון פורים וכו' ניט (ווי אין בבלי וואו עס ווערט דערמאָנט נאָר) אסתר אליין („שלחה להם אסתר .. קבעוני .. כתבוני\").\nמען קען אָבער זאָגן, אַז דאָס איז ניט אַ פלוגתא (און דערצו נאָך — אין אַ מציאות) צווישן בבלי און ירושלמי (צי די בקשה איז געקומען פון אסתר אליין, אדער פון ביידע צוזאַמען)<sup data-n=\"8\">8</sup>, נאָר עס רעדט זיך וועגן באַזונדערע<sup data-n=\"9\">9</sup> ענינים<sup data-n=\"10\">10</sup>:\nאין בבלי — וועגן דער תקנה פון קריאת המגילה\n[וואָס דערפאַר טייטשט אָפּ רש״י „קבעוני\" — „(ניט נאָר) ליו״ט (נאָר",[["1","1","ז, א."],["2","2","רש״י שם ד״ה קבעוני."],["3","3","פרש״י מג״א ט, לב. וראה חדא״ג מהרש״א מגילה שם."],["4","4","ראה טו״א מגילה שם. הרי״ף לע״י מגילה שם (ד״ה שלחה כו' כתבוני כו')."],["5","5","כ״ה בטו״א שם. ובאו״א קצת י״ל: זה שצ״ל כתיבה הוא רק לצורך קריאתה (אבל לא שניתנה לכתוב להכלל ב„כתובים\" — כד ספרי קודש) — ראה צפע״נ לרמב״ם ריש הל' מגילה. וראה תוד״ה נאמרה (מגילה ז, א) דגם למ״ד (מגילה שם. וש״נ) דאסתר „לא נאמרה ליכתוב\" — „מדרבנן ניתנה ליכתב ולקרות\" (וקראה ע״פ לא יצא), ובריטב״א שם: שלא ניתנה כו' לטמא את הידים אבל מ״מ ניתנה ליכתוב שלא תהא ע״פ. ועד״ז הוא בת״י יומא כט, א. וראה קדושת לוי קדושה ראשונה ד״ה לתריץ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261222\" data-slug=\"likkutei-sichot\" data-id=\"1300261222\">לקו״ש חכ״ו ע' 222</a> ואילך. וידועה השקו״ט בזה מהא דדברים שבע״פ אי אתה רשאי לכתבם (גיטין ס, ב. תמורה יד, ב). ואכ״מ."],["6","6","משנה מגילה רפ״ב."],["7","7","מגילה שם (פ״א ה״ה)."],["8","8","ובפרט שלגירסת היל״ש (עה״פ מג״א ט, כט), ע״י מגילה שם, ועוד (ראה דק״ס שם) — בעל המאמר „קבעוני\" בבבלי הוא „רב(י) שמואל בר (רב) יצחק\" — אותו בעל המאמר בירושלמי שם."],["9","9","במסורת הש״ס לירושלמי שם ציין לבבלי כאן. וראה קה״ע שם ד״ה מקבלים („ליו״ט ולקריי״\"). — אבל לפ״ז יש פלוגתא ביניהם. וידוע הכלל שכל מה שאפשר להשוות בבלי וירוש' משווינן (יד מלאכי כללי שני התלמודים אות י'. שד״ח (כרך ט') כללי הפוסקים סימן ב' אות א'. וש״נ)."],["10","10","להעיר מצפע״נ לרמב״ם שם: ג' דברים עשו אז אחד כתיבת המגילה והב' קריאת המגילה והג' עשיית הסעודה, עיי״ש."]]],[1300161366,"אויך) לקריי״, ווייל דער עיקר בקשה פון אסתר „קבעוני\" („להיות לי לשם\"), איז געווען בשייכות צו קריאת המגילה (וואָס ווערט גערופן על שמה)],\nאון (דערנאָך — אויך) פאַרשרייבן די מגילה אלס איינעם פון די „כתובים\" („כתבוני\") — און די צוויי בקשות זיינען געקומען פון אסתר אליין<sup data-n=\"11\">11</sup> (אָן דער השתתפות פון מרדכי)<sup data-n=\"12\">12</sup>.\nאין ירושלמי<sup data-n=\"13\">13</sup> אָבער רעדט זיך נאָר וועגן דער עצם תקנה פון קובע זיין די ימי הפורים בכל שנה „ימי משתה ושמחה ומשלוח מנות איש לרעהו ומתנות לאביונים\"<sup data-n=\"14\">14</sup> [ווי פשטות לשון הירושלמי „מקבלין .. שני ימים הללו בכל שנה כו'\"]<sup data-n=\"15\">15</sup>, און דאָס האָבן ביידע צוזאַמען געבעטן ביי די חכמים<sup data-n=\"16\">16</sup>.\nג. די דריי ענינים הנ״ל [(א) „מקבלין אתם עליכם שני ימים הללו\", (ב) „קבעוני\", (ג) „כתבוני\"] און דער אויבנגעזאָגטער חילוק צווישן זיי [דעם ערשטן ענין — האָבן געבעטן מרדכי ואסתר, און די לעצטע צוויי — אסתר אליין] — י״ל אז זיי זיינען מרומז בהדגשה אין דער מגילה<sup data-n=\"17\">17</sup>:\nביים דערציילן ווי אידן האָבן אנגענומען<sup data-n=\"18\">18</sup> „לקים את ימי הפורים האלה\"<sup data-n=\"19\">19</sup>",[["11","11","וי״ל שגם מטעם זה נק' המגילה רק ע״ש אסתר, ע״ד מחז״ל (מדרש תהלים מזמור א, ב. ועוד) בנוגע לתורה, דלפי שמשה „נתן נפשו עלי' לפיכך נקראת על שמו\"."],["12","12","ראה עד״ז מגילת סתרים למג״א (ט, כט) דמרדכי (באגרת הא' — מג״א ט, כב) לא צוה רק על עשיית השמחה בימי הפורים אבל כתיבת וקריאת המגילה היתה רק אסתר העיקר כו'. ושם, שזוהי הוספת אסתר באגרת הב' (שם, כט) „ותכתוב אסתר המלכה גו'\" — כי באגרת זו נתחדשו בקשות אסתר לכתיבת וקריאת המגילה • [ולכן גם מקדים אסתר למרדכי. משא״כ באגרת הא' שלא נזכרה אסתר כלל — כי בענין עשיית שמחה בימי פורים (ובפרט בעת אגרת הא') היא טפלה למרדכי. שלכן מקדים הכתוב (שם, לא — המדבר בענין ימי שמחה כו' דפורים, כדלקמן סעיף ג') מרדכי לאסתר. וראה לקמן הערות •21, 61]."],["13","13","וצ״ע ליישב המבואר בפנים (ובהערה 15) בלשון המדרש (רות רבה פ״ד, ה) שהוא ע״ד סוגיית הירושלמי, ומ״מ הלשון שם „מגלת אסתר\", עיי״ש. אבל להעיר מתשב״ץ דלקמן הערה הנ״ל, שמתרץ דברי הרמב״ן (שאיירי בהתקנה דימי משתה ושמחה) שמכוון להירושלמי „וכן הוא במדרש רות רבתי\". •) וכן משמע מפרש״י שם, לב (נעתק לקמן הערה 24). ולהעיר מפרש״י שם, כ. אבל י״ל שאי״ז ענין כתיבת המגילה בין הכתובים, וגם לא תיקון אז קריאת המגילה (אבל ראה מנות הלוי שם, כג). אבל אין להקשות מדרז״ל (עה״פ שם, כז-כח ועוד) שקאי על קריאת וכתיבת המגילה — כי פסוקים הנ״ל (מפסוק כג ואילך) אינם מהאגרת (ראה פנ״י מגילה שם — מטעם אחר)."],["14","14","לשון הכתוב מג״א ט, כב."],["15","15","לכאורה יש להקשות עז״מ מהמשך הסוגיא בירושלמי שם: „היו מצטערין על הדבר הזה .. ומרדכי ואסתר מבקשים לחדש לנו דבר\" — שמהמשך הסוגיא שם משמע לכאורה שקאי על כתיבת המגילה, ובפרט שבבבלי מובא תוכן שקו״ט זו דהחכמים לענין כתיבת המגילה, אבל ראה ברכ״י או״ח סתרפ״ח סק״א (ועד״ז כתב בשו״ת אבני נזר או״ח סתקט״ז אות כה. וכן מוכח בתשב״ץ ח״ג סרצ״ז) דסוגיית הירושלמי קאי (גם) על עצם התקנה דימי משתה ושמחה (ומפרשים שלזה כיוון הרמב״ן ריש מגילה), עיי״ש."],["16","16","לכאורה צע״ק שהרי מענה דהחכמים על בקשת מרדכי ואסתר שבירושלמי שם היא לכאורה אותה המענה שבבבלי על בקשת אסתר „קבעוני\" (ועד״ז מענה דמרדכי ואסתר שבירושלמי שם היא אותה המענה דאסתר שבבבלי). ואולי י״ל דבקשת אסתר „קבעוני\" היתה יחד עם הבקשה (דשניהם) „מקבלין .. שני ימים הללו\" (ע״ד מ״ש בברכ״י שם). וכן משמע מפרש״י שמפרש „קבעוני\" (לא רק „לקריי״\", כ״א) גם „ליו״ט\". ויומתק עפמ״ש במנות הלוי (ט, כט) דאגרת הב' היא היא אגרת הא' (דלעיל פסוק כ'), עיי״ש. ודלא כדלעיל הערה 12 (ע״פ המגילת סתרים)."],["17","17","נוסף על הנ״ל הערה 12."],["18","18","לאחרי אגרת הב' שרק אז קבעוה לחובה בכל העולם (מגילה ז, א ובפרש״י)."],["19","19","מג״א ט, לא."]]],[1300161367,"זאָגט דער פסוק<sup data-n=\"19\">19</sup> „כאשר קים עליהם מרדכי היהודי ואסתר המלכה\", דער־נאָך אָבער שטייט<sup data-n=\"20\">20</sup> „ומאמר אסתר קים דברי הפורים האלה ונכתב בספר\" — וי״ל אַז די צוויי פסוקים ריידן וועגן די דריי ענינים הנ״ל:\nאין ערשטן פסוק רעדט זיך וועגן דער תקנה פון ימי הפורים (אלס טעג פון משתה ושמחה גו')<sup data-n=\"21\">21</sup> — ווי ס'איז משמע פון לשון „לקים את ימי הפורים האלה\" (ע״ד לשון הנ״ל פון ירושלמי „מקבלין .. שני ימים הללו\"); און דער־פאָר ווערן דאָ דערמאָנט ביידע •<sup data-n=\"21\">21</sup>: „מרדכי היהודי ואסתר המלכה\", ווייל די תקנה איז געקומען דורך זייער בשותפות'דיקער בקשה, כנ״ל.\nדאָקעגן אין צווייטן פסוק רעדט זיך וועגן דער תקנה פון קריאת המגילה<sup data-n=\"22\">22</sup> און וועגן כתיבת המגילה „ומאמר אסתר קים דברי (הפורים האלה)\" מיינט די תקנה פון קריאת המגילה, און דערפאַר שטייט דאָ „דברי הפורים\" (ניט „ימי\"), וואָס מיינט (ברמז עכ״פ) די רייד — צו ריידן און דערציילן וועגן נס פורים („לקריי״\")<sup data-n=\"23\">23</sup>; „ונכתב בספר\" מיינט דאָס וואָס דער סיפור פון פורים, די מגילה, איז פאַרשריבן געוואָרן אלס איינער פון די „כתובים\" („כתבוני\")<sup data-n=\"24\">24</sup>.\nאון דערפאַר זאָגט דערביי דער פסוק „ומאמר אסתר\" (און עס ווערט דאָ ניט דערמאָנט מרדכי) — ווייל די צוויי ענינים האָט אסתר אליין געבעטן.\nד. מען דאַרף אָבער פאַרשטיין:\nא) ווי קומט עס טאַקע, אַז מרדכי האָט געבעטן ביי די חכמים נאָר וועגן דער תקנה פון ימי הפורים, און ניט וועגן קריאת און כתיבת המגילה ?\nב) נאָכמער: מרדכי איז דאָך געווען אַ חבר סנהדרין<sup data-n=\"25\">25</sup>, ובמילא, איז ער געווען פון די חכמים<sup data-n=\"26\">26</sup> וואָס האָבן מסכים געווען צו די בקשות פון אסתר „קבעוני\" און „כתבוני\" — האָט ער דאָך אוודאי זיך געדאַרפט אויך משתתף זיין אין דער בקשה צוזאַמען מיט אסתר'ן.\nדאַרף מען זאָגן, אַז בּאַ מרדכי גופא זיינען אין דעם געווען צווי אופנים: (א)",[["20","20","שם, לב."],["21","21","ולהעיר שכאן נאמר רק „בזמניהם\", משא״כ לעיל (ט, כז) נאמר „ככתבם (וכזמנם)\", ש(גם) כפשוטו שייך לכתיבת המגילה (כפרש״י שם) — כי כאן נפרטו קריאת וכתיבת המגילה בפסוק שלאח״ז, כדלקמן. •21) ומקדים מרדכי — כי בזה אסתר טפלה אליו, כנ״ל הערה 12."],["22","22","להעיר אשר קריאת המגילה — היא לאו דוקא ב„ימי הפורים האלה\" כי „מגילה נקראת (גם) ביא יב יג'\" ובירוש' (מגילה פ״א ה״א — הובא בשו״ע או״ח ס' תרפ״ח ס״ז וברמ״א) — מתחיל מר״ח."],["23","23","ראה עד״ז הרי״ף לע״י מגילה ז, א (ד״ה שלחה כו' קבעוני כו')."],["24","24","ראה פרש״י מג״א עה״פ: „ומאמר אסתר קים וגו', אסתר בקשה מאת חכמי הדור לקבעה ולכתוב ספר זה עם שאר הכתובים וזהו ונכתב בספר\" (וראה ירושלמי מגילה פ״א ה״ה). וי״ל דמ״ש „לקבעה\" הכוונה להענין ד„קבעוני\" (וזה נלמד מהתחלת הכתוב), ו„לכתוב ספר\" („כתבוני\") נלמד מסיום הכתוב, וע״ז מסיים רש״י „וזהו ונכתב בספר\"."],["25","25","ומהראשים שבהם, וגם לאחרי „שפירשו ממנו מקצת סנהדרין\" — רק „מקצת\" פירשו משא״כ רובם, ונשאר בסנהדרין, אלא שנמנה „בתר חמשה\" (מגילה טז, סע״ב. נת' בארוכה לקמן ע' 373 ואילך)."],["26","26","להעיר שסנהדרין בתקפו כשאינו חסר אפילו אחד (הוריות ג, ב) — ואף כי סנה' צ״ל במקומה דוקא וכאן הרי הי' מרדכי בשושן (עם הגולה אשר הגלתה עם יכני', החרש והמסגר וכו' לבבל (מ״ב כד, יד. גיטין פח, סע״א. פרש״י עה״פ)) — הרי אח״כ חזר לירוש' ולביהמ״ק (עזרא ב, ב. נחמי' ז, ז. שקלים רפ״ה) — פעם אחת או פעמיים (ראה רש״י וחדא״ג מגילה טז, ב)."]]],[1300161368,"ווי מרדכי איז מצד עצמו — דאַרף ניט זיין דער ענין פון „קבעוני\" און „כתבוני\", און דערפאַר האָט ער זיך ניט משתתף געווען אין בקשות אסתר; (ב) ווי ער איז אַ חבר סנהדרין, וואָס דאָס גיט אַן אָרט צו ממלא זיין בקשות אסתר „קבעוני\" און „כתבוני\".\nג) יעדער ענין אין תורה איז בדיוק. דאַרף מען זאָגן, אַז דאָס וואָס די בקשות פון אסתר „קבעוני לדורות\" און „כתבוני לדורות\" ווערן געבראַכט נאָר אין בבלי (ניט אין ירושלמי), און לאידך, די בקשה פון מרדכי ואסתר „מקבלין אתם עליכם שני ימים הללו\" געפינט זיך נאָר אין ירושלמי (און ניט אין בבלי) — איז עס אלץ בדיוק.\nה. װעט מען דאָס פאַרשטיין בהקדים, אַז דאָס וואָס די מגילה איז פאַרשריבן געוואָרן („כתבוני\") איז עס ניט נאָך אַן ענין און פרט נוסף אין נס פורים, נאָר עס איז פאַרבונדן מיטן עצם תוכן הנס;\nווי ס'איז אויך פאַרשטאַנדיק פון דעם וואָס די גמרא זאָגט אין יומא<sup data-n=\"27\">27</sup>: „למה נמשלה אסתר לשחר לומר לך מה שחר סוף כל הלילה אף אסתר סוף כל הנסים\", און די גמרא איז מסביר, אַז אע״פ ד„איכא חנוכה\" (וואָס דער נס חנוכה איז געשען נאָך נס פורים) — ווערט אָבער אסתר פאַררעכנט אלס „סוף כל הנסים\" ווייל אסתר „ניתנה לכתוב\" — דער לעצטער נס וואָס איז פאַרשריבן געוואָרן (תורה שבכתב, תנ״ך) — איז אסתר.\nד.ה. די נסים וואָס ניתנו לכתוב זיינען אַ באַזונדער סוג אין נסים, און אסתר איז דער „סוף\" פון דעם סוג [און דוקא דערפאַר (וואָס אסתר „ניתנה לכתוב\") קען מען איר פאַרגלייכן „לשחר .. סוף כל הלילה\" — אַז „אסתר\" האָט דעם זעלבן תוכן ווי „שחר\"; ווען זי וואָלט ניט געווען פאַר־שריבן, וואָלט מען ניט געקענט מאַכן דעם פאַרגלייך].\nו. דער ביאור בכל זה: דער חילוק בפשטות צווישן מרדכי און אסתר איז זייער אויפטאָן אין דעם מבטל זיין גזירת המן:\nמרדכי האָט זיך (בעיקר) פאַרנומען מיט מעורר זיין אידן תשובה צו טאָן<sup data-n=\"28\">28</sup> אויף די עבירות וואָס האָבן דערפירט צו גזירת המן; אויך דער „כנוס את כל היהודים גו' וצומו גו'\"<sup data-n=\"29\">29</sup> — כאָטש אַז אסתר האָט עס אים געבעטן טאָן, איז אָבער מרדכי געווען דער וואָס האָט דאָס דורכגעפירט בפועל<sup data-n=\"30\">30</sup>;\nדאָקעגן אסתר, וואָס זי איז געווען בבית המלך (ניט צווישן אידן) און „לעת כזאת הגעת למלכות\" — „לא הגעת למלכות אלא בעבור העת הזאת שתושיעי את ישראל\"<sup data-n=\"31\">31</sup>, האָט זיך משתדל געווען און געטאָן כמה פעולות בדרך הטבע אַז אחשורוש זאָל מבטל זיין גזירת המן: זי איז געקומען צו אחשורוש'ן ניט געראָפנערהייט, האָט צוגעגרייט די סעודות פאַר אחשורוש און המן וכו'<sup data-n=\"32\">32</sup>.",[["27","27","כט, א."],["28","28","ראה תרגום שני למג״א קאפיטל ד'. אסת״ר פ״ח, ז. פ״ט, ד. ועוד."],["29","29","מג״א ד, טז."],["30","30","שם, יז."],["31","31","אסתר ד, יד. ובראב״ע. — וראה ג״כ אסת״ר ופרש״י עה״פ אסתר ב, יא."],["32","32","וי״ל שעד״ז הוא החילוק במלחמת עמלק בין משה ויהושע דמשה מרים ידיו וישראל מסתכלין כלפי מעלה ומשעבדין את לבם לאביהם שבשמים (משנה ר״ה ספ״ג) ויהושע פעולתו „צא הלחם בעמלק גו' לפי חרב\" (בשלח יז, ט-יג) •, ובלשון הזהר (ח״ב סה, ב): אמר משה אנא אזמין גרמי להההוא קרבא דלעילא ואנת יהושע זמין גרמך לקרבא דלתתא."]]],[1300161369,"אין אַנדערע ווערטער: מרדכי האָט געטאָן (בעיקר) אין דעם רוחניות'דיקן חלק פון ביטול הגזירה — אויפטאָן דעם ביטול הגזירה למעלה — איז דעריבער זיין התעסקות געווען מיט (און צווישן) אידן; אסתר האָט געטאָן (בעיקר) אין דער השתדלות אין דרכי הטבע (דורך וועלכע דער ביטול הגזירה למעלה איז דורכגעפירט געוואָרן למטה — זי האָט אלץ) געטאָן דורך אחשורוש ביז אַז אחשורוש האָט מבטל געווען די גזירה און נאָכמער — „ונהפוך הוא אשר ישלטו היהודים המה בשונאיהם\"<sup data-n=\"33\">33</sup>.\nז. וי״ל — אין דעם זעלבן אופן ווי מרדכי און אסתר האָבן זיך פאַנאַנדער־געטיילט בנוגע זייערע פעולות צו מבטל זיין די גזירה, אזוי אויך איז דער חילוק ביניהם בנוגע צו דער הדגשה אין דעם נס פורים, זיין אויפטו:\nבּאַ מרדכי איז די הדגשה בנס פורים דער רוחניות'דיקער „נצחון\" פון אידן — דאָס וואָס זיי האָבן תשובה געטאָן און אין אזאַ אופן, ביז אַז דאָס האָט אויפגעטאָן<sup data-n=\"34\">34</sup> דעם „קיימו מה שקבלו כבר\", דער „הדר קבלוה בימי אחשו־רוש\" האָט אראָפגענומען די „מודעא רבה לאורייתא\" פון מתן תורה [און דערפאַר האָט מרדכי געוואָלט אַז פורים זאָל זיין אסור במלאכה<sup data-n=\"35\">35</sup> — וע״ד יום הכפורים, יום התשובה ודנתינת לוחות שניות — עס זאָל זיין אַ טאָג אויף צו אָפגעבן זיך מיט עניני הנפש]<sup data-n=\"36\">36</sup>.\nמשא״כ אסתר האָט מדגיש געווען אין דעם נס די הצלה פון גזירת המן „להשמיד להרוג ולאבד את כל היהודים גו'\"<sup data-n=\"37\">37</sup> — די הצלת הגופים פון אידן, ובלשון הלבוש<sup data-n=\"38\">38</sup>: שהיתה הגזירה להשמיד ולהרוג את הגופות .. ולא את הנפשות .. לכך כשנצלו ממנו כו'.\nח. דערמיט קען מען מסביר זיין וואָס אויך בים זכרון הנס, איז די בקשה פון „מקבלין אתם עליכם שני ימים הללו\" געקומען פון מרדכי און אסתר, און די בקשות „קבעוני\" און „כתבוני\" נאָר פון אסתר אליין — ווייל אין די דריי ענינים דריקט זיך אויס דער זכרון פון נס פורים אויף פאַרשידענע אופנים:\nביים מקיים זיין „ימי הפורים\" — כאָטש אַז דאָס איז פאַרבונדן מיט די מצות מעשיות פון „משתה ושמחה ומשלוח מנות גו' ומתנות לאביונים\" — איז ענינם בפשטות, אַז דורך זיי זאָלן אידן במחשבתם בנפשם קומען צום זכרון הנס.\nדורך דעם ענין פון „קבעוני\" — „לקריי״\", קומט דער זכרון הנס אראָפ אין דיבור, וואָס „עקימת שפתיו הוי מעשה\"<sup data-n=\"39\">39</sup> —\nאָבער פונדעסטוועגן, איז דיבור בלויז אַ „מעשה זוטא\"<sup data-n=\"40\">40</sup>;",[["33","33","מג״א ט, א."],["34","34","שבת פח, א."],["35","35","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">ראה מגילה ה, ב</a>. נת' בתו״א מג״א ק, סע״א ואילך. •) להעיר מהמבואר אשר מרדכי ואסתר הם בדוגמת משה ויהושע. וראה לקמן בפנים ס״י."],["36","36","ראה בכ״ז מגילת סתרים למג״א ט, יט (בסופו)."],["37","37","מג״א ג, יג."],["38","38","או״ח סעתר״ב. הובאה דעתו בט״ז שם סק״ג."],["39","39","דעת ר״י — ב״מ צ, סע״ב. סנהדרין סה, ריש ע״ב. וכן קיי״ל. ועיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מז, א</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">פל״ח (נ, א</a>־ב). פנ״ג."],["40","40","סנהדרין שם, א."]]],[1300161370,"דערנאָך דורך בקשת „כתבוני\" ווערט דער זכרון הנס אראָפגעטראָגן אין „מעשה<sup data-n=\"40\">40</sup> רבא\"<sup data-n=\"41\">41</sup> — דער נס ווערט פאַרשריבן<sup data-n=\"42\">42</sup> בדיו גשמי אויף קלף גשמי וכו'.\nאון דעריבער: ביי מרדכי, וואָס די הדגשת הנס איז ביי אים דער נצחון רוחני, איז אויך אין דעם זכרון הנס נוגע בעיקר דער זכרון במחשבה (רוחניות פון מענטשן) [וכנ״ל אז ער האָט אויך געוואָלט אַז פורים זאָל זיין אסור במלאכה]:\nדאָקעגן ביי אסתר, וואָס די הדגשת הנס איז די הצלה כפשוטה — הצלת הגוף גשמי, איז דעריבער ניט גענוג אַז דער זכרון הנס זאָל זיין אין מחשבה, נאָר ער דאַרף בעיקר אראָפקומען אין „עשי'\" (אין „מעשה זוטא\" און דערנאָך אין „מעשה רבא\").\nט. דאָס וואָס מרדכי האָט נאָר געבעטן „מקבלין אתם עליכם שני ימים הללו\" (ניט „קבעוני\" און „כתבוני\") — איז דאָס ווי מרדכי איז מצד מצב ומעלת עצמו, וואָס דאָן זעט ער אויך זיין דור (וואָס ער איז זייער פרנס וראש ווי זיי שטייען ויונקות וחיות פון עם<sup data-n=\"43\">43</sup> ווי זיי זיינען מצד נשמתם ורוחניותם — און מצד זייער רוחניות איז גענוג אַז דער זכרון הנס זאָל זיין במחשבה, ס'איז ניט אזוי נוגע אַז עס זאָל אראָפקומען במעשה, כנ״ל;\nבשעת אָבער ער זיצט אין סנהדרין און מען ברענגט אהין דעם דבר הקשה — און ענין הסנהדרין איז צו פסק'נען דעם דין למעשה, וואָס צוליב דעם דארפן זיי זיך אראָפלאָזן צו אידן און זען זייער מצב אין עולם הגשמי, מצד גופם •<sup data-n=\"43\">43</sup> (און דער פסק הלכה דארף דורכגעפירט ווערן אין מעשה<sup data-n=\"44\">44</sup> — דאָן זעט ער אידן מצד גופם, וואָס מצד דעם דארף דער זכרון הנס אראָפקומען אין מעשה ממש, ווייל דוקא דאָס דער־נעמט דעם גוף בתכלית<sup data-n=\"45\">45</sup>.\nיוד. דער ענין הנ״ל אין סגנון פון תורת החסידות:\nדער חילוק צווישן מדריגת מרדכי און מדריגת אסתר: מרדכי איז ענינו — „יסוד אבא\"<sup data-n=\"46\">46</sup>, וואָס מצד „אבא\" (ספירת החכמה) איז נוגע דער ענין ה„אור\"<sup data-n=\"47\">47</sup>; אסתר איז ספירת המלכות, און אין דעם גופא — ווי מלכות איז יורדת אין עולמות בי״ע<sup data-n=\"48\">48</sup> [ווי ס'איז מרומז אין איר נאָמען „אסתר\" — פון לשון<sup data-n=\"49\">49</sup> „ואנכי",[["41","41","עולם העשי' ממש — עיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל״ח (נא, א</a>) ד„גוף המצוה עצמם ממש הן ב' מדרגות כו'\", עיי״ש. שם פל״ה (מה, א)."],["42","42","אפילו לפי המובא לעיל (הערה 5) שגם לצורך קריאת המגילה („קבעוני\") צ״ל כתיבה — הרי אי״ז ענין הכתיבה (ועשי') מצ״ע, כ״א הכשר או עכ״פ פרט בהקריאה (דיבור). ובדוגמת המבואר בפנים לענין „ימי הפורים\", שהמצות דפורים הן בכדי שעי״ז יבוא לזכרון הנס במחשבה."],["43","43","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ״ב</a>. — וע״ד ביאור הענין דרצון יצחק לברך את עשו מפני דרישא דעשו בעטפי' דיצחק (תו״א תולדות ד״ה ראה ריח בני). •43) להעיר ממה שאמר דוד (ברכות ד, א) „ידי מלוכלכות בדם ובשפיר ובשליא כדי לטהר אשה לבעלה\"."],["44","44","להעיר מב״ב קל, ב וברשב״ם. המשך תרס״ו ע' שצ ואילך."],["45","45","ועי״ש שבמצות שבמעשה ובדיבור — הרי הם העיקר וכו', כיון שצ״ל בירור הגוף וחלקו בעולם דוקא (<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז</a> ורפל״ח)."],["46","46","פע״ח שער יט פ״ה."],["47","47","ובפרט ע״פ הידוע שגם הכלי דחכמה הוא בבחי' אור (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380673\" data-slug=\"likkutei-torah\" data-id=\"4001380673\">לקו״ת מטות פז, סע״ד</a>. אוה״ת וארא ע' קנ. ובכ״מ)."],["48","48","ראה מאו״א מערכת אל״ף אות קמד. הובא באוה״ת מג״א ד״ה ויהי אומן. וראה ד״ה זה דשנות תרע״ט (קה״ת תשכ״ד. ובסה״מ תרע״ט) ותשכ״ד."],["49","49","וילך לא, יח."]]],[1300161371,"הסתר אסתיר\"<sup data-n=\"50\">50</sup> — תכלית ההעלם וההסתר<sup data-n=\"51\">51</sup>], וואָס מצד ספירת המלכות איז נוגע דער ענין ה„כלים\" •<sup data-n=\"51\">51</sup>.\nדער חילוק צווישן דעם אופן ווי נס פורים ווערט דערהערט מצד דעם ענין ה„אור\" און ווי ער איז נרגש מצד ה„כלים\":\nדער נס פורים, זייענדיק פון די נסים המלובשים בטבע<sup data-n=\"52\">52</sup>, האָט אין זיך צוויי קצוות: פון איין זייט, וויבאלד אז דער נס איז אנגעטאָן אין טבע אין אַן אופן „שלא הי' דבר נראה לעין שהוא למעלה מהטבע\"<sup data-n=\"53\">53</sup>, איז מובן, אַז ער איז פאַר־בונדן מיט דעם אור אלקי וואָס קומט אראָפּ בהתלבשות אין וועלט<sup data-n=\"54\">54</sup>;\nפון דער צווייטער זייט, וויבאלד אז דאָס איז אַן ענין פון נס וגילוי אלקות (ביז — „נראה בחוש שכל הסבות היו רק למעלה מהטבע\"<sup data-n=\"55\">55</sup>, איז מובן, אַז דער שורש פון דעם נס איז פון דעם אור אלקי וואָס איז העכער פון טבע<sup data-n=\"56\">56</sup>; און נאכמער: דאָס גופא וואָס דער נס קען אראָפקומען אין טבע איז אַ באַ־וויז, אַז בשרשו איז ער העכער אויך פון די נסים גלויים<sup data-n=\"57\">57</sup>, וואָס דערריבער איז ער ניט „מוגבל\" אין דער הגבלה פון העכער־פון־טבע און ווערט נמשך אין טבע גופא.\nאון דאָס איז דער חילוק צווישן דעם נס פורים ווי ער איז מצד „אור\" און ווי ער איז מצד „כלים\": דער ענין ה„אור\" טוט אויף דעם „גילוי\" ונס — דער נס ווי ער איז מצד שרשו ומקורו; דער ענין פון די „כלים\" איז צו אראָפּטראָגן דעם נס אין העלם והסתר ולבושי הטבע, וואָס אין דעם פירט זיך אויס דער מכוון פון נס<sup data-n=\"58\">58</sup> — צו איבערמאַכן דעם העלם פון טבע, אַז מ'זאָל זען ווי טבע ווערט געפירט פון אויבערשטן אליין.\nיא. און דאָס איז דער חילוק צווישן מרדכי און אסתר:\nמצד מרדכי, ענין ה„אור\", איז דער עיקר הדגשה פון נס פורים (ניט אין זיכוך הטבע, נאָר) אין התגלות האור — דאָס וואָס דורך דעם נס ווערט נתגלה דער בלי גבול האמתי ית' (אַז עס דער־גרייכט ביז למטה למטה, אין הנהגת הטבע):\nאון דערריבער איז אויך אין דעם זכרון הנס ניט אזוי נוגע אַז עס זאָל אראָפ־קומען אין מעשה — עס איז גענוג וואָס דער זכרון הנס דריקט זיך דירקט אויס אין די מצות מעשיות פון פורים, אָבער דער זכרון הנס גופא קען בלייבן במחשבה ורוחניות:",[["50","50","חולין קלט, ב."],["51","51","כידוע פי' הבעש״ט (תולדות יי״ר״פ בראשית) ב„הסתר אסתיר\". נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071041\" data-slug=\"likkutei-sichot\" data-id=\"1300071041\">לקו״ש ח״ז ע' 41</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091193\" data-slug=\"likkutei-sichot\" data-id=\"1300091193\">ח״ט ע' 193</a> ואילך. •51) ובפרט שמל' מצ״ע כלי — ולית לה מגרמא כלום (זח״א רמט, א. שם בהשמטות רנא, ב. ועוד)."],["52","52","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370418\" data-slug=\"torah-or\" data-id=\"3901370418\">תו״א מג״א (צג, א</a>. שם, סע״ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">ק, א</a>). ובכ״מ."],["53","53","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370420\" data-slug=\"torah-or\" data-id=\"3901370420\">תו״א צג, סע״ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">ק, א</a>."],["54","54","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">תו״א מג״א (ק, א</a>) „שהנסים שבהתלבשות הם ע״י אות ה' אחרונה דשם הוי״ה\". וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940148\" data-slug=\"or-hatorah-hb\" data-id=\"8159940148\">אוה״ת אחרי (ס״ע תקסד</a>) בשם הרמב״ן (לך יז, א. וארא ו, ב) דנסים המלובשים בטבע הם משם שד״י. וראה פיה״מ מהדו״ב פקל״ט (צב, ריש ע״ב)."],["55","55","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370421\" data-slug=\"torah-or\" data-id=\"3901370421\">תו״א צג, רע״ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">ק, א</a>."],["56","56","ראה אוה״ת אחרי שם — דנסים המלובשים בטבע הם משם שד״י וטבע עצמו משם אלקים."],["57","57","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370410\" data-slug=\"torah-or\" data-id=\"3901370410\">תו״א מג״א צא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">ק, א</a>. אוה״ת מג״א ב״שלו. ובכ״מ."],["58","58","כידוע דנס מלשון הרמה (פרש״י יתרו ב, יז. וראה סדור מד, סע״ב. פיה״מ מהדו״ב פקל״ט. אוה״ת בשלח ד״ה ויבן. ועוד), רוממות הטבע. וראה סה״מ תרע״ח (ע' פט ואילך) שזה נעשה בעיקר ע״י הנסים המלובשים בטבע, עיי״ש."]]],[1300161372,"[און דערפאַר ווערט דער ענין געבראַכט אין ירושלמי — וואָס אין תורה גופא איז עס דער ענין ה„אור\"<sup data-n=\"59\">59</sup> (מ'געפינט גלייך די ריכטיקע סברא און תירוץ וכו' ווי איינער וואָס זעט אַ זאַך אין דער ליכטיקייט)].\nמצד אסתר אָבער — ענין ה„כלים\", „הסתר אסתיר\" — איז דער עיקר הדגשה אין נס פורים דאָס וואָס דורך דעם ווערט איבערגעמאַכט דער הסתר און חושך פון טבע<sup data-n=\"60\">60</sup>; דערפאַר איז אויך אין דעם זכרון הנס נוגע, אַז עס זאָל אראָפקומען אין (עולם ה)עשי'<sup data-n=\"61\">61</sup> — אין קריאה וכתיבה, וואָרום דוקא דורך דעם פירט זיך אויס דער מכוון פון דעם נס, אַז טבע גופא זאָל מאיר זיין<sup data-n=\"62\">62</sup>.\n[און דערפאַר ווערט דער ענין געבראַכט אין בבלי, וואָס „במחשכים הושיבני .. זה תלמודה של בבל\"<sup data-n=\"63\">63</sup> — עס איז דער ענין פון „בירור החושך\"<sup data-n=\"59\">59</sup> (אין תורה גופא)].\nיב. עפ״י כהנ״ל וועט מען אויך פאַר־שטיין דעם פאַרגלייכן פון „אסתר\" צו „שחר\" — „מה שחר סוף כל הלילה אף אסתר סוף כל הנסים\", און ווי דאָס איז פאַרבונדן מיט דעם וואָס אסתר „ניתנה לכתוב\":\nדאָס וואָס די גמרא פאַרגלייכט „סוף כל הלילה\" צו „סוף כל הנסים\" — דלכאורה זיינען „נס\" און „לילה\" הפכיים בתכלית (ווי דער מהרש״א •<sup data-n=\"63\">63</sup> פרעגט) — איז עס ווייל, ווי גערעדט פריער (סוף סעיף יוד), דער תכלית פון אַ נס איז אַז טבע גופא זאָל זיך ענדערן, אַז אין טבע (וואָס מצ״ע<sup data-n=\"64\">64</sup> איז עס אַן ענין פון „לילה\" וחושך) זאָל זיך אַנ־הערן דער אור וגילוי פון אלקות;\nאון „אסתר\" איז „סוף כל הנסים\", זי איז דער סוף און תכלית פון אלע נסים — אראָפצוטראָגן דעם נס און גילוי אלקות אין העלם והסתר העולם; ווייל זי פועל'ט (ניט נאָר אין דעם חושך פון עוה״ז וואָס האָט אַ שייכות (— איז „בסמיכות\") צו „אור\", די איידעלע ענינים פון עוה״ז, נאָר) אין „סוף כל הלילה\" — אין תכלית החושך והעלם והסתר אסתיר פון עוה״ז וואָס האָט ניט קיין שייכות צו „אור\" [אזוי ווי „סוף כל הלילה\" כפשוטו, וואָס דוקא דאָן (פאַרן",[["59","59","ראה בארוכה שערי אורה ד״ה בכ״ה כסלו פנ״ד ואילך. המשך תרס״ו ע' צ ואילך. ד״ה אמר רבא תש״ח פי״א (ושם, דתלמוד ירושלמי הוא בחי' חכמה — ע״ד בחי' מרדכי כנ״ל, ותלמוד בבלי הוא בחי' בינה — שהיא התחלת הכלים (ראה לעיל הערה 47))."],["60","60","ובזה יובן שינוי לשון הכתוב — בנוגע ל„קים את ימי הפורים גו'\" נאמר „מרדכי היהודי ואסתר המלכה\" אבל בנוגע ל„דברי הפורים גו' ונכתב בספר\" נאמר „ומאמר אסתר\" (סתם): הענין ד„ימי הפורים\" שייך ל„אור\", והשתתפות אסתר בזה היא מצד מלכות כמו״ש במקומה באצילות, ולכן נאמר שם „אסתר המלכה\" — דתואר „מלכה\" מורה על מלכות בגילוי ולא כשהיא בגלות בעולמות בי״ע. משא״כ „קבעוני\" ו„כתבוני\" שייך ל„כלים\", ובמלכות גופא — כמו״ש יורדת ומסתתרת בבי״ע, ולכן נאמר „אסתר\" (סתם)."],["61","61","וגם בנוגע להתקנה ד„ימי הפורים\" — הרי ע״י אסתר דוקא נקבע חובה בכל העולם ולכל הדורות [שלכן נאמר באגרת הב' (ט, כט) „ותכתוב אסתר גו'\" (ומקדימה למרדכי) • — ראה ראב״ע שם, כח. ל. מנות הלוי עה״פ]."],["62","62","עיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> פל״ז ורפל״ח שדוקא ע״י דבור ומעשה נשלמת כוונת הבריאה ד„דירה בתחתונים\". •) נוסף על הנ״ל הערה 12."],["63","63","סנהדרין כד, א. ראה ר״ח שם. •63) חדא״ג יומא שם."],["64","64","ובלשון חז״ל (ב״ר פ״ב, ג) „העולם מתנהג באפלה תבא האורה כו' זה אברהם כו'\"."]]],[1300161373,"עלות השחר) איז דער חושך הלילה מיט מער התגברות ווי במשך דער נאכט<sup data-n=\"65\">65</sup>].\nאון עפ״ז איז פאַרשטאַנדיק וואָס דוקא די נסים וואָס זיינען אין סוג פון „ניתנה לכתוב\" קען מען פאַרגלייכן צו „לילה\", ובפרט צו „סוף כל הלילה\": דאָס וואָס ביי די נסים איז דער זכרון הנס אראָפגעטראָגן געוואָרן אין „כתיבה\" ועשי' — וואָס אין עוה״ז, וואָס איז עס סוג הדומם<sup data-n=\"41\">41</sup>, סוף כל המדריגות פון עולם העשי'<sup data-n=\"41\">41</sup> — איז עס ווייל די נסים איז ענינם צו איבערמאַכן דעם „לילה\", ובפרט „סוף כל הלילה\"<sup data-n=\"66\">66</sup>.\nיג. דאָס איז אויך דער ביאור וואָס „נמשלה אסתר לשחר\": דער אור השחר, וואָס איז בוקע דעם חושך פון „סוף כל הלילה\", ווייזט אויף דעם אור וואָס ווערט „נמשך דוקא מן החושך שקדמו\" [דאָס וואָס מ'איז הפך מהחושך גופא לאור]; ווי ס'איז אויך מרומז אין ווארט „שחר\", וואָס איז פון „ל' שחרות וקדרות וחושך\"<sup data-n=\"67\">67</sup>;\nאון אזוי אויך אין ספירות: „(אילת ה)שחר דא כנסת ישראל\"<sup data-n=\"68\">68</sup> — ספירת המלכות, און וויבאלד אז „שחר סוף כל הלילה\", איז מובן, אַז דאָס איז ספירת המלכות\n— ניט ווי זי איז במקומה אין אצילות, אָדער אפילו ווי זי ווערט „עתיק לבריאה\" — וואו דער ענין המלכות איז בגילוי, נאָר —\nווי זי איז יורדת אין דעם העלם והסתר פון עולמות בי״ע —\nאויך איבערמאַכן דעם העלם לאור (ע״ד ווי גערעדט פריער בנוגע צו אסתר<sup data-n=\"69\">69</sup>).\nיד. דאָס וואָס „אסתר\" מאַכט איבער דעם העלם והסתר העולם — כאָטש אַז ענינה איז „הסתר אסתיר\" — איז עס ניט נאָר בכחו של מרדכי (וואָס ענינו איז אור וגילוי כנ״ל בארוכה), נאָר אויך ווייל אסתר גופא, איז בפנימיותה, העכער לגמרי פון דעם הסתר;\nוואָס דאָס איז דער פירוש הפנימי<sup data-n=\"70\">70</sup> אין פסוק<sup data-n=\"71\">71</sup> „הדסה היא אסתר\": (אויך) אין דער ירידה אין העלם והסתר העולם („אסתר\") איז פאַראַן די בחי' „הדסה\" (אלו הצדיקים •<sup data-n=\"71\">71</sup> וואָס ווייזט אויף פנימיות המלכות וואָס איז מיוחד מיט די ספירות שלמעלה ממנה.\nאון דאָס איז אויך די הוראה בעבודת כאו״א: אויך ווען אַ איד געפינט זיך אין אַ מצב פון „הסתר\" וחושך, דארף ער דערפון ניט נתפעל ווערן — ואדרבה: וויבאלד אז בפנימיותו איז ער העכער פון דעם הסתר, איז בכחו ניט נאָר צו בייקומען דעם הסתר, נאָר נאָכמער — צו איבערמאַכן דעם הסתר גופא לאור.",[["65","65","סה״מ אתהלך לאזניא ס״ע קג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830044\" data-slug=\"or-hatorah-hb\" data-id=\"8158830044\">אוה״ת במדבר ע' מד</a>."],["66","66","וי״ל שזהו הטעם שנס חנוכה לא נכתב — כי נס חנוכה שייך (בעיקר) לנשמה ורוחניות (לבוש וט״ז דלעיל הערה 38)."],["67","67","ראה בכ״ז אוה״ת במדבר שם."],["68","68","זח״ג כא, ב. שם כה, ב."],["69","69","במאו״א שבהערה 48 איתא שאסתר בחי' מלכות „המסתתרת בראש הבריאה\". וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370414\" data-slug=\"torah-or\" data-id=\"3901370414\">תו״א מג״א (צב, א</a>) שהוא „עתיק דבריאה\" (ועיי״ש הדיוק ד„עתיק\" דוקא). אבל בד״ה ויהי אומן תרע״ט (קרוב לסופו) ד„הדסה היא בחי' פנימיות המל' כמו שהיא באצי'\" (וכמו שנעשית עתיק לברי' כו'), ו„אסתר היינו בחי' מל' היורדת בריבוי ההעלמות וההסתרים דבי״ע כו'\". ויל״ע בתיווך המאמרים."],["70","70","מאמרי ד״ה ויהי אומן דלעיל הערה 48."],["71","71","מג״א ב, ז. •71) מגילה יג, א."]]],[1300161374,"טו. ווי גערעדט פיל מאָל, זיינען אלע ענינים פון פנימיות התורה דאָ, ברמז עכ״פ, אין נגלה דתורה. און אזוי אויך אין ענינינו:\nדער ענין הנ״ל אין עבודת כאו״א — ווי אַ איד איז בפנימיות העכער פון „הסתר\"<sup data-n=\"72\">72</sup> — איז דער אלטער רבי מרמז אין זיין שו״ע (במהדורא תניינא) אין אנהויב פון הל' השכמת הבוקר, אין דעם דין פון „אני מעורר השחר ואין השחר מעיר אותי\" •<sup data-n=\"72\">72</sup>;\nאון דאָס איז פאַרבונדן מיט אַ תמי' אין ט״ז און אַ שינוי אין אלטן רבי'נס שו״ע פון מהדורא קמא צו מהדורא תניינא — וואָס וועט וועלן ווערן פאַר־שטאַנדיק לויטן ביאור פנימי (דלעיל סעיף יג) אין מדריגת „שחר\".\nטז. דער טור ברענגט אראָפ (אין ערשטן סימן פון אורח חיים): „צריך האדם להתגבר כארי לעמוד בבקר לעבודת בוראו .. שתהא אתה מעורר השחר ולא יהא הוא מעירך כמו שאמר דוד ע״ה .. אני מעיר השחר ואין השחר מעיר אותי\"; אין שו״ע<sup data-n=\"73\">73</sup> אָבער, ברענגט דער מחבר נאָר דעם אנהויב — „שיהא הוא מעורר השחר\", און ניט דעם סיום („ואין השחר מעיר אותי\")<sup data-n=\"74\">74</sup>.\nאיז מסביר דער ט״ז<sup data-n=\"75\">75</sup>: שחר מיינט כנסת (קדושת) ישראל<sup data-n=\"76\">76</sup>, די קדושה וואָס איז שורה אין אידן<sup data-n=\"77\">77</sup>; און אין דעם זיינען דאָ צוויי אופנים: „אני מעיר השחר\" — די התעוררות מלמטה אויף צוקומען צו „שחר\"; „שחר מעיר אותי\" — די התעוררות מלמעלה, פון בחי' „שחר\".\nאון דאָס האָט געמיינט דוד „ואין השחר מעיר אותי\": די „התעוררות שלו מלמטה גדולה כ״כ שא״צ לסיוע התעוררות של מעלה\". און וויבאלד עס איז אַ מדריגה וואָס איז שייך נאָר „לדוד וכיו״ב\" ברענגט עס ניט דער מחבר אין שו״ע.\nאיז לכאורה תמוה ביותר: ווי קען מען זאָגן אַז עס איז דאָ אַזאַ וואָס „א״צ לסיוע התעוררות של מעלה\" — ס'איז דאָך „אלמלא הקב״ה עוזרו אין יכול לו\"<sup data-n=\"78\">78</sup>, און יעדן אידן, אפילו אַ צדיק גמור זאָגט מען „אל תאמין בעצמך\"<sup data-n=\"79\">79</sup> ?\nיז. דער אלטער רבי אין מהדו״ק ברענגט אויך אראָפ (ווי דער מחבר) נאָר דעם ענין פון „שיהא הוא מעורר השחר\" — אָבער אין מהדורא תניינא זאָגט ער: „שיהא הוא מעורר השחר כמ״ש<sup data-n=\"80\">80</sup> אעירה שחר אני מעורר השחר ואין השחר מעיר אותי וזו מדה בינונית\".\nאיז ניט מובן: וויבאלד אַז אויך מהדורא תניינא איז אַ טייל פון שו״ע — אַ דבר השווה לכל נפש — פאַרוואָס",[["72","72","ובל' התניא ספכ״ד: (וגם בשעת החטא) הייתה באמנה אתו (ית') — ע״ד הנאמר באסתר (מג״א ב, כ). •72) לשון אדה״ז. מטור או״ח סימן א' (ושם: אני מעיר). והוא ע״פ ירושלמי ברכות פ״א ה״א. מדרש תהלים מזמור כב. מזמור קח. ועוד. הובא בפרש״י תהלים נז, ט."],["73","73","שם סעיף א'."],["74","74","ולהעיר גם מיל״ש לתהלים נז שם: „אני מעורר את השחר\" (ותו לא). ועד״ז הוא בפרש״י תהלים קח, ג. ברכות ד, א ד״ה אעירה שחר."],["75","75","סק״ב."],["76","76","ראה פרמ״ג שם משבצות זהב סק״ב. יד אפרים שם."],["77","77","ראה יד אפרים שם."],["78","78","קידושין ל, ב. סוכה נב, ריש ע״ב."],["79","79","אבות פ״ב מ״ד. ברכות כט, א."],["80","80","תהלים נז, ט. קח, ג."]]],[1300161375,"ברענגט דאָרט דער אלטער רבי דעם ענין פון „ואין השחר מעיר אותי\", וואָס איז שייך נאָר „לדוד וכיו״ב\" ?\nנאָכמער איז די תמי': פון דעם המשך הלשון פון אלטן רבי'ן איז משמע, אַז די וואָרטער „וזו מדה בינונית\" באַציען זיך [ניט נאָר צום כללות הדין וועגן קימה „קודם אור הבוקר\" (וואָס קומט ניט צו דעם וואָס ס'איז „ראוי לכל ירא שמים כו' לקום בחצות הלילה\"<sup data-n=\"81\">81</sup>, נאָר]\nאויך צום ענין פון „ואין השחר מעיר אותי\". ד.ה. עס איז שייך דוקא ניט צו יחידי סגולה, נאָר אדרבא — „זו מדה בינונית\".\nיח. ע״פ הנ״ל (סעיף יג) אין מדריגת „שחר\" — אַז דאָס איז „כנסת ישראל\" (מלכות) ווי זי איז יורד אין דעם העלם והסתר פון עולם — קען מען זאָגן: דאָס וואָס דער ט״ז זאָגט „א״צ לסיוע התעוררות של מעלה\" מיינט ער בלויז אַז ער דארף ניט אנקומען צו דעם סיוע וואָס נעמט זיך פון בחי' „שחר\", ער דארף אָבער אנקומען צו אַ סיוע פון העכערע מדריגות<sup data-n=\"82\">82</sup> אין אלקות<sup data-n=\"83\">83</sup>.\nדער ביאור בזה: אין דעם סיוע מלמעלה י״ל אַז עס זיינען פאַראַן, בכללות, דריי מדריגות:\nא) דער סיוע אַז מען זאָל ניט נכשל ווערן אין תאוות איסור ר״ל — און דער סיוע איז פון בחי' „שחר\", ווי מלכות קומט אראָפ אין „סוף כל הלילה\", דער אָרט פון תכלית ההסתר פון עוה״ז.\nב) דער סיוע אַז מען זאָל זיך אויס־היטן פון תאוות היתר — און דאָס קומט פון מלכות ווי זי ווערט „עתיק לבריאה\" [וואָס כאָטש אַז אויך די בחי' איז אַן ענין פון „לילה\" (ירידה אין עולמות בי״ע) — און עד״ז אין עבודה, קומט עס דאָך צו פאַרהיטן פון תאוות — איז עס אָבער ניט „סוף כל הלילה\": דער סיוע איז אויף תאוות היתר].\nג) דער סיוע אויף קענען עולה זיין ממדריגה למדריגה אין קדושה גופא — און דאָס קומט פון מלכות דאצילות ווי זי איז במקומה אין אצילות, וואָס דאָן ווערט זי אנגערופן „יום\".\nיט. די דריי ענינים הנ״ל זיינען מתאים, בכללות, צו די דריי מדריגות אין עבודה: עבודת הצדיק, הבינוני און — הרשע, ווי מדריגתם ווערט ערקלערט אין תניא:\nאַ צדיק איז אינגאַנצן ניט שייך צו ענינים פון תאוות, וואָס נעמען זיך פון נפש הבהמית<sup data-n=\"84\">84</sup>, און זיין עבודה באַ־שטייט אין עלי' אין קדושה גופא; ביי אַ בינוני איז אָפגעגרעגט צו טאָן אַן עבירה ר״ל („לא עבר עבירה כו' ולא יעבור לעולם\"<sup data-n=\"85\">85</sup>, ער דארף אָבער האָבן אַ מלחמה צו אויסהיטן זיך פון תאוות היתר; אַ רשע דארף האָבן אַ מלחמה ניט",[["81","81","לקמן סעיף ב'."],["82","82","כדיוק לשון חז״ל „אלמלא הקב״ה עוזרו כו'\". ועייג״כ בארוכה אוה״ת מג״א ד״ה ובהגיע. ולהעיר מתר״ש ע' 86: לפי מעשה זו לא הי' צריך לסיוע כלל כו'."],["83","83","וכמובן בפשטות שאינו דומה הסיוע מלמעלה בקומו משנתו בתחלת היום — להסיוע לאחרי תפלתו ובקשתו עד״ז בעבודת היום."],["84","84","<a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא</a> פ״ו. ועיי״ש פי״ג (יח, סע״ב) „לא נתבטל לגמרי כו' אלא בצדיק כו'\"."],["85","85","שם רפי״ב. ועיי״ש יז, ריש ע״ב: בדבר איסור אינו עולה בדעתו לעשות האיסור בפועל ממש כו'. ומ״ש ברפי״ג בענין אלמלא הקב״ה עוזרו כו' הוא בעיקר בענין ההרהורים כו', עיי״ש [ו„להתפשט באברי הגוף כו'\" — י״ל שקאי רק על תאוות היתר]. והחילוק בפשטות — כי ההרהורים באים מאליו (וכ<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא ספי״ב</a>), משא״כ דיבור ומעשה שהם מרצונו של האדם."]]],[1300161376,"צו דורכפאַלן אין איסור — און אויף דעם דארף ער אנקומען צום סיוע מלמעלה פון בחי' „שחר\".\nוי״ל אז דאָס איז אויך דער ביאור אין אלטן רבי'נס שו״ע:\nמצד נגלה דתורה, איז אַ בינוני דער וואָס איז „מחצה על מחצה\", דער וואָס האָט מער פון מחצה — „רוב זכיות\" איז אַ צדיק<sup data-n=\"86\">86</sup> — און דערריבער, אין מהדורא קמא וואָס איז געשריבן געוואָרן לויט דער הכרעה פון „גמרא\" און „פוסקים\"<sup data-n=\"87\">87</sup>, ברענגט ניט דער אלטער רבי דעם ענין פון „ואין השחר מעיר אותי\" (אַז מ'דארף ניט אנקומען צום סיוע פון „שחר\", וואָס היט אָפ פון עובר זיין אַן עבירה).\nמשא״כ אין מהדו״ת האָט דער אלטער רבי מכריע געווען „כהמקובלים\"<sup data-n=\"88\">88</sup> — און מצד ע״פ (הביאור אין) פנימיות התורה איז אויך אַ בינוני ניט שייך צו עובר זיין אַן עבירה (ובמילא דארף ער ניט דעם סיוע פון בחי' „שחר\"); און דערפאַר ברענגט דאָרט דער אלטער רבי אויך דעם ענין פון „ואין השחר מעיר אותי\" און איז מסיים „וזו מדה בינונית\" (וואָס דערמיט איז ער מרמז צו דער בחי' פון בינוני<sup data-n=\"89\">89</sup>).\nאון דאָס גופא שטעלט אריין דער אלטער רבי אין שו״ע אלס אַ פסק דין וואָס איז שווה לכל נפש — ווייל נאָכ־דעם ווי דער אלטער רבי האָט מגלה געווען אין תניא די אמתית ענין הבינוני, איז דאָך דאָס געווארן „מדת<sup data-n=\"90\">90</sup> כל אדם ואחרי' כל אדם ימשוך שכל אדם יכול להיות בינוני בכל עת ובכל שעה\".\nכ. דער ענין הנ״ל מאָנט דער אלטער רבי גלייך בהשכמת הבוקר, אפילו פאַר אמירת מודה אני. ד.ה. אויך ווען ס'איז נאָך ניטאָ קיין גילוי אור בנפשו, ס'איז בײ אים נאָך אַ מצב פון „חושך\", מאָנט זיך פון אים „להתגבר על יצרו כארי\"<sup data-n=\"91\">91</sup> באופן אַז ער דארף ניט אנקומען אפילו צו סיוע מלמעלה אויף ניט עובר זיין אַן עבירה ר״ל („אין השחר מעיר אותי\").\nווי קען מען טאַקע מאַנען ביי אַ אידן אזאַ דרגא ומצב ? איז דער ביאור אין דעם: דאָס וואָס אַ איד איז אין אַ מצב פון חושך איז עס נאָר מצד זיין חיצוניות; בפנימיות — איז ער העכער פון דעם הסתר (וכנ״ל סעיף יד בענין „הדסה היא אסתר\"):\nואדרבה — דער מצב פון „הסתר\" רופט אַרויס די פנימיות הנשמה ביתר שאת ויתר עז, וואָס דריקט זיך אויס אין דעם כח המסנ״פ וואָס איז דאָ בא יעדן אידן<sup data-n=\"92\">92</sup>; און ווי ס'איז געווען בימי אסתר",[["86","86","ראה רש״י ותוס' ר״ה טז, סע״ב. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ״א</a>: והא דאמרינן בעלמא כו'."],["87","87","ראה שו״ע אדה״ז או״ח ס' כה סכ״ח."],["88","88","ראה שער הכולל בתחילתו (נדפס גם בהוספות לשו״ע אדה״ז או״ח (קה״ת) ח״א לא, א [קפג, א]. לב, ב [קפד, ב])."],["89","89","ועפ״ז מובן המשך ב' הסעיפים: בסעיף א' מדבר ע״ד מדרי' הבינונים כבפנים, ובסעיף ב' — „ראוי לכל ירא שמים כו' לקום בחצות הלילה כו'\" — עבודה שלמעלה מזו המוכרחת בבינונים (ראה קונט' התפלה פ״א). וגם זה מביא בשו״ע, עדמ״ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא ספי״ד</a>: אף אעפ״כ כו' לקיים את השבועה שמשביעים תהי צדיק כו'. וראה לקמן הערה 97."],["90","90","<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא רפי״ד</a>. וראה ד״ה ואלה המשפטים תשל״ח פ״ה ובהערה 38 שם (סה״מ — מלוקט ח״א ע' שט)."],["91","91","לשון אדה״ז מהדו״ת שם."],["92","92","ראה בארוכה ד״ה ויהי אומן תרע״ט (ותשכ״ד). ושם, דבחי' פנימיות הנפש שמאיר בזמן הבית הוא „אור הנשמה\", ובזמן הגלות — „כח הנשמה\", שהו״ע המסנ״פ, עיי״ש."]]],[1300161377,"אַז במשך „כל השנה כולה\"<sup data-n=\"93\">93</sup> זיינען אידן געווען „בבחי' מסנ״פ ממש בכל יום ובכל עת ובכל שעה\"<sup data-n=\"94\">94</sup>, ווייל מסנ״פ נעמט דורך דעם מענטשן אינגאַנצן, אין אלע זיינע כחות און „אפילו בלבושי' החיצונים\"<sup data-n=\"95\">95</sup>:\nאון עד״ז בעבודת כאו״א: דוקא דער מצב פון „חושך\" רופט אַרויס פנימיות נפשו נאָך מער ווי אַ מצב פון „גילוי אור\"; און דאָס דריקט זיך אויס אין קבלת עול פון עצם הנשמה וואָס נעמט אים דורך אינגאַנצן, וואָס מצד דעם<sup data-n=\"96\">96</sup> — „יכול להיות בינוני בכל עת ובכל שעה\"<sup data-n=\"97\">97</sup>.\n(משיחות פורים וש״פ תשא תשכ״ד)",[["93","93","לשון אדה״ז — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו״א צז, א</a> (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370538\" data-slug=\"torah-or\" data-id=\"3901370538\">ושם קכ, ד</a>: כמעט משך שנה). נת' בד״ה וקבל היהודים תשל״ח (סה״מ — מלוקט שם ע' שיז ואילך) פ״ג."],["94","94","לשון אדה״ז — תו״א שם."],["95","95","<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא ספי״ט</a>. וראה ד״ה וקבל שם."],["96","96","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310030\" data-slug=\"tanya\" data-id=\"3401310030\">תניא ספכ״ה</a>: תלוי בזה .. מסנ״פ .. בזה יוכל לעמוד נגד יצרו לנצחו תמיד בכל עת ובכל שעה."],["97","97","עפ״ז י״ל ברמז המשך דב' הסעיפים בשו״ע אדה״ז שם: בסעיף א' מדובר במדרי' בינוני (כנ״ל) שמכיון שהוא במצב דחושך צריך לעורר „כח הנשמה\" (כנ״ל הערה 92); ועי״ז בא לסעיף ב' — קימה בחצות הלילה שמורה על ענין הגילוי [להעיר מחדא״ג דלעיל הערה •63: הנסים המפורסמים בעוה״ז התחילו בחצות לילה], „אור הנשמה\", עבודה השייכת לדרגת הצדיקים."]]],[1300161378,"<h3>פורים ב</h3>\nא. אויפן פסוק „קימו וקבלו היהו־דים”1 זאָגן חז״ל2: „קיימו מה שקיבלו כבר”, אַז די „מודעא רבה לאורייתא” מצד דעם וואָס „כפה הקב״ה עליהם את ההר כגיגית וכו׳”, בשעת מ״ת, איז בטל געוואָרן בימי הפורים ווייל „הדר קבלוה בימי אחשורוש”.\nעס איז מובן אַז דאָס וואָס די אידן האָבן (דעמאָלט) מקבל געווען תורה מדעתם איז אַן ענין עקרי. איז ניט מובן לכאורה: פאַרוואָס מ׳האָט ניט מתקן געווען צו טאָן בימי הפורים אַן ענין לזכר פון דעם „הדר קבלוה בימי אחשורוש”?\nאון אע״פ אַז דאָס וואָס זיי האָבן דעמאָלט מקבל געווען מדעתם איז געווען „מאהבת הנס שנעשה להם”3, איז אָבער פאַרט שווער צו זאָגן אַז ס׳זאָל ניט זיין אפילו אַ זכר צום ענין הכי עיקרי4, וואָס דער נס האָט אַרויסגערופן — דער גמר און שלימות פון מתן תורה, קבלת התורה מדעתם.\nב. ויש לומר, אַז אדרבא, דאָס ווערט אַרויסגעבראַכט אין אַלע מצוות מיוחדות פון פורים: א) מקרא מגילה, ב) משלוח מנות, ג) מתנות לאביונים,\nדי מצוות וואָס אין זיי איז מודגש דער שינוי פון פורים לגבי אַנדערע חגים ויו״ט [משא״כ די אַנדערע מצות און ענינים שבפורים — קריאת התורה, אמירת ועל הנסים בתפלה ובברכת המזון, איסור הספד ותענית, סעודה — משתה ושמחה — וועלכע זיינען דאָ (דוגמתם) בשאר החגים ויו״ט5].\nובהקדים דעם חילוק צווישן אַ מעשה וואָס אַ מענטש טוט דורך כפי׳ ואונס, און אַ מעשה וואָס ער טוט ברצון ודעת: ווען דאָס איז בעל כרחו ובכפי׳ טוט ער דאָס נאָר אויף וויפל ער מוז און עס פאַדערט זיך (צו יוצא זיין ידי חובתו); משא״כ ווען ער טוט עס מיט אַן אייגענעם חפץ ורצון, באַנוגנט ער זיך ניט מיט בלויז יוצא זיין ידי חובתו, נאָר ער איז זיך משתדל און זוכט צו מוסיף זיין ומהדר זיין אין דער פעולה, מער ווי עס פאָדערט זיך מצד דער פליכט וואָס ליגט אויף אים.\nאון דאָס דריקט זיך אויס אין דעם „קיימו וקבלו היהודים עליהם ועל זרעם” — דורך די מצוות (כתיבת6 ו)קריאת המגילה, משלוח מנות און מתנות לאביונים.\nוהביאור: פון איין זייט זיינען די דריי ענינים ניט קיין דברים חדשים ממש, און לאידך, האָבן זיי אין זיך אַ הוספה לגבי דעם ווי זיי זיינען פאַראַן פון פריער:\nדער ענין המגילה איז ניט קיין חידוש, (עס זיינען דאָ פון פריער די ספרי",[["1","1","אסתר ט, כז."],["2","2","שבת פח, א."],["3","3","פרש״י שבת שם ד״ה בימי. ועד״ז בתוד״ה מודעא שבת שם „קבלו מדעתם מאהבת הנס”."],["4","4","להעיר ממגילת סתרים לאסתר (שם, יט בסופו): והא דמרדכי כתב כו׳."],["5","5","אבל י״ל דגם חיוב משתה ושמחה הוא מהענינים המיוחדים שבפורים, כי לא נמצא במק״א החיוב באופן כזה, כדלקמן בפנים. משא״כ קריאת התורה וכו׳."],["6","6","להעיר מפרש״י עה״פ (מג״א ט, כז) „קיימו וקבלו היהודים גו׳ ככתבם” „שתהא המגילה כתובה כתב אשורית”. וראה לקמן בפנים ובהנסמן בהערה 10."]]],[1300161379,"קודש, תורה נביאים וכתובים — אעפ״כ איז מיט דער מגילה נתוסף געוואָרן נאָך אַ ספר צו די ספרי קודש — דורך אַ בקשה מיוחדת כתבוני לדורות7, אַז דאָס איז פון די נסים הכתובים8 עכ״פ דער סיום וסוף זייערער9; און עד״ז קריאתה10 — איז דאָך סיי דער ענין פון קריאה בתורה שוין געווען, ועד״ז דער ענין סיפור הנס דאָ (בכלל) אין יו״ט, אעפ״כ קומט דאָ צו די קריאה בלילה11 פון אַ מגילה12 מתוך הקלף פרסומי ניסא וכו׳13.\nמשלוח מנות: לויט ווי עס איז מבואר אין מנות הלוי14, איז ענינה צו מרבה זיין שלום וריעות צווישן אידן מיטן צווייטן, וואָס דאָס איז דאָך אַ מצוה וכללית בכל ימות השנה — אהבת ישראל, וועלכע איז אַ כלל גדול בתורה15; אָבער מצד מצות אהבת ישראל איז ניטאָ קיין חיוב אַז מ׳דאַרף זוכן אַ אידן צו מקיים זיין די מצוה פון „ואהבת לרעך כמוך”. דער חידוש אין דער מצוה פון „משלוח מנות איש לרעהו”: משתדל זיין זיך געפינען „רעהו” און דורך משלוח מנות צו אַרויסברענגען בפועל און אין אַן אופן אַז מ׳זאָל עס קענען גלייך נוצען (ניט — געלט<sup data-n=\"16\">16</sup> דעם ואהבת לרעך כמוך.\nמתנות לאביונים: דער ענין הצדקה17 — איז אַ מצוה בכל השנה כולה; אין פורים קומט צו דער יתרון, אַז ס׳איז ניט גענוג דאָס וואָס ער טרעפט אַן עני בשעת ער מקיים די מצוה פון „פתוח תפתח” און „נתון תתן”18, נאָר ער דאַרף עס זוכן און געפינען און — צוויי עניים און זיי געבן (באופן פון) „מתנות”.\nאון דאָס איז מודגש אויך אין די ווערטער „קיימו מה שקבלו כבר”: דאָס זיינען ענינים19 וואָס „קבלו כבר” — וואָס מ׳איז זיי מחוייב און מ׳טוט זיי בלאה״כ; בפורים אָבער קומט אין זיי צו דער ענין פון „קיימו” — דער אויפטו פון קיום וחיזוק — און אין ביידע קיין בין אדם לחבירו און בין אדם למקום: אַ קיום והוספה פון ענין אין תורה כפשוטה, כתיבה וקריאת מגילה, און דורכדעם אויך אין שבח20 ושירה לה׳, מער ווי אין אַנדערע ימים טובים (בין אדם למקום),\nאון אַ הוספה פון פעולה און השתדלות מיוחדת אין דעם ענין פון „ואהבת לרעך כמוך” און מצות הצדקה, דורך משלוח מנות איש לרעהו ומתנות לאביונים (בין אדם לחברו).",[["7","7","מגילה ז, א."],["8","8","משא״כ נס חנוכה."],["9","9","יומא כט, א."],["10","10","ראה צפע״נ להרמב״ם ריש הלכות מגילה. וראה לעיל ע׳ 352, וש״נ."],["11","11","ראה צפע״נ לרמב״ם הל׳ מגילה פ״א ה״ג."],["12","12","דק״ו דר״י בן קרחה (מגילה יד, א) „ומה מעבדות לחירות אמרי׳ שירה ממיתה לחיים לא כ״ש” (וראה טו״א שם) הוא בפשטות לכל הדיעות, אלא שלר״ג יתירה מזו: „קרייתא זו הלילא” (וכ״כ הרמב״ם הלכות חנוכה פ״ג סה״ו. וכ״ה בבה״ג הל׳ מגילה בסופו). וראה שו״ת חת״ס יו״ד סו״ס רל״ג."],["13","13","ולהעיר משו״ת צפע״נ דווינסק ח״ב סי׳ ח אות ג. מהד״ת ט, א."],["14","14","למגילת אסתר ט, טז. כ (ואילך)."],["15","15","תו״כ ופרש״י קדושים יט, יח."],["16","16","ראה תענית כג, ב."],["17","17","ראה מג״א ר״ס תרצד משל״ה ומהרי״ל דמתנות לאביונים צ״ל משלו ולא משל מעשר. וראה שו״ת כת״ס או״ח סי׳ קלט."],["18","18","ראה טו, ח. יו״ד."],["19","19","להעיר שענין ה„שמחה ומשתה ויו״ט ומשלוח מנות איש לרעהו” (אסתר שם, יט) קבלו ע״ע עוד לפני כתיבה ובקשת מרדכי — ראה מנות הלוי שם. מגלת סתרים שם (פסוק יט). ועוד."],["20","20","ע״ד קרבן תודה."]]],[1300161380,"ג. מ׳קען אָבער פרעגן: אויף משלוח מנות און מתנות לאביונים געפינט מען אַנדערע טעמים: באַ משלוח מנות „כדי21 שיהא לכל אחד די וספק לקיים הסעודה כדינא כמשמע בגמ׳ בפ״ק22 דאביי בר אבין ורב חנינא בר אבין מחלפי סעודתייהו להדדי ונפקו בהכי משלוח מנות אלמא דטעמא משום סעודה היא”23, ועד״ז בנוגע מתנות לאביונים איז משמע בכ״מ אַז דאָס איז כדי זיי זאָלן האָבן (גענוג) אויף סעודת פורים24 —\nולפי דעות אלו, אַז תוכנן וענינן פון די מצות איז דער קיום פון סעודות פורים און צוליב דעם איז די השתדלות במצות אלו (כאָטש אַז בדרך ממילא איז מען דערמיט מקיים אויך מצות ואהבת לרעך כמוך און מצות צדקה) — איז אין זיי דאָך ניט ניכר ומודגש דער „קיימו מה שקבלו כבר”?\nד. וועט מען דאָס פאַרשטיין ובהקדים אַז אויך דעת הרמב״ם איז משמע כנ״ל — אַז די מצוה פון מתנות לאביונים איז ניט (נאָר) אַלס מצות צדקה (ועד״ז בנוגע משלוח מנות כדלקמן) — וז״ל הרמב״ם25: „מוטב לאדם להרבות במתנות אביונים מלהרבות בסעודתו ובשלוח מנות לרעיו שאין שם שמחה גדולה ומפוארה אלא לשמח לב עניים ויתומים ואלמנות וגרים, שהמשמח לב האומללים האלו דומה לשכינה שנאמר26 להחיות רוח שפלים ולהחיות לב נדכאים”.\nאויב דער רמב״ם האַלט, אַז דער תוכן המצוה פון מתנות לאביונים בפורים איז דער ענין הצדקה במילא איז דער ענין („במתנות לאביונים . . דומה לשכינה”) אַ מעלה וואָס איז דאָ ביי דער מצוה פון צדקה פון כל ימות השנה — האָט ער דעם ענין (די מעלה „לשמח לב עניים . . דומה לשכינה”) געדאַרפט אַריינשטעלן בעיקר במקומו, אין הל׳ מתנות עניים27, וואו ער רעדט וועגן דער מעלה פון נתינת הצדקה בכלל — וואָס איז די שייכות דערפון דוקא (צו פורים און) הל׳ מגילה?\nאון אַזוי אויך לאידך גיסא: די מעלות אין נתינת צדקה וואָס ער ברענגט אין הל׳ מת״ע (אין ישראל נגאלין אלא בצדקה28 וכיו״ב), דערמאָנט ער ניט דאָ אין הל׳ (פורים —) מגילה29?\nמוז מען זאָגן לדעת הרמב״ם, אַז כאָטש מיט געבן „מתנות לאביונים” בפורים איז מען מקיים (אויך) די מצות הצדקה, איז אָבער תוכנה וענינה (פון מצות מתנות לאביונים בפורים) ניט (נאָר) דער ענין פון צדקה, צו ממלא זיין „די מחסורו” פון די צרכי העני כפשוטם, נאָר (בעיקר) דער קיום ענין השמחה30 פון עני — „לשמח לב עניים”.",[["21","21","תרומת הדשן סי׳ קיא."],["22","22","מגילה ז, ב."],["23","23","וראה שו״ת חת״ס או״ח סי׳ קצו ע״ד ב׳ הטעמים, ואשר זהו מחלוקת הרמ״א ופר״ח כו׳."],["24","24","ראה לבושי שרד במג״א שם סתרצ״ה סקי״ג. ובפרמ״ג שם [וראה ב״מ עח, ב. ובפרש״י שם. ע״ז יז, ב (ובפרש״י ותוס׳ שם)]. צפע״נ לרמב״ם הל׳ מגילה פ״ב סהט״ז. וראה בהנסמן לקמן הערה 30."],["25","25","הלכות מגילה פ״ב הי״ז."],["26","26","ישעי׳ נז, טו."],["27","27","פ״י."],["28","28","שם בריש הפרק."],["29","29","וידוע בכללי הרמב״ם שאין סומך בספרו על מש״כ לאחרי זה (יד מלאכי כללי הרמב״ם אות ואו)."],["30","30","ראה גם ריטב״א מגילה ז, ב. רמב״ן וחי׳ המיוחס להריטב״א ב״מ שם. ובהנ״ל משמע שזהו גם הטעם במשלוח מנות מצד שמחה. ולהעיר שברמב״ן מתוספתא (מגילה פ״א ה״ה) „והמותר אל יפול לכיס של צדקה”. משא״כ בריטב״א שם, ובמגילה שגריס „יפלו בכיס של צדקה”. וראה שו״ת כתב סופר או״ח שם."]]],[1300161381,"[ומהאי טעמא איז מובן וואָס דער רמב״ם איז דאָ כולל אין דער שמחה פון מתנות לאביונים אויך „יתומים ואלמנות וגרים” — דלכאורה: אויב זיי זיינען נצרכים, זיינען זיי דאָך אין כלל פון אביונים ועניים, פאַרוואָס טיילט ער זיי אויס באַזונדער? און אויב זיי זיינען ניט נצרכים און דאַרפן ניט אָנקומען צו צדקה — פאַרוואָס רעכנט זיי דער רמב״ם בשייכות צו דער מצוה פון מתנות לאביונים?\nע״פ הנ״ל אָבער, אַז דער גדר ותוכן המצוה פון מתנות לאביונים איז בעיקר „לשמח לב וכו׳” האָט עס במילא אַ שייכות צו אַלע „האומללים האלו”. וע״ד הצחות — אין דעם פרט פון שמחה זיינען זיי אַלע „עניים” ונצרכים].\nנאָכמער: פון לשון הרמב״ם איז מובן אַז אַלע דריי ענינים סיי „סעודתו”, סיי „שלוח מנות לרעיו” און סיי „מתנות לאביונים” איז ענינם ותוכנם — שמחה (ניט אַן אַנדער ענין), נאָר היות אַז „אין שם שמחה גדולה ומפוארה אלא לשמח לב עניים”, דעריבער „מוטב לאדם להרבות במתנות לאביונים”.\nדאַרף מען פאַרשטיין: בנוגע צו דער סעודה איז מובן אַז ענינה איז שמחה — פון וואַנעט נעמט אָבער דער רמב״ם אַז דער תוכן וגדר פון משלוח מנות און מתנות לאביונים איז ענינם שמחה.\n[אויך דאַרף מען פאַרשטיין: וואָס איז טאַקע די שייכות פון דעם „שהמשמח לב האומללים האלו דומה לשכינה” דוקא צום תוכן המצוה פון מתנות לאביונים? לכאורה איז דאָס שייך באַ יעדער נתינת צדקה, ווי ס׳איז מובן פון פסוק וואָס דער רמב״ם ברענגט, און פונדעסטוועגן דערמאָנט ניט דער רמב״ם די מעלה „דומה לשכינה” בנוגע צו צדקה בכלל, כנ״ל, כאָטש אַז ער ברענגט דאָרטן31 דעם פסוק „להחיות רוח שפלים גו׳”].\nה. בנוגע צו משלוח מנות י״ל אַז דער רמב״ם לערנט אַז טעמו איז, כנ״ל, פאַרזאָרגן אַז אַ צווייטער זאָל האָבן אויף סעודת פורים וואָס דאָס איז אַ טייל פון דעם חיוב פון זיין אייגענער סעודה, ווי דער רמב״ם זאָגט: „כיצד חובת סעודה זו, שיאכל . . (און איז ממשיך אין דער זעלבער32 הלכה<sup data-n=\"33\">33</sup> וכן חייב אדם לשלוח שתי מנות כו׳, ואם אין לו מחליף עם חבירו זה שולח לזה סעודתו וזה שולח לזה סעודתו”, וואָס סעודת פורים איז דאָך אַן ענין פון שמחת מצוה — משתה ושמחה34,\nועד״ז י״ל איז אויך במתנות לאביונים אַז דאָס איז פאַרבונדן מיט חיוב משתה ושמחה שעליו, זיין סעודת פורים35,\nווי דער רמב״ם האָט שוין געזאָגט36 בנוגע צו שמחה ביו״ט „וכשהוא אוכל ושותה חייב להאכיל לגר ליתום ולאלמנה עם שאר העניים האומללים, אבל מי שנועל דלתות חצירו ואוכל ושותה הוא ובניו אתו ואינו מאכיל",[["31","31","בהל׳ מתנות עניים שם."],["32","32","כידוע שחלוקת ההלכות ברמב״ם בדיוק היא ולמדין ממנה וכו׳ (ראה לדוגמא הל׳ ת״ת לאדה״ז קו״א לפ״א ס״א [תתכו, א])."],["33","33","כ״ה בדפוסי רמב״ם שלפנינו. ובספרי תימן הוא בהלכה בפ״ע (ראה רמב״ם מהדורת פרנקל)."],["34","34","אבל אין מוכרח לומר שהרמב״ם ס״ל כהתרה״ד (שבהערה 21), כ״א ע״ד פי׳ הב״ח או״ח סו״ס תרצה, עיי״ש."],["35","35","אלא שהחילוק בין משלוח מנות ומתנות לאביונים לפ״ז הוא דמשלוח מנות הוא איש לרעהו, גם לעשירים, ומתנות הוא רק לאביונים עניים הנצרכים. ראה במקומות הנ״ל הערה 30."],["36","36","הל׳ יו״ט פ״ו הי״ח. שו״ע אדה״ז הל׳ יו״ט סתקכ״ט סי״א (בהוספת הראי׳, הפסוק — לאחרי תיבת „האומללים”): שנאמר והלוי והגר והיתום וגו׳ — דברים טז, יד. וצ״ע שלא העתיק אדה״ז גם תיבת „והאלמנה”."]]],[1300161382,"ומשקה לעניים ולמרי נפש אין זו שמחת מצוה אלא שמחת כריסו כו׳”, עיי״ש.\nעס איז אָבער שווער אַזוי לערנען דאָ בנוגע צו מתנות לאביונים, היות דער רמב״ם טיילט אָפּ דעם דין פון „מתנות לאביונים” אין אַ באַזונדער הלכה: „וחייב לחלק לעניים ביום הפורים וכו׳” ניט ווי דער דין פון משלוח מנות וועלכן ער שרייבט בהמשך אין איין הלכה מיט מצות הסעודה37,\nובפרט אַז ער דערמאָנט ניט אין דער הלכה און אין דער הלכה שלאח״ז בנוגע צו מתנות לאביונים „וכשהוא אוכל ושותה וכו׳” וכיו״ב, ווי אין הל׳ יו״ט.\nפון דעם איז מובן אַז דאָס איז אַ באַזונדער ענין וואָס האָט ניט צו טאָן מיט חיוב סעודתו, משתה ושמחה שעליו.\nנאָכמער — לפי הנ״ל קומט אויס, אַז משלוח מנות און מתנות לאביונים, זיינען ניט קיין באַזונדערע ענינים בפורים, נאָר — אַ חלק און אַ פרט פון דעם חיוב סעודה שלו, און בשעת ער איז ניט מקיים מצות משלוח מנות ומתנות לאביונים איז ער ניט יוצא כדבעי במצות סעודת פורים (משתה ושמחה) שעליו, ע״ד ווי בנוגע יו״ט,\nוואָס דאָס איז היפך פשטות הכתוב והמבואר בכ״מ, אַז זיי זיינען דריי באַזונדערע מצות. און ווי ס׳איז אויך מוכח פון לשון הרמב״ם בנוגע צו מתנות לאביונים אַז מוטב להרבות בזה, ווייל „אין שם שמחה גדולה ומפוארה אלא לשמח לב עניים כו׳”, ד. ה. אויך אָן דעם איז ער מקיים די מצות פון פורים, כולל אויך דעם ענין השמחה, נאָר עס איז ניט שמחה גדולה ומפוארה, עס קומט ניט צו צו דער שמחה פון מתנות לאביונים.\nו. ויש לומר הביאור בכל זה:\nדער לשון אין מגילה38 (פון וואַנען מ׳לערנט אַרויס די דריי מצות: משתה — סעודה, משלוח מנות איש לרעהו ומתנות לאביונים), איז: „לעשות אותם ימי משתה ושמחה ומשלוח מנות איש לרעהו ומתנות לאביונים”. פון דעם וואָרט „ימי” איז משמע, אַז דער חיוב פון משתה ושמחה בפורים איז ניט אַ פעולה וואָס מ׳דאַרף טאָן און זמנה איז אין דעם טאָג, נאָר דאָס איז דער גדר (— חובת) היום39, אַ תוצאה פון דעם וואָס דער יום („ימי”) איז ענינו „(משתה ו)שמחה”.\nפון דעם איז מובן אַז אויך די אַנדערע ענינים וחיובים פון ימי הפורים, ע״פ די וואָס שטייען בהמשך אין זעלבן פסוק „ומשלוח מנות איש לרעהו ומתנות לאביונים”, קומען אויך אַלס תוצאה פון דעם וואָס די טעג גופא זיינען40 „ימי משתה ושמחה”41.",[["37","37","ועד״ז הוא בשו״ע שדין מעות פורים לעניים הוא סי׳ בפ״ע, משא״כ החיוב ופרטי הדינים דמשלוח מנות הוא בהסי׳ ד„דיני סעודת פורים”."],["38","38","ט, כב."],["39","39","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071020\" data-slug=\"likkutei-sichot\" data-id=\"1300071020\">לקו״ש ח״ז ע׳ 20</a> ואילך, שזהו חיוב על כל היום."],["40","40","בסגנון אחר קצת: עשיית ימים אלו („לעשות אותם”) לימי שמחה היא ע״י ג׳ דברים: משתה — סעודה, משלוח מנות ומתנות לאביונים. וראה פרש״י שם, כח ד״ה „ונעשים, משתה ושמחה ויו״ט לתת מנות ומתנות”."],["41","41","עפ״ז אולי יש לבאר זה דלשון הרמב״ם בהי״ד הוא „שמחה ומשתה” כסדרן בכתוב לפנ״ז (יט) אע״פ דבפסוק זה לא נאמר התקנה והחיובים דימי הפורים, שהרי נזכר שם יו״ט ולא נאמר שם מתנות לאביונים, ולא כסדרו בהכתוב „ימי משתה ושמחה ומשלוח מנות איש לרעהו ומתנות לאביונים” שבו נאמר (וממנו למדין) החיובים דימי הפורים (וראה מנות הלוי ומגלת סתרים שם (הובאו בהערה 19)) — כי בזה מוסבר שגדר ה„ימי” הוא „שמחה” ומזה מסתעף החיוב דמשתה וכן המשלוח מנות ומתנות כו׳. *) להעיר מצפע״נ השלמה ע׳ 30."]]],[1300161383,"דעם ענין אַז די „ימי” ווערן (ימי) משתה ושמחה, געפינט מען ניט אין אַנדערע יו״ט.\nאון דאָס איז די שייכות צו „קיימו מה שקבלו כבר”, אין דעם ענין וואָס דאָס זיינען „ימי משתה ושמחה”, דריקט זיך אויס דאָס וואָס „הדר קבלוה בימי אחשורוש”42, (דער היפוך פון אונס), ווען זיי האָבן מקבל געווען די תורה „מדעתם” ומרצונם43.\nז. וי״ל אַז דער ענין פון „קיימו מה שקבלו כבר”, דריקט זיך אויס בעיקר אין דעם אופן המיוחד פון דער שמחה בפורים וואָס מען געפינט ניט ביי אַנדערע יו״ט וחיובי שמחה:\nוועגן מצות הסעודה זאָגט דער רמב״ם44: „כיצד חובת סעודה זו שיאכל כו׳ ושותה יין עד שישתכר וירדם בשכרותו”. דער מקור פון דער הלכה איז (ווי מפרשים זאָגן<sup data-n=\"45\">45</sup> מאמר רבא46 „חייב47 איניש לבסומי בפוריא עד דלא ידע בין ארור המן לברוך מרדכי”.\nלכאורה איז שכרות ניט קיין הנהגה רצוי׳, און ווי מפרשים48 זיינען אין דעם מאריך בשייכות צו דעם דין, און ווי דער רמב״ם אַליין איז עס מסביר בשייכות צו (שאר) יו״ט49: „שהשכרות והשחוק כו׳ אינה שמחה אלא הוללות כו׳” — איז ווי קומט עס אַז דאָס איז גאָר „חובת סעודה זו . . שותה יין עד שישתכר וירדם בשכרותו”.\nח. קען מען דאָס מסביר זיין ע״פ הנ״ל: וויבאַלד אַז בימי הפורים האָט זיך אויפגעטאָן (ווי די גמרא זאָגט) דער ענין פון „קיימו מה שקבלו כבר”, די שלימות וגמר פון קבלת התורה איז ווי־באַלד די תורה איז דאָך גילוי רצונו וחכמתו של הקב״ה, חמודה גנוזה50 קען דאָס אַ נברא (אַ מוגבל אין זיין ידיעה והשגה און אין זיין מציאות) ניט אויפנעמען, און דעריבער איז ביי מ״ת על כל דבור ודבור פרחה נשמתן51,\nועד״ז און ביתר שאת איז בנוגע „הדר קבלוה בימי אחשורוש”, בכדי מקבל זיין תורתו של הקב״ה, האָט געדאַרפט זיין דער ביטול השגה ודעת ביז צו התפשטות הגשמיות, וע״ד ווי עס שטייט אין טור און שו״ע (ואדה״ז)52 דער אופן התפלה פון חסידים ואנשי מעשה (וואָס „המתפלל53 צריך שיראה עצמו כאילו שכינה54 כנגדו”) „היו מתבודדים ומכו־",[["42","42","ולהעיר דבגמ׳ (פסחים סח, ב) באים בחדא מחתא „הכל מודים בעצרת דבעינן נמי לכם מ״ט יום שניתנה בו תורה” [„שישמח בו במאכל ומשתה להראות שנוח ומקובל יום זה לישראל שנתנה תורה בו” — פרש״י שם ד״ה דבעינן. שו״ע אדה״ז או״ח סתצ״ד סי״ח], הכל מודים בפורים דבעינן נמי לכם מ״ט ימי משתה ושמחה."],["43","43","ראה בה״ג הל׳ מגילה (קרוב לסופו) „ועדיף יום פורים כיום שנתנה בו תורה”. ועד״ז בשאילתות ויקהל שאילתא סז. ובהעמק שאלה שם אות ו׳ מפרש ע״ד הנ״ל. וראה שו״ת כתב סופר שם סי׳ קמא."],["44","44","שם הט״ו."],["45","45","מגיד משנה. הגהות מיימוניות."],["46","46","מגילה ז, ב."],["47","47","בש״ס שלנו הגירסא מיחייב. אבל במאור הקטן על הרי״ף, שער הכוונות בסופו, של״ה פ׳ תצוה ובכל דרושי דא״ח שראיתי הל׳ הוא חייב איניש. וכן הוא ג״כ בא״ח (הובא בב״י סי׳ תרצה), שו״ע או״ח סתרצ״ה ס״ב, סי׳ יעב״ץ ועוד."],["48","48","מאירי מגילה שם. כל בו (סי׳ מה בסופו). ועוד."],["49","49","הל׳ יו״ט שם ה״כ."],["50","50","שבת פח, ב."],["51","51","שבת שם. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>. אגה״ק סי׳ י״ט."],["52","52","או״ח ר״ס צח. וראה הל׳ ת״ת לאדה״ז פ״ד סוס״ה."],["53","53","סנהדרין כב, א."],["54","54","בשו״ע אדה״ז „שכינה שרוי׳ כנגדו”. ובטושו״ע שם: ויחשוב כאילו שכינה כנגדו."]]],[1300161384,"נים בתפלתם עד שהיו מגיעים להתפשטות הגשמיות ולהתגברות רוח55 השכליות עד שהיו מגיעים קרוב למעלת הנבואה” —\nאון בימי הפורים זיינען אידן צו דעם צוגעקומען דורך זייער מסירת נפש במשך כל השנה כולה56.\nט. ועפ״ז איז מובן אַז דער ענין (עקרי) פון פורים, דער „עיצומו של יום” זאָגט זיך אַרויס אין „ימי משתה ושמחה” — אין דער שמחת הסעודה באופן פון „שותה יין עד שישתכר וירדם בשכרותו” —\nווייל דער הדר „קבלוה בימי אחשורוש” און „קיימו מה שקבלו כבר” במ״ת, דריקט זיך אויס אין דעם וואָס ער איז מבטל דעתו והשגתו, ביז ער קומט צו „התפשטות הגשמיות”, וע״ד ווי מ׳געפינט ביי נבואה — ווי דער רמב״ם57 זאָגט — „כולן אין רואין כו׳ אלא בחלום בחזיון לילה או ביום אחר שתפול עליהן תרדמה . . וכולן כשמתנבאים אבריהן מזדעזעין וכח הגוף כשל ועשתנותיהם מתטרפות כו׳”.\nאון דעריבער איז אויך דער חיוב השמחה פון ימי משתה ושמחה אין אַזאַ ניט מוגבל׳דיקן אופן „עד שישתכר וירדם58 בשכרותו” ווען עס ווערט נתבטל59 זיין ציור ועשתנותיהם.\nיו״ד. און מהאי טעמא זאָגט דער רמב״ם „מוטב לאדם להרבות במתנות אביונים מלהרבות בסעודתו ובשלוח מנות לרעיו”: כאָטש אַלע דריי מצות איז ענינם שמחה, איז אָבער „אין שם שמחה גדולה ומפוארה אלא לשמח לב עניים יתומים כו׳”: ווען איז די שמחה אַן אמת׳ע און שלימות׳דיקע ביז ער גייט אַרויס פון זיין ציור ומציאות און קומט צו אַ מצב פון „לא ידעי” — וואָס דריקט אויס (קיום) קבלת תורתו של הקב״ה — בשעת ער איז מרבה במתנות לאביונים, וואָס דערמיט באַווייזט ער אַז דער ענין פון משמח זיין „לב עניים כו׳” רופט באַ אים אַרויס מער שמחה ווי זיין אייגענע סעודה ושמחה, אָדער אפילו די סעודה מיט „רעיו” (אנשים כערכו)60.\nמשא״כ בנוגע יו״ט, וואָס דער חיוב השמחה ביו״ט איז די מצות „ושמחת בחגיך”61; ס׳איז אין דעם ניטאָ דער חיוב לבסומי עד דלא ידעי, „עד שישתכר” — ביז צו אַרויסגיין פון זיין מציאות, ואדרבה, ווי מובן פון רמב״ם דאָרטן, כנ״ל, אויב עס זיינען ניטאָ קיין עניים ומרי נפש, איז מספיק זיין שמחה פרטית און עס פעלט ניט אין זיין קיום מצות „ושמחת בחגיך”, וואָס האָט אַ הגבלה.\nדוקא ווען ער איז „נועל דלתות חצירו”, ווען ער טוט אַ פעולה צו שולל זיין די שמחת יו״ט פון די עניים —",[["55","55","כ״ה בשו״ע אדה״ז ובטור. בשו״ע שם: כח השכלי."],["56","56","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370417\" data-slug=\"torah-or\" data-id=\"3901370417\">תו״א צב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370429\" data-slug=\"torah-or\" data-id=\"3901370429\">צה, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">צז, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">צח, א</a>. ובכ״מ."],["57","57","הל׳ יסודי התורה פ״ז ה״ב."],["58","58","להעיר משהש״ר פ״א, יב (ב) דלפני קבלת התורה „ישנו להם ישראל כל אותו הלילה”. וראה לקו״ש ח״ד ע׳ 1024, שי״ל שזו היתה ההכנה שלהם לקבלת התורה. ולהעיר מסה״מ תשי״א ע׳ 11 ואילך."],["59","59","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370429\" data-slug=\"torah-or\" data-id=\"3901370429\">תו״א צה, סע״ד</a> ואילך. ובכ״מ."],["60","60","וי״ל דמשלוח מנות מכיון שזהו „לחבירו”, ה״ז רק בחי׳ „לא ידעי” בהאדם עצמו, היינו שלימות בחי׳ השמחה דלא ידע שבמשתה וסעודה שלו. ולכן כתבו הרמב״ם בהמשך וכסיום ל„כיצד חובת סעודה זו . . וכן חייב אדם לשלוח כו׳”. משא״כ מתנות לאביונים (שאינם בדרגתו) שהוא למעלה מ„לא ידעי” המתבטא אצל האדם בסעודתו הוא, ולכן כתבו הרמב״ם בהלכה בפ״ע."],["61","61","ראה טז, יד."]]],[1300161385,"דעמאָלט איז דאָס ניט קיין שמחת מצוה נאָר שמחת כריסו.\nיא. און אין דעם איז דער יתרון פון דער שמחה בחג הפורים, וואָס די שמחה דאַרף זיין עד דלא ידעי, העכער פון זיין ידיעה והגבלות — און אַזאַ שמחה גדולה ומפוארה זאָגט זיך אַרויס ווען ער איז משמח לב העניים כו׳.\nאון אויף דעם איז דער רמב״ם מוסיף אַז ניט נאָר דאַרף ער דעמאָלט שטיין אין אַ שמחה בבחי׳ „לא ידע”, ביז „ישתכר וירדם בשכרותו”, וואָס דערמיט ווערט נתקיים „הדר קבלוהו כו׳”, כנ״ל:\nנאָר נאָכמער: „המשמח לב האומללים האלו דומה לשכינה”, ווייל אַזאַ ענין אַז די שמחה פון אַ צווייטן אידן וואָס איז אומלל, רופט ביי אים אַרויס אַ שמחה גדולה ומפוארה, איז ניט שייך באַ אַ נברא — וואָס איז אַ מציאות בפ״ע און קרוב אצל עצמו62 און דערפאַר מוז זיין מציאות און (במילא) זיין שמחה ביי אים זיין וויכטיקער ווי שמחתו פון אַ צווייטן ובפרט של (עני כו׳) הפחות ממנו — נאָר בלויז באַ שכינה; און דאָס וואָס אַ איד קען שטיין (און שטייט) אין אַזאַ תנועה, איז עס דערפאַר וואָס ער איז „דומה לשכינה”.\nאון דורך אַזאַ הנהגה איז ער מקיים דעם ענין פון „ימי משתה ושמחה” בשלימות, וואָרום דעמאָלט ווערט אין זיין מעשה בפועל נתגלה במילואו דער גילוי פון „הדר קבלוה בימי אחשורוש” דער „קיימו מה שקבלו כבר”.\n(משיחת פורים תשל״ו)",[["62","62","יבמות כה, ב. וש״נ."]]],[1300161386,"<h3>פורים ג</h3>\nא. אויף דעם וואס עס שטייט אין סיום וחותם פון דער מגילה — „כי מרדכי היהודי וגו׳ ורצוי לרוב אחיו וגו׳” — זאגן רז״ל אין גמרא¹: „לרוב אחיו, ולא לכל אחיו, מלמד שפירשו ממנו מקצת סנהדרין” [וארום „אחיו” זיינען „חבריו שהיו מכלל אנשי כנסת הגדולה”²] און רש״י איז מפרש דעם טעם פארוואס „מקצת סנהדרין” האבן זיך פורש געווען פון מרדכי — „לפי שבטל מדברי תורה ונכנס לשררה”³.\nנאכדעם איז די גמרא ממשיך: „גדול תלמוד תורה יותר מהצלת נפשות, דמעיקרא חשיב לי׳ למרדכי בתר ד׳ ולבסוף בתר חמשה, מעיקרא כתיב כו׳ ולבסוף כתיב כו׳”, אז אין א פריערדיקן פסוק (אין עזרא⁴) ווערט מרדכי גערעכנט אלס דער פינפטער, און אין א ווייטערדיקן פסוק (נחמי׳⁵) — אלס דער זעקסטער: „לפי שנעשה מרדכי שר בינתים ירד מחשיבותו אצל חכמים”⁶.\nאיז ניט מובן: אט דעם כלל, אז „גדול ת״ת יותר מהצלת נפשות”, האבן דאך חז״ל געקענט ארויסלערנען פון פשטות הכתוב אין דער מגילה גופא: „לרוב אחיו .. מלמד שפירשו ממנו מקצת סנהדרין”, וואס דער „פירשו” איז דאך געווען דערפאר וואס „בטל מדברי תורה” צוליב הצלת נפשות — טא פאר־\nוואס לערנט דאס די גמרא ארויס פון א שינוי סדר און פון שלא במקומו און פון צוויי פסוקים אין באזונדערע ספרי תנ״ך?\nעס זיינען דא מפרשים⁷ וואס ענטפערן, אז פון לשון אין מגילה קען מען נאר ארויסלערנען אז ביי סנהדרין איז ת״ת געווען מער חשוב ווי הצלת נפשות; ס׳איז אבער ניטא קיין באווייז אז משמים האט מען דערצו מסכים געווען? דערפאר ברענגט די גמרא דעם לימוד הנ״ל, וואו די תורה גופא האט דאס מרמז געווען אין דעם שינוי הסדר בהפסוקים.\nאבער דער תירוץ איז, ע״ד הפשט, ניט גלאטיק: די וואס „פירשו ממנו” זיינען ניט געווען סתם מענטשן, נאר אחיו — חברי סנהדרין, וואס ענינם והנהגתם איז פסק הלכה על פי תורה — איז וואו פעלט דא די ראי׳ אז „משמים הסכימו”?\nב. אויך איז שווער צו פארשטיין:\nא) וויבאלד אז „גדול ת״ת יותר מהצלת נפשות”, היינט פארוואס איז מרדכי׳ס נאמען דערפאר (וואס „בטל מת״ת”) איבערגעשטעלט געווארן נאר מיט איין דרגא ווייטער אין סדר פון די נעמען (פון „בתר ד׳” צו „בתר ה׳”) — לכאורה האט ער דערנאך איבערהויפט ניט געדארפט גערעכנט ווערן צווישן די (חברי ה)סנהדרין, וואס זייער ענין איז פס״ד תורה?\nב) פון משמעות הפסוק איז פאר־שטאנדיק, אז מרדכי׳ס שררה אלס „משנה למלך” האט געדויערט א משך",[["1","1","מגילה טז, ב. הובא בפרש״י עה״פ."],["2","2","חדא״ג מהרש״א שם."],["3","3","ובפרש״י עה״פ בהיפך הסדר — לפי שנעשה קרוב למלכות והי׳ בטל מתלמודו, כפשוטו של הענין."],["4","4","ב, ב."],["5","5","ז, ז."],["6","6","פרש״י מגילה שם."],["7","7","הרי״ף לע״י מגילה שם."]]],[1300161387,"זמן, וואס דעמאלט איז ער געווען „רצוי (בלויז) לרוב אחיו” (— א מצב פון „פירשו ממנו”) — איז ממה־נפשך: אדער מרדכי האט זיי באלד געדארפט אויפווייזן אז זיין הנהגה איז על פי תורה, אדער, אויב ניט, האט ער געדארפט אוועקגיין פון זיין „שררה”, ובמילא — גלייך צוריק ווערן רצוי לכל אחיו.\nג. דער ביאור אין דעם וועט זיין מובן פון דעם דיוק אין זעלבן לשון המגילה (ודרשת רז״ל): „רצוי לרוב אחיו” — „פירשו ממנו (נאר) מקצת סנהדרין”, וואס דאס מיינט אז רוב „אחיו” אין סנהדרין יע מסכים געווען צו דער הנהגה פון מרדכי.\nובמילא איז פארשטאנדיק בפשטות אז פון דעם וואס „פירשו ממנו מקצת סנהדרין” איז כלל ניטא קיין ראי׳ אז ת״ת איז גרעסער פון הצלת נפשות; אדרבה, פון דעם קען מען ארויס־לערנען פארקערט, וויבאלד אז צו רוב סנהדרין איז ער געווען רצוי — ד.ה. זיי זיינען מיט אים בדעה אחת⁸.\nאון דערמיט איז אויך מוסבר, וואס מרדכי׳ס נאמען איז צוליב דעם איבער־געשטעלט געווארן נאר מיט איין דרגא ווייטער — היות, אז, אדרבה, רוב חברי הסנהדרין האבן איינגעשטימט מיט זיין הנהגה.\nאבער לפי זה ווערט שווער לאידך גיסא:\nא) וויבאלד אז מרדכי׳ס הנהגה איז געווען בהסכם מיט דער דיעה פון רוב חברי הסנהדרין, האט זי דאך געדארפט מכריע זיין די דיעה פון מיעוט („מקצת”) — היינט פארוואס „פירשו ממנו” און זיי\nהאבן ניט מבטל געמאכט זייער דעת (המיעוט) קעגן דעם רוב?\nב) לויט דעם קומט אויס, אז די צוויי מאמרי חז״ל הנ״ל וואס די גמרא ברענגט אין איין המשך („פירשו ממנו (נאר) מקצת סנהדרין” ו„גדול ת״ת יותר מהצלת נפשות”), זיינען זיי גאר סותר איינער דעם צווייטן⁹.\nד. איז דער כללות׳דיקער ביאור אין דעם בהקדם נאך א דיוק במחז״ל זה: „פירשו ממנו מקצת סנהדרין”, און ניט „חלקו עליו” אדער עכ״פ „אין רוח מקצת חכמים נוחה הימנו”¹⁰ וכדומה — וואס „פירשו ממנו” מיינט (ניט א מחלוקת ווייל לויט זייער דיעה איז מרדכי׳ס הנהגה ניט עפ״י תורה, נאר) אז זיי האבן זיך פון אים אפגעזונדערט, האבנדיק א באזונדערן און אנדערן דרך ושיטה אין הנהגת פון חברי סנהדרין (אדער — ת״ח בכלל), ולא דרכו דרכם — אבער אויך זיי האבן מסכים געווען אז מרדכי׳ס הנהגה (בנוגע לעצמו) איז א דרך עפ״י תורה.\nדי הסברה אין דעם וועט זיין פאר־שטאנדיק אויך פון א סיפור וועגן דעם ראגאטשאווער גאון והנהגתו — והביאור אין דעם:\nנאכדעם ווי כ״ק מו״ח אדמו״ר איז ארויסגעפארן פון רוסלאנד און אנגע־קומען אין ריגא, האט ער דארט פאר־רופן אן אסיפה פון רבנים, מנהיגים און עסקנים וכו׳ לטובת די רוסישע אידן, צווישן די איינגעלאדענע איז אויך געווען דער ראגאטשאווער. ביי דער",[["8","8","כ״פ גם בבן יהוידע מגילה שם."],["9","9","ולגירסת הע״י (וכ״ה גירסת היל״ש עה״פ. הובאה ג״כ בדק״ס מגילה שם) בעל ב׳ המימרות אחד הוא (רב יוסף)!"],["10","10","להעיר ממדרש שמואל לאבות פ״ג מ״י — הובא ביד יוסף לע״י שם."]]],[1300161388,"אסיפה האט מען געוואלט באשטימען א ועד וואס זאל זיך צוזאמענקומען מזמן לזמן און זיך מיישב זיין ווי צו פירן די ארבעט פאר די רוסישע אידן — און מ׳האט געבעטן דעם ראגאטשאווער אז ער זאל זיין משתתף אין דעם ועד. ער האט זיך אבער אפגעזאגט און האט מסביר געווען, אז זיין אריינגיין אין ועד איז תלוי אין א פלוגתא צווישן תלמוד בבלי און ירושלמי:\nדי גמרא זאגט אין ברכות¹¹, אז „חסידים הראשונים היו שוהים .. תשע שעות ביום בתפלה”. פרעגט די גמרא: אויב אזוי, „תורתן היאך משתמרת ומלאכתן היאך נעשית (און די גמרא פארענטפערט) אלא מתוך שחסידים הם תורתם משתמרת ומלאכתן מתברכת”.\nאין ירושלמי¹² ברענגט זיך דער זעלבער ענין, נאר מיט א שינוי: אנשטאט „מתוך שחסידים הם תורתם משתמרת (ומלאכתן מתברכת)”, שטייט: „על ידי שהיו חסידים היתה ברכה ניתנת בתורתן (וברכה ניתנת במלאכתן)”.\nדער חילוק צווישן „תורתם משתמרת” און „ברכה ניתנת בתורתן” איז מובן: „משתמרת” מיינט נאר „שאין תלמודם משתכח”¹³, אבער עס קומט ניט צו קיין נייע בתורתן (נאר וויפל זיי קענען לערנען אין דעם זמן מועט ווען זיי זיינען זיך ניט עוסק אין תפלה);\nמשא״כ „ברכה ניתנת בתורתן” מיינט: „שהצליחו להבין ולהשכיל מיד ולא היו שוהין”¹⁴, ד.ה. אז (ניט נאר פארגעסן זיי ניט דאס וואס זיי לערנען, נאר ס׳קומט זיי צו א הוספה אין הבנת וידיעת\nהתורה:) אין דעם זמן מועט וואס זיי לערנען זיינען זיי מצליח „להבין ולהשכיל מיד” — דאס וואס כרגיל עפ״י זייער טבע וואלט אויף דעם נויטיק געווען א־סך מער זמן בלימוד התורה.\nאון אזוי אויך בנדו״ד (האט דער ראגאטשאווער אויסגעפירט): דורך דעם וואס ער וועט זיך באטייליקן אין ועד וועט ער מוזן מבטל זיין מזמנו בלימוד התורה — איז לויטן ירושלמי, וואס „על ידי שהיו חסידים היתה ברכה ניתנת בתורתן”, וועט אים ניט פעלן אין ידיעת התורה; וויבאלד אבער אז הלכה כבבלי, אז ס׳איז בלויז „תורתם משתמרת”¹⁵, וועט ביי אים פעלן די הוספה אין לימוד וידיעת התורה וואס ער וואלט געקענט האבן ווען ער לערנט תורה אויך אין די זמנים — און אויף דעם קען ער ניט מוותר זיין.\nה. וי״ל, אז דער הסבר אין דער מחלוקת הנ״ל צווישן בבלי און ירושלמי, איז פארבונדן מיט דעם חילוק אין דעם אופן הלימוד צווישן זיי:\nדער אופן הלימוד אין תלמוד בבלי איז מיט א ריבוי שקו״ט וכו׳, און ווי די גמרא¹⁶ זאגט „במחשכים הושיבני¹⁷ .. זה תלמודה של בבל”: דער לימוד איז ע״ד ווי איינער זוכט אין דער פינצטער — מ׳דארף ריבוי חיפוש ויגיעה, פרעגן",[["11","11","לב, ב."],["12","12","שם פ״ה ה״א."],["13","13","פרש״י ברכות שם."],["14","14","פני משה לירושלמי שם."],["15","15","להעיר מהענין שע״י צדקה „נעשה מוחו ולבו זכים אלף פעמים ככה” — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו״א א, ב</a>. ובלקו״ת לג״פ (ג, א. נדפס באוה״ת בראשית כרך ו׳ תתרכו, ב ואילך) מובן שאינו גוזמא כ״א אלף ממש. ובמילא מובן שאין צריך לשהות. ואולי יש לחלק בין זה ל„ברכה ניתנת בתורתן”. ואכ״מ."],["16","16","סנהדרין כד, א. ומשמע דהסיבה היא „בבל” (ש„אין תורה כתורת א״י” — ב״ר פט״ז, ד׳) — וגם בזמן התנאים, אנשי כנה״ג וכו׳ כן הוא."],["17","17","איכה ג, ו."]]],[1300161389,"קושיות און פאנאנדערקלייבן וכו׳ ביז מ׳קומט צו צום אמת׳ן פשט ומסקנא; אבער אין תלמוד ירושלמי איז דער לימוד אין אן אופן ישר — מ׳געפינט גלייך די ריכטיקע סברא און תירוץ וכו׳, ווי איינער וואס זעט א זאך אין דער ליכטיקייט¹⁸.\nאון דעריבער דארף אויסקומען, אז לויט דער שיטה (און אופן הלימוד) פון בבלי, קען דורכן לימוד מועט (פון חסידים הראשונים) אויפגעטאן ווערן נאר דער ענין פון „תורתם משתמרת” — זיי זאלן ניט פארגעסן די דברי תורה וואס מ׳לערנט, אבער ניט אז עס זאל נאך זיין אין אן אופן פון „ברכה ניתנת בתורתן”, „להבין ולהשכיל מיד”, וואס איז ניט מתאים צום סדר הלימוד פון בבלי:\nאבער לויט דער שיטה (און אופן הלימוד) פון ירושלמי, טוט אויף זייער לימוד אויך דער ענין פון „ברכה ניתנת בתורתן” — „הצליחו להבין ולהשכיל מיד ולא היו שוהין” — בהתאם צום דרך הלימוד אין אן אופן ישר, אז מ׳קומט באלד צום ענין ווי ער איז לאמיתתו.\nו. עפ״ז י״ל, אז דער חילוק צווישן הנהגת מרדכי (שרצוי׳ ל(שיטת) רוב הסנהדרין) און דער שיטה פון „מקצת סנהדרין” איז תלוי אין דער פלוגתא הנ״ל צווישן בבלי און ירושלמי:\nדי סנהדרין גדולה, וואס מ׳האט געקליבן פון די סנהדרין קטנה¹⁹ וואס מקומם בירושלים ועכ״פ בארץ הקודש²⁰\n— איז מסתבר צו זאגן, אז זייער לימוד (עכ״פ פון רובם) איז געווען ווי דער סדר לימוד הירושלמי — ובפרט אין זמן המשנה ואנשי כנסת הגדולה:\nאבער אויך דאן זיינען געווען תנאים פון בבל — ע״ד ווי שפעטער: הלל עלה מבבל²¹, ר׳ נתן הבבלי²², ועוד — ובפרט אז ס׳איז שוין דורכגעגאנגען מער ווי זיבעציק יאר פונעם זמן ווען „החרש והמסגר”²³ זיינען אוועק מירושלים עם הגולה אשר הגלתה עם יכני׳ — לבבל²⁴. און אנשי כנה״ג זיינען געווען משבי הגולה אשר הגלה נ״נ מלך בבל לבבל וישובו לירושלים ויהודה — בשנת אחת לכורש, פופציג צוויי יאר זיינען זיי געווען בבבל, אבער אויך — פון „החרש והמסגר” וואס נאך בירושלים זיינען זיי שוין געווען במעלתם זו (און אין דעם אופן הלימוד)²⁵.\nאון דעריבער האט מרדכי (ורוב הסנהדרין) געהאלטן אז ער מוז ווערן א משנה למלך צוליב הצלת נפשות; איי, ווי קען ער דערנאך בלייבן אין סנהדרין ואנשי כנה״ג וואס זייער ענין איז לימוד התורה והוראה — איז „על ידי שהיו חסידים היתה ברכה ניתנת בתורתן”, ובמילא וועט ער האבן הצלחה (ניט נאר אין אן אופן פון „תורתם משתמרת”, נאר אויך) „להבין ולהשכיל מיד” — צו מתברך ווערן און שטייגן אין לערנען מער ווי לויט דעם זמן וואס עס בלייבט אים אויף לימוד התורה.",[["18","18","ראה בארוכה שערי אורה ד״ה בכ״ה בכסלו פנ״ד ואילך. המשך תרס״ו ע׳ צ ואילך. ד״ה אמר רבא תש״ח פי״א. ועוד."],["19","19","ראה סנהדרין פח, ב. רמב״ם הל׳ סנהדרין פ״ב ה״ח."],["20","20","שם."],["21","21","פסחים סו, א."],["22","22","דעלה מבבל — פרש״י גיטין (סה, ב), ב״ב (עג, א) ד״ה רבי נתן. ועוד."],["23","23","מ״ב כד, יד. גיטין פח, סע״א. פרש״י עה״פ."],["24","24","ראה סדר הדורות — בזמן דנס פורים."],["25","25","ראה בכ״ז — מפרשי המשניות בתחלת אבות. הקדמת הרמב״ם לפיה״מ. עזרא ב, א־ב. שם א, א. סדה״ד."]]],[1300161390,"עס האבן זיך אבער געפונען צווישן די חברי הסנהדרין אויך (א „מקצת”) אזעלכע וואס זייער אופן הלימוד איז געווען בדומה צום דרך הלימוד פון תלמוד בבלי — כנ״ל.\nאון דעריבער איז ביי זיי געווען דער אופן פון (בלויז) „תורתם משתמרת”, וואס דורך אפגעבן זיך מיט עניני עסקנות ו„הצלת נפשות” וועט פעלן אין הוספה בידיעת התורה וואס פאדערט זיך פון חברי הסנהדרין. און דערפאר „פירשו ממנו מקצת סנהדרין”: ביי זיי האט ניט געקענט זיין דער אופן העבודה פון מרדכי (ורוב הסנהדרין) און זיי האבן זיך פון אים אפגעזונדערט אין זייער אייגענעם דרך (כנ״ל אין אנהויב׳ס סעיף ד׳).\nז. הגם אז לויט דער שיטה פון ירושלמי איז „ברכה ניתנת בתורתן” — און דעריבער האט מרדכי געהאט אויך די ברכה וענין פון הוספה אין ידיעת התורה — פונדעסטוועגן, „ירד מחשי־בותו” צוליב דעם וואס „בטל מד״ת ונכנס לשררה” —\nוארום עס איז פאראן א מעלה מיוחדת אין דעם דרך פון „תורתם אומנתם” — ניט צו מבטל זיין פון לימוד צוליב קיין זאך²⁶ (אפילו ווען עס וועט לפועל ניט פעלן אין דער הוספה בידיעת התורה ווייל „ברכה ניתנת בתורתן”); און דאס איז כוונת חז״ל „גדול ת״ת יותר מהצלת נפשות כו׳”: עס איז דא א „גדלות” אינעם אפגעבן זיך אינגאנצן אויף לימוד התורה. און וויבאלד אז ביי מרדכי איז די „גדלות”\nנתמעט געווארן, איז אויך געווארן א מיעוט (ירידה) אין זיין חשיבות „אצל חכמים”, אז אנשטאט צו דערמאנט ווערן „בתר ד׳” איז ער דערמאנט געווארן „בתר חמשה”.\nאבער פונדעסטוועגן האט מרדכי (ורוב הסנהדרין) געהאלטן אז ער האט געדארפט ווערן א משנה למלך — ווייל אפילו אז דורכדעם זאל ביי אים פעלן די „גדלות” פון „גדול ת״ת”, איז עס כדאי צוליב דעם ענין פון „הצלת נפשות”²⁶*, צו זיין א „דורש טוב לעמו ודובר שלום לכל זרעו”²⁷.\nח. לכאורה איז אבער פארט ניט גלאטיק: אמת טאקע אז מחמת דעם וואס „ברכה ניתנת בתורתן” האט ביי מרדכי ניט געפעלט אפילו אין דער הוספה בידיעת התורה; און אמת טאקע אז עס איז דא א מעלה אין „הצלת נפשות” וואס צוליב דעם איז כדאי די ירידה (אז ער זאל ניט זיין „תורתו אומנתו”) — אבער ווי אזוי איז ער פארט אויך דערנאך געבליבן איינער פון די סנהדרין, וואס לכאורה כל ענינם איז נאר לימוד התורה און הוראה?\nבסגנון אחר: ווי איז שייך אז אויף סנהדרין גופא (וואס כל ענינם איז תורה כנ״ל) זאל זיין א חיוב צו מוותר זיין אויף „תורתם אומנתם” צוליב „הצלת נפשות”?",[["","","26*) ראה ט״ז יו״ד סו״ס רנא."],["27","27","אבל לולי הענין ד„הצלת נפשות” לא הי׳ עוסק בצ״צ, מצד מעלת ת״ת. ועפ״ז יש לקשר מה שפרש״י בתחלת מג״א — „הוא אחשורוש, הוא ברשעו מתחלתו ועד סופו”, עם פירושו בסיום מג״א — „לרוב אחיו, ולא לכל אחיו וכו׳” (דנעוץ תחלתן בסופן) — כי הטעם שמרדכי „נעשה קרוב למלכות והי׳ בטל מתלמודו” גם לאחר נס פורים, הוא לפי ש„הוא אחשורוש, הוא ברשעו מתחלתו ועד סופו”, ובמילא ישנו החשש שיחדש הגזירה."],["26","26","ראה מג״א (סק״י סק״ד. שו״ע אדה״ז שם ס״ד): אפילו רגע. ובשו״ע אדה״ז ס״צ סי״ז: ואין מתבטל כלל כ״א לדברים הכרחים לצרכי גופו ולימודו. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא ספכ״ג</a>. וראה לקמן הערה 32."]]],[1300161391,"איז דער ביאור אין דעם: עס שטייט אין תנא דבי אליהו²⁸: „הי׳ להם (לסנהדרי גדולה) לילך ולקשור חבלים של ברזל במתניהם ולהגבי׳ בגדיהם למעלה מארכובותיהן ויחזרו בכל עיי־רות ישראל כו׳ וילמדו את ישראל כו׳”.\nדער דין איז, אז ווען סנהדרין האט גולה געווען ממקומה בלשכת הגזית קען זי ניט דן זיין דיני נפשות²⁹; ד.ה. אז דורך דעם וואס „ויחזרו בכל עיירות ישראל כו׳” ווערט א ירידה אין דעם כח ותוקף פון סנהדרין³⁰; און פונדעסט־וועגן איז „הי׳ להם” — א חיוב — „לילך כו׳ בכל עיירות ישראל כו׳”³¹.\nפון דעם קען מען פארשטיין, אז דער עיקר תפקיד פון די סנהדרין איז — הוראה לרבים (און דורכדעם הצלת\nרבים), און צוליב דעם דארפן זיי יורד זיין פון זייער כח ותוקף אלס סנהדרין, כדי צו זיין ממזכי הרבים.\nאון עד״ז איז דער ביאור בעניננו: הגם אז דורכדעם וואס מרדכי איז געווארן א משנה למלך איז געווארן א ירידה אין זיין חשיבות (אלס חבר הסנהדרין) פון „בתר ד׳” צו „בתר חמשה”, עס האט ביי אים געפעלט דער ענין ומעלה פון „תורתם אומנתם” — איז אבער די ירידה כדאי, אפילו מצד ענינים פון סנהדרין גופא — וויבאלד דאס איז צוליב טובת הרבים (ע״ד הנת״ל אין תנא דבי אליהו).\nט. די הנהגה פון כ״ק מו״ח אדמו״ר איז געווען, אז ער פלעגט „גזל׳נען”³¹* פון זיין צייט וואס ער וואלט געקענט אפגעבן אויף לימוד התורה לעצמו ועבודת ה׳ לעצמו, און זיך פארנומען דאן מיט עניני עסקנות והצלת נפשות.\nאון ער האט עס אויך געמאנט פון א חלק חשוב פון זיינע תלמידים און מקושרים, אז אויך זיי זאלן זיך פירן אין דעם וועג; און ער האט איינגעפירט, אז אפילו תלמידי הישיבה זאלן — בין הסדרים — אוועקגעבן א געוויסן טייל פון זייער זמן אויף הפצת התורה והיהדות חוצה; און די התעסקות איז צייטענוויז אין אן אופן, אז א חלק גדול פון דעם זמן ההפצה גייט אוועק (ניט אויפן עצם לערנען מיטן צווייטן, נאר) אויף „צרכי ציבור”: השתדלות אריינ־צוקריגן תלמידים, מסדר זיין אן ארט אויף לערנען, שאפן די נויטיקע סכומים צו דעקן די הוצאות וכו׳ וכו׳.\nד.ה. אז אפילו אזעלכע מקושרים, וואס זייער מצב ודרגא איז נאר (כפסק הלכה פון בבלי) אינעם אופן פון „תורתם משתמרת”, דארפן זיי אפגעבן פון זייער",[["28","28","רבה פי״א."],["29","29","ע״ז ח, סע״ב. ושי״ג. רמב״ם הל׳ סנהדרין פי״ד הי״א־יג. ולדעת הרמב״ן (בהשגותיו לסהמ״צ מ״ע קנג) „בטלו כל הדינין (לא רק דיני נפשות) התלויין בב״ד הגדול”."],["30","30","ואף שבתדבא״ר שם המדובר בזמן „עד שיתישבו ישראל בארצם” שזה קודם לבנין ביהמ״ק — הרי מקומם דסנהדרין הוא „אצל המזבח” (ירושלמי מכות פ״ב ה״ו. מכילתא ס״פ יתרו*. משפטים כא, יד. פרש״י ר״פ משפטים), „סמוך לשכינה” (תוס׳ ע״ז שם ד״ה מלמד), דזה ישנו גם במשכן וכו׳. ומובן שכשאינם „אצל המזבח” חסר בשלימות ענין הסנהדרין. ובתוס׳ ע״ז (הנ״ל) מוכח דכשאינם (רק) „אצל המזבח” בטלו דיני נפשות כו׳, עיי״ש. ועוד (ועיקר) — טעם התדבא״ר דזהו „עד שיתיישבו” — כי לאח״ז הרי יש ב״ד בכ״מ והם עושים כ״ז (במכש״כ מסנהדרין „קודם שיתיישבו”, וק״ו מהם — שה״ה מארי דאתרא זה בפרט)."],["31","31","בפרט באופן ד„ולהגבי׳ בגדיהם למעלה מארכובותיהן” — להעיר מרז״ל חלוק כו׳ טלית של ת״ח כל שאין חלוקו נראה מתחתיו טפח (ב״ב נז, ב). — ועייג״כ תענית כג, רע״ב. מג״א או״ח ר״ס ב. *) כ״ה בדפוסים לפנינו. ובכמה דפוסים: ר״פ משפטים. ראה מכילתא מהדורת האראוויטץ־רבין. 31*) ראה זח״ב צג, ב: לא תגנוב כו׳. דיינא כו׳."]]],[1300161392,"זמן, אפילו אין דעם אופן וואס דורכ־דעם וועט פעלן אין זייער לימוד התורה ועבודת ה׳, צוליב טובת הרבים;\nווייל די הנהגה הנ״ל פון דעם ראגאטשאווער איז נאר פאר יחידי סגולה אין יעדן דור וואס זיינען בבחי׳ „תורתם אומנתם”, און זייער ענין איז ע״ד ווי דאס איז געווען ביי מקצת סנהדרין — א הוספה בידיעת התורה באופן תמידי;\nאבער דער סדר העבודה פאר רובא דרובא (אפילו פון בני תורה) איז — כפסק הדין, אז בזמן הזה איז ניטא מענשען וואס „תורתם אומנתם”³², און מה־דאך אז מ׳איז מבטל פון לערנען צוליב אנדערע ענינים, דארף מען אוודאי דאס טאן צוליב „הצלת נפשות” וטובת הרבים.\n— ולהעיר אז בנוגע צו כ״ק מו״ח אדמו״ר אליין — איז מי יודע אופן עבודתו. ובכלל איז דאך ידוע די תורה פון בעש״ט³³ אויפן פסוק³⁴ „קומי אורי כי בא אורך וכבוד ה׳ עליך זרח”: „אתם נשיאי ישראל וואס איר לייגט אוועק אייער תורה ועבודה בשביל טובת הרבים וואס וועט זיין מיט אייך, איז דאס קומי אורי באור הפרטי להכללי וכו׳” — ד.ה. אז נשיאי ישראל האבן א ברכה מיוחדת, אז עס זאל ביי זיי ניט פעלן אין זייער „תורה ועבודה”, ואדרבא „בא אורך\nוכבוד הוי׳ עליך זרח” — וואס דאס איז שלא בערך פון „ברכה ניתנת בתורתן”.\nיו״ד. דאס איז די הוראה פון הנהגת מרדכי פאר אונז לפועל — און ווי די תורה הידועה פון בעש״ט³⁵ אויפן מאמר המשנה³⁶ „הקורא את המגילה למפרע לא יצא”: דער וואס לייענט די מגילה אננעמענדיק אז דאס וואס ס׳ווערט דערציילט אין מגילה איז א זאך וואס האט געטראפן אינעם עבר („למפרע”) און האט ניט קיין שייכות צום הווה — איז „לא יצא”:\nעס פאדערט זיך פון אונז א הנהגה — מעין און עכ״פ שמץ מנהו פון הנהגת מרדכי, צו ווערן א „משנה למלך”, כדי צו זיין א „דורש³⁷ טוב לעמו ודובר שלום לכל זרעו” (אפילו ווען צוליב דעם איז ער „רצוי” בלויז צו „רוב אחיו”);\nאון הגם אז די הנהגה איז ביי כמה וכמה פארבונדן מיט א „ירידה”³⁸, וארום מ׳דארף צוליב דעם מוותר זיין אויף דער אייגענער שלימות — איז כדאי די ירידה צוליב דער תועלת וטובת הרבים.\n[און אזוי געפינט מען עס אויך ביי יעדערן בחייו אלס יחיד ופרט: זיין נשמה איז יורד „מאיגרא רמה לבירא עמיקתא”³⁹ כדי צו ווערן א מושל",[["32","32","בדרגא דרשב״י (שאז „אין מפסיקין לתפלה”) — שבת יא, א. טושו״ע (ואדה״ז) או״ח סר״ס קו [אף שישנו בדרגא פחותה יותר (שאז אי״צ לילך לביהכנ״ס) — רמ״א או״ח ס״צ סי״ח. שו״ע אדה״ז שם סי״ז. וראה לעיל הערה 26]."],["33","33","מד תורות הידועות שאמרן בג״ע ביום חגיגת הולדתו ש״ק פ׳ תבוא ח״י אלול תרנ״ב — כפי ששמען כ״ק אדמו״ר מהורש״ב נ״ע (משיחת שמע״צ תרצ״ז). נדפסו בהוספות לכש״ט (קה״ת) סי׳ ג׳ ובסה״ש תרצ״ז."],["34","34","ישעי׳ ס, א (מהפטורה דפ׳ תבוא)."],["35","35","הוספות לכש״ט (קה״ת) סי׳ עח."],["36","36","מגילה רפ״ב."],["37","37","וכידוע אמתית ענין הדרישה — ע״ד ודרשת וחקרת גו׳, תדרשנו בכל לבבך גו׳. וראה ט״ז לאו״ח ר״ס תכט. — ראה סה״מ עתי״ר ע׳ סא. סה״מ תש״ט ע׳ 224 ואילך."],["38","38","וכמו מלך כפשוטו, שמצ״ע הוא „משכמו ומעלה גבוה מכל העם” (ש״א ט, ב), וצ״ל השתדלות מיוחדת לפעול עליו שירצה להיות מלך על עם (ראה ד״ה תקעו תש״ה. יו״ט של ר״ה תש״ג. ובכ״מ)."],["39","39","ע״ד לשון הש״ס חגיגה ה, ב. ונת׳ ברשימות הצ״צ לאיכה (אוה״ת נ״ך כרך ב׳ ע׳ א׳עב ואילך)."]]],[1300161393,"ושולט⁴⁰ אויפן גוף, נפה״ב וחלקו בעולם, זיי כובש זיין און פון זיי מאכן א „דירה לו ית׳”:\nאון דערנאך אז ער האט חתונה — קומט בהוספה על הנ״ל (ובלשון המגילה⁴¹): „להיות כל איש שורר בביתו” (וכמחז״ל⁴² „איזהו אשה כשרה העושה רצון בעלה”) — און אויך די „שררה” איז פארבונדן מיט א ירידה, וכמחז״ל⁴³ „נחית דרגא נסיב איתתא”, ווייל א מענטש מוז מוותר זיין אויף זיינע אייגענע ענינים צוליב טובת ביתו⁴⁴].\nאון דאס איז אויך די הסברה אויף דעם וואס מ׳געפינט אן עילוי אין עוסקים בצ״צ אפי׳ אויף די וואס „תורתם אומנתם”⁴⁵: די וואס „תורתם אומנתם” דארפן מפסיק זיין לק״ש⁴⁶, אבער די וואס זיינען עוסק בצ״צ זיינען ניט מפסיק אפילו לק״ש⁴⁷ —\nוארום הגם אז דורך התעסקות בצ״צ באמונה⁴⁸ פעלט אין לימוד התורה ושלימות עצמו, ביז אז חז״ל⁴⁹ זאגן „הטל עליהן צ״צ והן כלין מאיליהן”, פונ־דעסטוועגן, איז דוקא אין דעם און דורכדעם דער עילוי נפלא פון טובת הרבים.\nאון אויב עס פאדערט זיך די הנהגה פון מרדכי בנוגע צו דער הצלה פון אידישע גופים⁵⁰, על אחת כמה וכמה אז עס דארף אזוי זיין ווען עס קומט צו דער הצלה פון אידישע נשמות — אז מ׳דארף אפלייגן די אייגענע שלימות צוליב „הצלת נפשות”, צו זיין א „דובר שלום לכל זרעו”, ביז עס וועט ווערן דער ישראל עושין תשובה „ומיד הן נגאלין”⁵¹, בקרוב ממש.\n(משיחות פורים תשל״ג, פורים וש״פ תשא תשל״ה)",[["40","40","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ״ט</a>."],["41","41","א, כב."],["42","42","ראה תדבא״ר פ״ט. הובא ברמ״א אהע״ז סוס״י סט."],["43","43","יבמות סג, א."],["44","44","ודוקא עי״ז „ויברך אותם ויקרא את שמם אדם” (בראשית ה, ב. יבמות שם. המשך שמח תשמח תרנ״ז ע׳ 5 ואילך). וראה לעיל הערה 15, שע״י צדקה „נעשה מוחו ולבו זכים וכו׳”."],["45","45","נוסף על החילוק בגדרם — דתורתו אומנתו הוא כשאין מתבטל מלימודו כלל (ראה לעיל הערה 26), ועוסק בצ״צ הוא גם כשעוסק בזה רק בשעה זו [כפשטות לשון הרמב״ם וכו׳ (דלקמן הערה 47), „הי׳ עוסק בצרכי רבים כו׳”]."],["46","46","בהנסמן בתחילת הערה 32. רמב״ם הל׳ ק״ש פ״ב ה״ה (וכ״מ שם)."],["47","47","רמב״ם שם. שו״ע (ואדה״ז) או״ח ס״ע ס״ד. שו״ע אדה״ז סו״ס צג. וראה לח״מ (הל׳ ק״ש שם), שא״ל כמ״ש הב״י (סי׳ ע) דמקור הרמב״ם הוא מהא דירושלמי ברכות (פ״ה ה״א) „העוסק בצ״צ כעוסק בד״ת”, ד„כאן צרכי רבים עדיף מד״ת בתורתו אומנתו כו׳”, עיי״ש. וראה כס״מ הל׳ ק״ש שם. שו״ע אדה״ז שם."],["48","48","אף שבשו״ע אדה״ז (ס״ע שם) כתב: בד״א בדורות הראשונים שהיו עוסקים עמהם לש״ש כו׳* — הרי מסיים: „אין מי שישתדל אלא הוא שאז אפי׳ עוסק בהצלת ממונם לבד כו׳ ולא יפסיק”. וכ״ש בנדו״ד בענין של הצלת נפשות — נשמות — ממש."],["49","49","סנהדרין יז, א. פרש״י בהעלותך יא, כח. ובתנחומא וארא (ה) ושמו״ר (פ״י, ב): משכח תלמודו."],["50","50","כידוע שפורים הי׳ ההצלה של גופות בנ״י (משא״כ חנוכה — לבוש או״ח סי׳ עת״ר ס״ב. ט״ז שם סק״ג)."],["51","51","רמב״ם הל׳ תשובה פ״ז ה״ה. וראה אגה״ת פי״א. *) ודלא כדחיית הכס״מ (הל׳ ק״ש שם) ד„מ״ש (הר״ר מנוח) ודוקא בדורות הראשונים אין לו טעם”."]]],[1300161394,"<h3>תשא</h3>\nא. אויפן פסוק1 „זה יתנו .. מחצית השקל\" זאגן רז\"ל2 (און רש\"י ברענגט עס אראפ בפירושו על התורה<sup data-n=\"3\">3</sup> „אמר רבי מאיר כמין מטבע של אש הוציא הקב\"ה מתחת כסא כבודו והראהו למשה ואמר לו זה יתנו כזה יתנו\".\nבדומה לזה — וואס דער אויבערשטער האט משה'ן געוויזן א דוגמא פון דער זאך אויף וועלכער ער האט אים אנגעזאגט — געפינט מען באַ כמה ענינים4: א) „נתקשה משה במעשה המנורה עד שהראה לו הקב\"ה מנורה של אש\"5, ב) „נתקשה משה על מולד הלבנה .. והראה לו באצבע את הלבנה ברקיע ואמר לו כזה ראה וקדש\"6, ג) ביים איסור פון שרצים — „וזה לכם הטמא\"7 (און נאך ענינים<sup data-n=\"8\">8</sup>.\nאיז ניט מובן9: בשלמא באַ אנדערע זאכן קען מען פארשטיין פארוואס דער אויבערשטער האט דאס אים געדארפט באווייזן10, ווייל זיי אנטהאלטן אין זיך פרטים און ציורים מסובכים: די מנורה, לדוגמא, האט געהאט אין זיך די גביעים כפתורים ופרחים און זיי אלע האבן גע־דארפט זיין „מקשה אחת\" און צוזאמען דערמיט יעדערער אין א באשטימטן ארט אין דער מנורה, אין זיין ספע־ציעלער פארם וכו'; עד\"ז האט מען ביי מולד הלבנה געמוזט וויסן גענוי „באיזו שיעור תראה ותהי' ראוי' לקדש\"11 (און מ'זאל וויסן מיט א וודאות אז דאס איז די לבנה12 און קענען מתאר זיין אופן עמידתה ברקיע — די אלע פרטים וואס די גמרא רעכנט אויס ביי בדיקת העדים<sup data-n=\"13\">13</sup> [און אזוי אויך די שרצים — וואס ניט אלע פון זיי האט מען גע־וואוסט ווי זיי זעען אויס14].",[["1","1","פרשתנו ל, יג."],["2","2","ירושלמי שקלים פ\"א ה\"ד. תנחומא פרשתנו ט. נשא יא. במדב\"ר פי\"ב, ג. פסיקתא דר\"כ פ\"ב (כי תשא). פסיקתא רבתי פט\"ז (בסופו). — ראה תו\"ש עה\"פ — בכהנ\"ל בשינויים קלים. ובפס\"ר פ\"י (בסופו): מטבע של אש קטן; ושם לפנ\"ז: כמין מטבע של שערה של אש. אבל שם לא הובא בשם ר' מאיר. ובתיב\"ע עה\"פ: דין שיעורא איתחמי למשה בטוורא הי כדינרא דאשא והיכדין א\"ל כדין יתנון."],["3","3","אבל ליתא שם „מתחת כסא כבודו\" (בבמדרש תהלים מזמור צא. פס\"ר הנ\"ל), ומוסיף „ומשקלה מחצית השקל\". וראה לקמן בפנים."],["4","4","מנחות כט, א. מכילתא בא יב, ב. ספרי בהעלותך ח, ד. שמו\"ר פט\"ו, כח. ועוד. וראה ראא\"ם וגו\"א בפרש\"י פרשתנו, ובפרש\"י שמיני יא, ב. בהעלותך שם."],["5","5","לשון רש\"י תרומה כה, מ. ובגמ' שם בתנא דבי ר' ישמעאל „עד שהראה לו הקב\"ה באצבעו\" (ועד\"ז במכילתא וספרי שם). וכ\"ה בפרש\"י בהעלותך שם. וראה ראא\"ם וגו\"א תרומה ובהעלותך שם."],["6","6","לשון רש\"י בא שם."],["7","7","שמיני יא, כט. וראה רש\"י שם יא, ב."],["8","8","במנחות (ומכילתא) שם „אף הלכות שחיטה\". וראה תוד\"ה שלשה שם. ובשמו\"ר שם: ד' דברים .. הראהו שמן המשחה. משא\"כ הנאמר לפנ\"ז במנחות שם: „ארון של אש ושלחן של אש כו' ירדו מן השמים וראה משה ועשה כמותם\" — לא נתקשה בהם (ראה גו\"א תרומה שם)."],["9","9","כמו שהקשה בגו\"א בפרש\"י פרשתנו. אלשיך עה\"פ (קושיא הא'). זית רענן ליל\"ש פרשתנו. אוה\"ח עה\"פ."],["10","10","ראה גו\"א שמיני שם. חדא\"ג מנחות שם."],["11","11","לשון רש\"י בא שם. וראה ראא\"ם וגו\"א שם."],["12","12","ובפרט לפי' הראגוצובי (ראה צפע\"נ עה\"ת בא שם)."],["13","13","בפרש\"י מנחות שם ד\"ה ראש חודש: בשעת מולד לבנה אינה נראית כ\"א מעט ואינה ניכרת כדאמרינן בר\"ה כזה ראיתם אם כזה ראיתם."],["14","14","בפרש\"י שם: שרצים, לא הי' מכיר איזה טמא"]]],[1300161395,"משא\"כ ביי מחצית השקל15 וואס איז ניט פארבונדן מיט קיינע שוועריקייטן צו וויסן וואס דאס מיינט16, און מען גע־פינט עס שוין באַ אליעזר עבד אברהם17, וואלט דאך געווען גענוג ווען דער אויבערשטער זאגט אים אן אז מ'זאל געבן א מחצית השקל — פאַר־וואס האט דער אויבערשטער אויך דאַ געוויזן אים א „מטבע של אש\"?\nתוספות אין מנחות18 איז מסביר, פארוואס די גמרא דארט רעכנט ניט מחצית השקל צווישן די ענינים וואס נתקשה בהם משה (מנורה, קידוש החודש און שרצים): „דלא שייך התם נתקשה, אלא משום דלא הוה ידע19 בשום ענין אם לא הי' מראהו\". ולכאורה איז דאס אינגאַנצן ניט פארשטאַנדיק: פארוואס וואלט משה ניט געוואוסט וואס עס איז דער (שיעור פון א) מחצית השקל20? און — אפילו אויב ער האט עס ניט געוואוסט, האט דער אויבערשטער אים געקענט מפרט זיין בדיבור וויפל ס'דארף זיין21 דער שיעור ומשקל22.\nנאַכמער: אפילו נניח אז דעם גענויעם שיעור פון מחצית השקל קען מען וויסן נאר דורך א דוגמא מוחשית — פאַר־וואס האט דאס געדארפט זיין א „מטבע של אש\"? אדרבא — עס וואלט געווען גענויער צו ווייזן אים א מחצית השקל23 וואס מ'דארף געבן בפועל — של כסף, אזוי ווי דער אויבערשטער האט אים באוויזן לבנה ברקיע (ועד\"ז די שרצים<sup data-n=\"24\">24</sup>.\n[דאס וואס דער אויבערשטער האט אים באוויזן א „מנורה של אש\" איז פאַר־שטאַנדיק, היות די מציאות פון אזא מנורת זהב איז נאַך דאַן ניט געווען",[["","","ואיזה טהור. הלכות שחיטה, לא הי' מבין מהיכן היא מוגרמת."],["15","15","להעיר מרע\"מ בזח\"ב (קנז, סע\"ב): ומכלא לא אתקשי לך למעבד אלא תלת מלין דרשימין באתוון דשמך מנורה שקלים החודש."],["16","16","ראה דברי דוד (להט\"ז) בפרש\"י: דשם לא מנו אלא דברים שנתקשה משה להבינם כי יש הרבה פרטים בהם כו' אבל כאן לא הי' קושי במטבע של מחצית השקל."],["17","17","ח\"ש כד, כב ובפרש\"י."],["18","18","שם ד\"ה שלשה."],["19","19","ובשטמ\"ק שם: ס\"א איזה מטבע יביאו אם לא כו'."],["20","20","וצ\"ע בזית רענן שם (שלאחרי שמקשה „בשלמא מנורה לא הי' לו להבין אם לא הי' מראה לו אבל הכא מה הוצרך להראות לו הול\"ל שיתנו מחצית השקל\", מוסיף): והתוס' במנחות כתבו כיוצא בזה. ואולי צ\"ל: והתוס' בחולין (הובא לקמן בפנים. וראה לקמן הערה 29)."],["21","21","ועד\"ז יש להקשות בתי' (הא') שבגו\"א בפרשתנו. ועפ\"י המבואר לקמן בפנים יש לבאר גם פירושו."],["22","22","ראה משכיל לדוד בפרש\"י, שהקשה על פי' התוס' (ולפי פירושו: למאן דדריש דהראהו מטבע של אש .. נתקשה כמו אינך דה\"נ יש קושי בדקדוק המשקל), וי\"ל כוונת התוס' (ובפרט ע\"פ גירסת השטמ\"ק) דכל מטבע הוא לא רק שיעור ומשקל, כ\"א יש לו גם צורה וציור מסוים, וזה קשה להודיע כ\"א הוצרך להראותו. ובפרט אם נאמר שעדיין לא הי' מטבע כזו* (ובפרש\"י ח\"ש שם היינו רק משקל. וכמובן דוחק הוא) (ולהעיר מרמב\"ן פרשתנו ריש פסוק יג). אבל עדיין אינו מובן כי אין לאמר שזה קשה להבין יותר מצורת המנורה והחודש כו' עד „דלא שייך התם נתקשה אלא משום דלא הוה ידע בשום ענין\"."],["23","23","ראה חלקי אבנים בפרש\"י."],["24","24","ראה תי' הב' בגו\"א. אלשיך ודברי דוד שם ע\"ד הדרוש וכו'. *) ראה חלקי אבנים (להרב דוד לידא פירדא, שנת תג\"ן. ניו יארק תשל\"ג) בפרש\"י, צפע\"נ הל' שקלים נסמן לקמן הערה 56 ועוד."]]],[1300161396,"בעולם25: משא\"כ מחצית השקל א מטבע מיט א שיעור ומשקל גשמי26].\nאויך דארף מען פארשטיין: תוס' אין חולין27 פארענטפערט די שאלה הנ\"ל פון תוס' אין מנחות (פארוואס ווערט מחצית השקל ניט גערעכנט צוזאמען מיט די אנדערע ענינים וואס „נתקשה משה\"): „הני אע\"פ שהראהו לא נתקשה בהן אלא שתמה על הדבר מה יוכל אדם ליתן כופר נפשו28 הראהו הקב\"ה כו'\" — ולכאורה זיינען די צוויי תירוצי התוס' סברות הפוכות: לויט תוס' אין מנחות איז במחה\"ש מער ווי „נתקשה משה\", ווייל „לא הוה ידע בשום ענין אם לא הי' מראהו\", משא\"כ לויט תוס' אין חולין איז משה מלכתחילה „לא נתקשה בהן\", ער וואלט געוואוסט דעם שיעור בדיוק אויך ווען דער אויבערשטער וואלט אים ניט באוויזן; און דאס וואס „הראהו\" איז צוליב אן אנדער טעם29.\nב. וועט מען דאס פארשטיין בהקדם לבאר וואס דער רמב\"ם זאגט30 ביי דער מצוה פון נתינת מחצית השקל: הצווי שנצטוינו ליתן מחצית השקל בכל שנה והוא אמרו יתעלה ונתנו איש כופר נפשו ואמר זה יתנו31. ולכאורה: צוליב וואס דארף ער ברענגען ביידע פסוקים און איז זיך ניט מסתפק מיט דעם פסוק „זה יתנו\"32? ובפרט אז דער ציווי אויף נתינת מחצית השקל שטייט דוקא אין דעם פסוק — „זה יתנו כל העובר על הפקודים מחצית השקל\"33 (דאקעגן אין פסוק „ונתנו איש כופר נפשו\" ווערט ניט דערמאנט וועגן דעם עצם מצוה פון נתינת מחצית השקל, נאר — אז אויב „תשא את ראש בנ\"י\" איז „ונתנו\" א „כופר נפשו\" כדי אז „לא יהי' בהם נגף בפקוד אותם\").\nג. איז דער ביאור בזה: אין דער מצוה פון נתינת מחצית השקל זיינען",[["25","25","ואף שהקב\"ה הי' יכול לעשות מנורה זהב להראותו, הרי המנורה שבמשכן צריכה שתיעשה ע\"י משה (בנ\"י) — ראה גו\"א בפרש\"י תרומה ובהעלותך שם. אבל ראה ראא\"ם שם —. ולא עביד קוב\"ה ניסא למגנא לברוא מנורת זהב ולבטלה אח\"כ (שהרי אסור להשתמש בה לבד במשכן). ואולי גם י\"ל דהאיסור לעשות מנורות בת ז' כו' (ר\"ה כד, סע\"א ואילך. וש\"נ) חל גם על למעלה. משא\"כ זה במחצית השקל. ועוד ועיקר: בהמנורה נאמר „אשר אתה מראה בהר\" (תרומה שם, ראה פרש\"י שם. מנחות שם). משא\"כ מחה\"ש."],["26","26","ובנוגע לגודל וצורת המטבע — נראה בפועל במטבעות דזמן הבית וכו' שלא הי' מדייקין בזה."],["27","27","מב, א ד\"ה זאת."],["28","28","ועד\"ז הוא בשטמ\"ק לתוס' מנחות שם: א\"נ התם לא נתקשה רק בהא דדבר מועט יכפר על עון העגל,"],["29","29","כוונת התוס' בחולין בפשטות היא: הקב\"ה עדיין לא אמר לו שיתנו מחצית השקל, ותמיהתו „מה יוכל אדם ליתן כופר נפשו\" היתה ע\"ז שאמר לו הקב\"ה „ונתנו איש כופר נפשו\", [וכדמוכח במדרשים הנ\"ל הערה 2, וכן ממ\"ש במדרשים הנ\"ל (פסיקתא דר\"כ שם לפנ\"ז, תנחומא פרשתנו יא (ובכ\"מ)), שהיו סבורין שצריך ליתן ככר כסף כו']. ואולי מפרש כן הזית רענן גם בתוס' מנחות „דלא הוה ידע בשום ענין\" מאמירת הקב\"ה „ונתנו איש כופר נפשו\" לחוד (וראה צאן קדשים לתוס' מנחות שם). אבל הא גופא צ\"ע: למה הוצרך להראות לו מטבע של אש, ולא די באמירה שיתנו מחצית השקל."],["30","30","בסהמ\"צ מ\"ע קעא."],["31","31","כ\"ה בהעתקת קאפח. ובסהמ\"צ שלפנינו „ואמרו זה יתנו כל העובר על הפקודים מבן עשרים וגו'\" עירוב ב' הפסוקים (יג-יד). ובהעתקת העליר ליתא „מבן עשרים וגו'\"."],["32","32","משא\"כ בכו\"כ מקומות בסהמ\"צ שמביא יותר מפסוק אחד כותב „וכבר נכפל זה הציווי\" (וכיו\"ב) ומביא הנאמר במק\"א, משא\"כ כאן. ואפי' אם רוצה להביא ב' הפסוקים הול\"ל להביאן זה אחר זה ולא להפסיק „ואמר\" (ואמרו). כאילו שזהו עוד עניין. וראה ברכות ומכות בסופן (ועוד) „מאי ואומר\"."],["33","33","ורק כתוב זה הביא במנין המצות שבריש ספר היד ובפיה\"מ ריש שקלים. וראה תוו\"ט שקלים פ\"א מ\"ד: „ולדברי הרב שכתב כו'\"."]]],[1300161397,"פאראן צוויי דינים: א) עס דארף זיין אן איינמאליקע נתינה, ווי דער רמב\"ם34 פסק'נט „ואינו נותנו בפעמים רבות היום מעט ולמחר מעט אלא נותנו כולו כאחת בפעם אחת\". ב) מ'דארף געבן א מטבע פון א „מחצית השקל כסף\"35 (ופשיטא ניט קיין „שוה כסף\" אין באטרעף פון א מחצית השקל<sup data-n=\"36\">36</sup>.\nבנוגע דעם וואס דער רמב\"ם פסק'נט אז מ'דארף דאס געבן בפעם אחת, איז מסביר דער ראגאטשאווער37 דעם טעם, אז די נתינת מחצית השקל האט א דין פון א קרבן און עס איז א גדר פון כפרה — און ביי כפרה העלפט ניט קיין נתינה לחצאין (ווי די גמרא38 זאגט בנוגע גזל הגר „החזירהו (צום כהן) חצאין לא יצא מאי טעמא אשם קריי' רחמנא\").\nאין דעם (אז דאס איז אן ענין פון קרבן וכפרה) קען מען לערנען אויף צוויי אופנים: א) דער גדר הכפרה פון מחצית השקל באשטייט אין דעם, וואס דערמיט ווערן געקויפט די קרבנות\nצבור במשך השנה וועלכע זיינען לכפרה39; ב) די עצם נתינה פון מחצית השקל איז אן ענין פון כפרה — א קרבן יחיד.\nויש לומר, אז דאס איז א מחלוקת צווישן רש\"י און רמב\"ם: רש\"י איז מפרש40 „ועל אותה תרומה נאמר לכפר על נפשותיכם שהקרבנות לכפרה הם באים\", אז ביי דער תרומה פון מחצית השקל שטייט „לכפר על נפשותיכם\" — לשון רבים, ד.ה. א כפרה אויפן צבור, היות אז דאס ווערט גענוצט פאר קרבנות צבור, וואס זייער ענין איז כפרה41.\nדער רמב\"ם אבער לערנט דאס ארויס כנ\"ל פון פסוק „ונתנו איש כופר נפשו\", וואס שטייט בלשון יחיד, עס מיינט ניט די כפרה פון קרבנות צבור, נאר אז דאס האט דעם דין „קרבן בפני עצמו\"42 — די נתינה גופא איז א גדר כפרה43.\nויש לומר אז דאס איז דער טעם אויף נאך א חילוק צווישן רש\"י און רמב\"ם: לדעת רש\"י44 דארף מען מכוון זיין",[["34","34","ריש הל' שקלים."],["35","35","לשון הרמב\"ם שם. ובהלכה ה': מחה\"ש זו מצותה שיתן מחצית מטבע של אותו הזמן כו'. וראה שם הי\"ז. ובפיה\"מ להרמב\"ם בכורות פ\"ח מ\"ח: מחצית השקל שהוא צריך להיות כסף צרוף עשוי מטבע* כמו שנתבאר בשקלים. ובפרש\"י בכורות שם מט, ב במשנה „אין מביאין שם אלא מטבע של חצי שקלים\". ובשו\"ת הריב\"ש סי' סו: וכן הי' לו לתת מחצית השקל במטבע כסף בעינו. אבל יש סוברין שאפשר ליתן גם פרוטות — ראה חינוך מצוה קה. ובמנ\"ח שם סוסק\"א. ועוד."],["36","36","משנה בכורות שם."],["37","37","צפע\"נ השלמה ג, א ואילך. וראה צפע\"נ לרמב\"ם ריש הל' שקלים."],["38","38","ב\"ק קי, א וברש\"י. „ושם דף מ' ע\"א גבי כופר\" (צפע\"נ שם)."],["39","39","ראה שבועות בתחלתה."],["40","40","פרשתנו ל, טו. ועד\"ז בפרש\"י מגילה כט, ב (ד\"ה שלש). וראה חזקוני פסוק יב."],["41","41","ראה גם תוספתא שקלים פ\"א, ב. וצע\"ק במ\"ש בצפע\"נ השלמה שם „ולכך מבואר בתוספתא ספ\"א דשקלים דיש עליהם שם כפרה\" בהמשך למש\"כ „יש עליו שם קרבן בפ\"ע\". וראה צפע\"נ הל' שקלים פ\"א ה\"ט."],["42","42","לשון הצפע\"נ בהשלמה שם."],["43","43","ולכאורה כן משמע גם ממ\"ש הרמב\"ן ריש פרשתנו (פסוק יב) באמצע דבריו: ומ\"מ אין אדם רשאי לפחות וליתן פחות מחצי סלע בין יחיד בין רבים, כי אין כופר הנפש פחות מכן כדכתיב זה יתנו גו'. אבל בסוף דבריו כתב: שכל הצריך כפרה שהגיע לכלל חיוב המצות יביא מחצית השקל אחד לקרבנות. (וראה ראא\"ם שם בפרש\"י). וראה שקלים פ\"ב סה\"ג. תנחומא פרשתנו יו\"ד, ובכ\"מ."],["44","44","ד\"ה לרבות (מנחות נב, א) הובא בצפע\"נ השלמה שם. *) כ\"ה בהעתקת קאפח. ולפנינו: כסף מזוקק מצויר מטבע."]]],[1300161398,"בשעת דער נתינה פון מחצית השקל אז מ'גיט דאס צוליב די קרבנות צבור; פון רמב\"ם אבער איז משמע אז דאס איז א באזונדער ענין, ווי ס'איז מוכח פון דעם וואס אין דעם ערשטן פרק אין הלכות שקלים רעדט ער בלויז וועגן דער מצוה און דעם אופן פון נתינת מחצית השקל (און ער זאגט ניט אז וויבאלד מ'דארף מקריב זיין קרבנות צבור מתרומה חדשה, דעריבער45 איז א „מ\"ע מה\"ת ליתן כל איש מישראל מחצית השקל בכל שנה ושנה\". און נאכמער — ער דערמאנט אינגאנצן ניט אז מען קויפט מיט די מחצית השקל קרבנות צבור<sup data-n=\"46\">46</sup>, און אויך אין פרק ד' הייבט ער אן בסגנון פון אן ענין בפ\"ע חדש לגמרי*46: תרומות הלשכה מה יעשה בה, לוקחין ממנה תמידין של כל יום והמוספין וכל קרבנות הצבור כו'. ד.ה. אז (איז) דעם עצם נתינה פון מחצית השקל איז ניט (נוגע אז דאס איז) צוליב קרבנות צבור (נאר ס'איז א דין קרבן וכפרה בפ\"ע) און דאס וואס לפועל קויפט מען די קרבנות צבור פון תרומת הלשכה (מחצית השקל) איז עס א באזונדער ענין פאר זיך47.\nד. עפ\"ז איז מובן דער טעם וואס דער רמב\"ם ברענגט אין ספר המצות ביידע פסוקים הנ\"ל, ווייל פון יעדערן פון זיי לערנט מען אפ א באזונדער גדר המצוה פון נתינת מחצית השקל: פון „ונתנו איש כופר נפשו\" לערנט ער אפ, אז נתינת מחצית השקל איז אן ענין פון כפרה ע\"ד ווי א קרבן; פון „זה יתנו\" — וואס דער לשון „זה\" באווייזט אויף א נתינה פון איין זאך — מ'גיט עס ניט אלס א סכום וצירוף פון צען (באזונ־דערע) גרה (ובמילא האט אן ארט צו זאגן אז מען קען זיי אויך געבן ניט אלע מיט אמאל), נאר אלס איין מחצית השקל — (בלשון הרגצובי<sup data-n=\"48\">48</sup> א „שיעור העצמיי\" ניט קיין „שיעור מצטרף\".\nוואס פון דעם קומען ארויס די צוויי דינים: א דין אין דער נתינה בשייכות צום גברא און א דין אין דער „חפצא\" פון מחצית השקל: פון „ונתנו איש כופר נפשו\" ווייס מען49 דעם דין אין גברא,",[["45","45","ראה מגילה כט, ב. וש\"נ. שקלים פ\"א ה\"א. וראה ר\"ן מגילה שם ד\"ה מאי פרשת שקלים רב אמר. וראה ל' המאירי ריש שקלים (והמשנה הראשונה) „פירוש כבר ידעת כו'\"."],["46","46","גם לא בה\"ט שם שכ' „בא' באדר משמיעין על השקלים כדי שיכין כל אחד ואחד מחצית השקל שלו ויהי' עתיד ליתן כו'\" (וגם אינו מוסיף למקדש. ראה ל' ר\"ח מגילה שם). ובפיהמ\"ש ריש מס' שקלים: ופירוש משמיעין מכריזין עליהם שיכינו בני אדם שקליהם כדי שתהי' תרומת הלשכה בזמנה כלומר בר\"ח ניסן כו'. *46) אף שיש לומר שתפס לשון המשנה רפ\"ד דשקלים."],["47","47","עפ\"ז (אם שקלים הוא מצוה בפ\"ע או בשביל הקרבנות) יש לבאר לכאורה מחלוקת רב ושמואל (מגילה כט, ב) אם פרשת שקלים הוא „צו את בני ישראל ואמרת אליהם את קרבני לחמי\", או „כי תשא\". ועיי\"ש בקושית הגמרא: בשלמא למ\"ד כי תשא כו'. וראה ר\"ן שם. אבל לפי תירוץ הגמרא שם טעמא מאי כדר' טבי (ראה פרש\"י שם) וכן מהמשך הגמרא יש לדחות דאינו שייך לזה. וראה צפע\"נ השלמה שם. ואכ\"מ."],["48","48","צפע\"נ הלכות תשובה פ\"ב ה\"ב. ומצויין „ע\"י\" מש\"כ פ\"א מהל' שקלים\". וראה בהנסמן בהערה 51."],["49","49","בקרית ספר ריש הלכות שקלים: ואינו נותנו מעט אלא כולו כאחד בפעם אחד דכתיב לא ימעיט ממחצית השקל דאי למימר שיתן חצי שקל הוה סגי לכתוב יתן חצי שקל וקאמר לא ימעיט דרוצה לומר אפילו בנתינה לא ימעיט ממחצית שקל (וראה עד\"ז נחל קדומים להחידא פרשתנו עה\"פ). אבל אף שהרמב\"ם ריש הלכות שקלים הביא הכתוב „העשיר לא ירבה והדל לא ימעיט גו'\" הרי הביאו ע\"ז ד„אפילו עני המתפרנס מן הצדקה חייב ושואל מאחרים כו'\". ולא מצינו שיביא הכתוב לעצם חיוב המצוה. ועוד: לדעתו הרי\"ז רק דין פרטי בנתינה דלא ימעיט ומזה שהרמב\"ם כתבו תיכף בהלכה א' משמע"]]],[1300161399,"אז ער דארף עס געבן בבת אחת, ניט לחצאין50 כנ\"ל; און פון „זה יתנו\" (די „זאך\" גופא זאל מען געבן) ווערט אפגעלערנט דער דין בנוגע „חפצא\", אז דער חיוב איז „זה (יתנו)\" — די מציאות51 פון א מחצית השקל — א מטבע פון א מחצית השקל52, און ניט כסף לויטן שיעור און משקל פון מחצית השקל.\n[ויש לומר, אז דאס איז מדוייק און מודגש אין די צוויי לשונות אין רמב\"ם „נותנו: א) כולו כאחת ב) בפעם אחת\"53].\nה. עפ\"ז וועט מען פארשטיין וואס דער פירוש פון „זה יתנו\" איז, „כמין מטבע של אש הוציא הקב\"ה מתחת כסא כבודו והראהו למשה ואמר לו זה יתנו כזה יתנו\" און ס'איז מובן דער טעם וואס דער אויבערשטער האט אים באוויזן דווקא א מטבע של אש.\nדער חילוק צווישן אש און אנדערע יסודות פון חומר הבריאה*53 איז: אנדערע סוגי חומר (רוח מים און עפר) ווערן געמאסטן לויט זייער כמות, פאר־נעם אין מקום, אדער אין ערך ושווי (זייער מאס אין גשמיות'דיקן שטח אדער אין כמות השוויות והערך). „אש\" ווערט ניט געמאסטן לויט איר תפיסת מקום און איז ניט מוגבל אין א באשטימטן שטח אין מקום, די מציאות פון „אש\" איז מער אן איכות'דיקע54, און אויך א מעט אש איז מתפשט והולך55.\nאון דעריבער, ווען דער אויבערשטער וואלט אים באוויזן א מחצית השקל כסף, וואלט נאך אלץ ניט געווען קלאר, וואס דער גדר המצוה איז און וואס אידן דארפן געבן: צי ס'איז אנגעזאגט גע־וואַרן און ס'איז גענוג די שוויות וכו' פון א מחצית השקל כסף. ובמילא קען מען",[["","","שזהו מעצם גדר המצוה. וי\"ל דנפק\"מ גם בפועל אם קיים המצוה אלא שחסר פרט זה, או שלא קיים המצוה כלל. וראה רי\"ט אלגזי הלכות בכורות פ\"ח אות פא בסופו. רי\"פ פערלא לרס\"ג מ\"ע ז (צב, ג). עשה כ' (קמח, ג ואילך). ועוד."],["50","50","ואף שזה נכלל כבר בהלימוד ד„זה יתנו\", דמכיון שצריך ליתן מטבע כסף הרי בדרך ממילא אא\"פ להיות נתינה לחצאין (ולהעיר שבמנין המצוות וכן בפיה\"מ שקלים הביא רק הכתוב זה יתנו, כנ\"ל הערה 33), י\"ל דממעט נתינת חתיכות מטבע זה עד שיצטרפו למטבע שלם. או — מכיון שהרמב\"ם הביא גם הפסוק „ונתנו איש כופר נפשו\" להודיע (גם) גדר מצות נתינת מחצית השקל דהגברא, שהוא כופר נפשו, הרי נמצא דכאשר נותנו בפעמים רבות חסר לא רק בקיום „זה יתנו\" (דההפצא), אלא גם בהקיום ד„יתנו איש כופר נפשו\" — הנתינה דהגברא."],["51","51","ראה צפע\"נ מהד\"ת ב, ג. ע, ג."],["52","52","וזה שמצינו לדעת הרמב\"ם (רפ\"ג דהל' שקלים) דשנים נותנין שקל אחד על שניהם, הרי א) כתב „שנים שנתנו על שניהם חייבין בקלבון\" ולא כ' „שנים נותנין שקל על שניהם\"*. ב) ועיקר: י\"ל (לדעת הרמב\"ם) גם אז נחשב שכ\"א נתן מטבע מחצית השקל, וזהו הטעם לחיוב נתינת „קלבון\", דלפי שחייבין ליתן מטבע מחצית השקל כסף, לכן כשנותן שקל (על שניהם), בכדי שיקיים מצות נתינת מחצית השקל צריכין (השולחני או הגזבר המקבל) להחליף השקל על ב' חצאי שקלים וזה ניתן להקדש (שרק אז נחשב נתינתו לקיים המצוה ד„זה יתנו\") וממילא חייבין ב„קלבון\". וראה רמב\"ם שם הי\"ו. *) להעיר משו\"ת חמדת שלמה יו\"ד סי' לב."],["53","53","וצע\"ק אריכות לשון הרמב\"ם שם בהשלילה „ואינו נותנו בפעמים רבות (ומוסיף) היום מעט ולמחר מעט\", ואולי הם ב' ענינים ובסדר ד„זו ואצ\"ל זו\". ולכאורה כצ\"ל (זו ואצ\"ל זו) גם במש\"כ „כולו כאחת בפעם אחת\" אף אם נפרש (דלא כבפנים, אלא) שניהם בהנתינה דגברא. ולהעיר מהגירסא ברמב\"ם (פרענקל) „פעם אחת\". ואכ\"מ. *53) רמב\"ם הל' יסוה\"ת רפ\"ד."],["54","54","עד\"ז יש להסביר גם בפי' הגו\"א פרשתנו (בתי' הא') במה שהוצרך להראותו מטבע של אש דוקא. ואכ\"מ."],["55","55","להעיר מזית רענן ליל\"ש שם."]]],[1300161400,"געבן וואס מ'וויל, אבי דאס איז ווערט א מחצית השקל, אדער עס דארף זיין דוקא כסף לויטן משקל פון א מחצית השקל, אדער דוקא א מטבע וואס משקלה איז מחצית השקל כסף.\nאון דעריבער האט ער אים באוויזן „כמין מטבע של אש\" (וואס „משקלה\" איז „מחצית השקל\"), אז די מצוה איז ניט די כמות — די שוויות אדער אפילו כסף במשקל פון א מחצית השקל, נאר „די זאך\" גופא, די מציאות פון דער מטבע פון מחצית השקל56.\n— ד.ה. ניט דער גדר המצוה איז געבן א משקל כסף אין ערך פון מחצית השקל (ולכל היותר — איז עס א תנאי (צדדי) אז דער כסף דארף זיין בצורת מטבע) נאר דאס איז דער גדר המצוה: „זה יתנו\" געבן די מטבע — מחצית השקל.\nאון דאס זאגט זיך אויס אין „מטבע של אש\" דוקא, וואס אש איז ניט א ענין וואס מעסט זיך מיט ערך ושוויות, כנ\"ל. נאר זיין שיעור איז — די עצם מציאות פון אש,\nאון עס איז דאך פארשטאנדיק אז „מטבע של אש\" ממש קען מען ניט געבן — מיינט „זה\" — דער ענין מיוחד אין מטבע של אש ווי ער געפינט זיך אין מטבע של כסף.\nו. עפ\"ז וועט מען פארשטיין די צוויי תירוצים פון תוס' (הנ\"ל ס\"א) אז זיי זיינען ניט מחולק צווישן זיך, נאר זיי זיינען בהתאם צו די צוויי גדרים הנ\"ל אין נתינת מחצית השקל: אין מנחות זאגט תוס' „משום דלא הוה ידע (איזה מטבע יביאו<sup data-n=\"57\">57</sup> בשום ענין אם לא הי' מראהו\" —\nווען דער אויבערשטער ווייזט אים ניט א מטבע של אש, וואלט משה ניט געוואוסט (ניט נאר — נתקשה) דעם דין אז עס דארף זיין „זה יתנו\", דער תנאי אין חפצא פון דער מטבע כנ\"ל בארוכה.\nאין חולין זאגט תוס', אז משה'ס תמי' איז געווען אין דער נתינה פון גברא — „מה יוכל אדם ליתן כופר נפשו\" — דאס איז דאך ניט קיין קרבן58.\nז. לויט דעם — אז די תמי' פון משה'ן (כפי' התוס' אין חולין) איז גע־ווען דערפאר וואס ער האט נאך ניט געוואוסט אז מחצית השקל איז א קרבן — קומט אויס אז דאס וואס „הראהו מטבע של אש\" איז געווען59 (ניט נאר צו מודיע זיין דעם גדר המצוה אין חפצא פון מחצית השקל נאר) אויך א הסברה אין דער נתינה פון גברא (אלס כפרה — קרבן).\nדער ביאור בזה:\nאין כפרה זיינען דא צוויי ענינים: א) כפרה דורך קרבנות, „לכפר על נפשותיכם\", ב) „כופר נפשו\".\n„כפרה\" (ע\"י הקרבנות) מיינט (ווי",[["56","56","להעיר מצפע\"נ לרמב\"ם שם ה\"ג וה\"ה: וזהו מה דאמרינן בירושלמי דשקלים כו' ר\"ל שני דברים אחד דדוקא כזה ר\"ל כמשקלו וגם מטבע ונ\"מ דאם יפחת כו'. וראה מכתבי תורה מכתב פט."],["57","57","גירסת השיטה מקובצת שם כנ\"ל הערה 19."],["58","58","להעיר על חילוקי הסוגיות בהא דר\"מ שהראהו לו כמין מטבע של אש: בירושלמי שקלים הובא לענין החפצא דמחצית השקל (בחיוב קלבון), איזה מטבע צריך ליתן (ראה קרבן העדה שם ובמפרשים): במדרשים הנ\"ל (הערה 2) — לענין הכפרה בהמשך לתמיהת משה מי יוכל ליתן כופר נפשו."],["59","59","לדעת התוס'. משא\"כ לדעת רש\"י (בפירושו עה\"ת), שס\"ל שהוא כפשוטו „זה יתנו\" להודיעו הדין בהחפצא דמחצית השקל. ולהעיר דעפ\"י פי' הא' דרש\"י כל המשך הפרשה מדבר רק במחה\"ש בשביל מנין בנ\"י אלא ש„מהמנין הזה נעשו האדנים\". ואכ\"מ."]]],[1300161401,"דער טייטש פון כפרה — פארגעבונג) אז עס ווערט פארגעבן און אראפגע־נומען די טומאת החטא; „כופר נפשו\" איז ניט קיין ענין פון אראפנעמען דעם חטא, נאר כופר: „אויסלייזונג פון נפש\", ד.ה. דערמיט ווערט אויפגעטאן אז דער נפש ווערט פארביטן60 און במילא אויסגעלייזט, ווי א נייע מציאות.\nוואס די צוויי ענינים זיינען בכללות די צוויי סוגים וואס מ'געפינט באַ דער טהרה פון טומאה אין פשטות61.\nטבילה במים נעמט אראפ די טומאה; טבילה באש, און ווי די גמרא62 זאגט איז „עיקר טבילותא בנורא\", איז תוכנה [ניט אראפנעמען די טומאה63, נאר] בדוגמת פעולת האש כפשוטה, וואס איר אופטו איז — „מחזירן לכבשן\" ווערט א נייע כלי64 ומציאות.\nאון דאס איז דער חילוק צווישן דער כפרה פון קרבנות און „כופר נפשו\" וואס דורך מחצית השקל: די קרבנות זיינען (בכלל) מכפר אויף שגגות65 (ועכ\"פ) ניט אויף כריתות ומיתות ב\"ד66; די נתינה\nפון מחצית השקל איז ענינה, ע\"ד ווי עס איז געווען צום ערשטן מאל, צו מכפר זיין אויפן חטא העגל67 וואס רירט אן אין עצם מציאות — ס'איז א חיוב מיתה; און דעריבער דארף זיין „כופר נפשו\", אז עס זאל ווערן א נייע מציאות.\nאון (אויך) דאס האט דער אויבערשטער מגלה געווען דורך ווייזן אים א „מטבע של אש\", אז די כפרה פון מחצית השקל איז תוכנה אזוי ווי (די טבילה ב)אש — עס איז פועל אז עס ווערט א מציאות חדשה68.\nח. אע\"פ אז דאס וואס דער אויבערשטער האט באוויזן משה'ן „מטבע של אש\" איז געווען כדי צו מבאר זיין אז די נתינה פון מחצית השקל איז ניט אן ענין פון שווי ומשקל, נאר — „זה יתנו\" (כנ\"ל בארוכה) — זאגט אבער רש\"י אז די „מטבע של אש\" האט געהאט א משקל69 דמחצית השקל",[["60","60","ע\"ד „בעליו יומת. אם כופר יושת עליו ונתן פדיון נפשו גו'\" (משפטים כא, כט-ל)."],["61","61","להעיר מצפע\"נ הל' תשובה שם: ב' עניינים להסיר הטומאה, ולטהרה, וב' ההסברות בזה. ואכ\"מ."],["62","62","סנהדרין לט, סע\"א."],["63","63","להעיר, דמים עצמם אפשר שיקבלו טומאה, משא\"כ אש. וראה ברכות כב, א: מה אש כו'."],["64","64","ראה זבחים צו, א. ובתוד\"ה אלא שם. תוד\"ה התורה (פסחים ל, ב). רא\"ש שם (פ\"ב סי' ז). טור או\"ח סי' תנא ובב\"י שם. שו\"ע שם סוס\"א, ואדה\"ז ס\"ט."],["65","65","לא רק קרבנות היחיד חטאת ואשם כו' כ\"א גם בקרבנות צבור — ראה שבועות בתחלתה. וראה סהמ\"צ להצ\"צ (דרך מצותיך) מצות עגלה ערופה (ובציונים לשם)."],["66","66","ורק שעיר המשתלח מכפר על כריתות ומיתות ב\"ד (שבועות שם בסוף המשנה. רמב\"ם הל' תשובה פ\"א ה\"ב)."],["67","67","ראה ירושלמי ותנחומא שבהערה 43. ובמדרשים הנ\"ל הערה 2. ולגירסת השטמ\"ק מפורש הוא בתוס' מנחות (כנ\"ל הערה 28)."],["68","68","ועפ\"ז יובן מש\"כ בתוס' חולין שם „הראהו הקב\"ה להבחין היטב ולהודיע לישראל\", דלפי פשטו אינו מובן: מה צריך „להבחין היטב ולהודיע לישראל\"*? ועפ\"י הנ\"ל יומתק, שהראהו הקב\"ה להבחין היטב גדר ותוכן הכפרה דמחצית השקל, שענינו (מטבע של) אש שנעשה מציאות חדשה. ועדיין אינו מובן לכאורה: זה שענינו הוא „כופר נפשו\" (ולא רק כפרה דקרבנות) הרי ידע גם לפנ\"ז „אלא שתמה על הדבר מה יוכל ליתן כופר נפשו\", והיינו איך זהו כופר נפשו ומה נתחדש לו בזה ש„הראהו מטבע של אש\"? ויובן עפ\"י המבואר לקמן בפנים."],["69","69","להעיר גם מתיב\"ע עה\"פ (הובא לעיל הערה 2). *) ולפי הנ\"ל דהראה הקב\"ה מטבע של אש ענינו להראותו גדר החפצא דמחצית השקל מובן בפשטות „להבחין היטב\" במטבע של אש, כנ\"ל בארוכה."]]],[1300161402,"— „הראה לו כמין מטבע של אש ומשקלה מחצית השקל\",\nאון פון דעם וואס דער אויבערשטער האט געמאכט א נס בתוך נס — ניט נאר „מטבע של אש\", נאר אז די מטבע של אש זאל האבן א משקל — איז מוכח, אז אויך אין דעם פרט פון „משקל\" האט דער אויבערשטער מחדש געווען אן ענין ביי משה'ן, וואס ווען ניט „הראה לו .. מטבע של אש ומשקלה כו'\" וואלט ער מדעת עצמו עס ניט געוואוסט.\nאין אנדערע ווערטער: אין דער נתינת פון מחצית השקל איז נוגע (ניט נאר דער עצם „מטבע של אש\", נאר) אויך אז דער מחצית השקל דארף זיין בדוגמא צו א „מטבע של אש\" וואס האט א משקל.\nט. וועט מען דאס פארשטיין בהקדם וואס תמיהת משה — „מה יוכל אדם ליתן כופר נפשו\" (ווי געבראכט פריער פון תוס') און דערפאר האט דער אויבערשטער באוויזן משה'ן מטבע של אש — איז מקורה אין מדרש70, און דארט איז מבואר אז דאס („ונתנו .. כופר נפשו\") איז געווען איינע פון די דריי זאכן ש„שמע משה מפי הגבורה ונבהל ונרתע לאחוריו\" — „בשעה71 שאמר לו הקב\"ה צו את בנ\"י את קרבני לחמי לאשי אמר משה מי יוכל להספיק לו קרבנות אם אנו מקריבין לפניו כל חיתו שדי כו' אינו מספיק לו כו', א\"ל הקב\"ה איני מבקש לפי כחי אלא לפי כוחן כו'. בשעה שאמר לו הקב\"ה ועשו לי מקדש ושכנתי בתוכם אמר משה מי יוכל לעשות לו מקדש שישרה בתוכו הנה השמים ושמי השמים לא יכלכלוך כו', אמר הקב\"ה איני מבקש לפי כחי אלא לפי כחן כו'\".\nאיז ניט מובן: וויבאלד משה האט שוין געהערט פריער*71, בנוגע צום משכן, אז „איני מבקש לפי כחי אלא לפי כחן\", פארוואס איז ער „נבהל\" און ס'איז ביי אים געווען א תמי' הערנדיק די ווערטער „ונתנו איש כופר נפשו\"?\nלכאורה קען מען ניט זאגן אז דער חידוש ותמי' פון משה'ן איז געווען דערפאר ווייל דאס איז כופר נפשו אויפן חטא העגל, וואס רירט אן דעם עצם מציאות כנ\"ל72 — וואָרום אויך דאס געפינט מען, דער אויבערשטער האט געהייסן נעמען א פר בימי המילואים „לכפר73 על מעשה העגל שהוא פר\"*73.\nאיז דער ביאור אין דעם:\nבאַ דעם משכן איז פארשטאנדיק אז דאס וואס אידן האבן געטאן איז געווען „לפי כחן\", ווייל זייער השתתפות אין דעם איז געווען מיט נדיבות לבם — „כל איש אשר ידבנו לבו\"74, „כל נדיב לבו יביאה\"75; עד\"ז ביי הקרבת הפר — ווייל ביי קרבן איז דער דין, אז „יקריב אותו לרצונו\"76, און דאס אז עס דארף",[["70","70","שם הערה 2."],["71","71","לשון במדב\"ר שם. ועד\"ז (בשינויים קלים) בשאר מקומות הנ\"ל. *71) שהרי הפרשה דמחה\"ש דפ' כי תשא „ונתנו איש כופר נפשו\" נאמרה לאחרי שנצטוו (בפ' תרומה) „ועשו לי מקדש גו'\", וכדמוכח ממש\"נ (פרשתנו ל, טז) „ולקחת את כסף הכפורים גו' ונתת אותו על עבודת אהל מועד גו'\"."],["72","72","ראה לקו\"ש ח\"ג ע' 923 ואילך. וש\"נ."],["73","73","פרש\"י תצוה כט, א. *73) להעיר מפרש\"י חוקת יט, כב ד\"ה פרה."],["74","74","תרומה כה, ב."],["75","75","ויקהל לה, ה. וכן הי' בפועל „כל נדיב לב הביאו גו'\" (שם, כב), ועד — שהמלאכה היתה דים גו' והותר (שם לו, ז)."],["76","76","ויקרא א, ג. פרש\"י שם מתו\"כ. ר\"ה ו, א. וש\"נ."]]],[1300161403,"זיין דער רצון המנדב ושל בעל הקרבן, איז דאס מדגיש אז עס איז „לפי כחן\" — אין דעם איז דא „כחן של ישראל\";\nאבער די מצוה פון מחצית השקל איז אין אן אופן אז יעדער האט געמוזט געבן, צי ער וויל יע אדער ניט, נאכ־מער דער דין איז אז „כופין את מי שלא נתן עד שיתן וכל מי שלא יתן ממשכנין אותו ולוקחין עבוטו בעל כרחו ואפילו כסותו\"77 —\n[און אע\"פ אז אויך בא קרבנות איז דא דער דין פון „כופין אותו\" — איז עס אבער אין אן אופן פון „כופין אותו עד שיאמר רוצה אני\"78, ד.ה. אז ביי דער הקרבת קרבן מוז דער מענטש זאגן בדיבור שלו אז „רוצה אני\"; וואס הגם אז בחיצוניות איז עס א געצוואונגענע אמירה, איז אבער די אמירה מתאים מיט'ן אמת, וויבאלד אז בפנימיות נפשו וויל יעדער איד מקיים זיין דעם רצון השם (כמבואר ברמב\"ם<sup data-n=\"79\">79</sup>; משא\"כ ביי מחצית השקל געפינט מען ניט אז דער איד דארף זאגן „רוצה אני\", ד.ה. אין זיין נתינה מוז ניט זיין רצונו. און ווי־באלד אז די נתינה אליין איז נאר א חיצוניות'דיקע פעולת היד און דער נפש פון אידן איז ניט קענטיק אין דער עשי', איז]\n— ווי קען אזא נתינה זיין „כופר נפשו\"80, אין דעם איז דאך ניטא „כחן\", „כחן של ישראל\"!\nאויף דעם האט דער אויבערשטער באוויזן משה'ן „מטבע של אש ומשקלה מחצית השקל\", וואס ער האט גענומען (ווי עס שטייט אין מדרש) „מתחת כסא כבודו\", כדלקמן.\nיו\"ד. דער טעם (פנימי) אויף דעם, וואס ביי מחצית השקל איז ניטא דער דין פון „כופין אותו עד שיאמר רוצה אני\" (ובפרט קשה לפי הנ\"ל, סעיף ג', אז דאס האט א דין קרבן), י\"ל אז דאס איז, ווייל מחצית השקל איז געקומען אלס כפרה אויפן חטא העגל, וואס האט אנגערירט כנ\"ל, דעם עיקר מציאות פון אידן, זיי אפגעריסן אויך מצד נפשם ופנימיותם ר\"ל, ובמילא קען דא ניט העלפן „כופין אותו עד שיאמר רוצה אני\" (אז דער רצון ופנימיות הנשמה זאל ארויסקומען בגלוי).\nאון דערפאר „הראה לו מטבע של אש\", וואס „הוציא הקב\"ה מתחת כסא כבודו\": מצד פנימיות הנשמה ווי זי איז שייך צום גוף האט די נתינה ניט געקענט זיין מצד כחן של ישראל, כנ\"ל. דאס קען אבער יע זיין מצד עצם הנשמה (וואס איז העכער לגמרי פון גילויים, ווייל עצמיות הנשמה איז דער עצם פון אלע כחות81, אויך פון זיין עשי' חיצונית).\nאון דאס מיינט „הראה לו (הקב\"ה)\" — דער אויבערשטער האט מגלה געווען, בדרך מלמעלה למטה אויך ווי די „מטבע של אש\" נעמט זיך „מתחת כסא כבודו\" — די בחי' אש שבנשמה, עצם הנשמה, ווי זי איז מושרש למעלה „תחת כסא כבודו\" ווי די חז\"ל82 זאגן „הנשמות גזורות מתחת כסא הכבוד\"83;",[["77","77","רמב\"ם הלכות שקלים שם ה\"ט. וש\"נ."],["78","78","נסמן לעיל הערה 76."],["79","79","ספ\"ב דהלכות גירושין."],["80","80","וידוע השקו\"ט במש\"כ בתוספתא שקלים שם דממשכנין כיון דהוי כפרה, והרי חייבי חטאות ואשמות אין ממשכנין אותם. וראה בארוכה צפע\"נ לרמב\"ם שקלים שם ה\"ט, וש\"נ."],["81","81","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081142\" data-slug=\"likkutei-sichot\" data-id=\"1300081142\">לקו\"ש ח\"ח ע' 131</a>, וש\"נ."],["82","82","רע\"מ צו כט, רע\"ב. נשא קכג, ב. ועוד."],["83","83","ראה אלשיך עה\"פ. ועוד."]]],[1300161404,"און דאס האט ער מגלה וממשיך גע־ווען אין „משקלה\" — אז דער עצם הנשמה נעמט דורך די נשמה מיט אירע אלע כחות דא למטה ביז אין משקל וכו'; ד.ה. אז די „מטבע של אש\" — עצם הנשמה — איז ניט א באזונדער זאך פון די כחות וואס זיינען דא אין דער נתינה גשמיות, נאר די מטבע של אש גופא איז „משקלה מחצית השקל\" (וכנ\"ל, אז דער עצם הנשמה איז דער עצם פון אלע כחות).\nאון דערפאר, אפילו ווען די נתינה פון א אידן איז אן דער אמירה פון רוצה אני, ס'איז אין אופן פון „משקל\" — א נתינה גשמית וחומרית, אן רצון וחיות, ס'איז „משקל\": עס וועגט און שלעפט למטה און מ'דארף האבן טרחא און אפילו כפי' — איז אבער דער אמת לאמיתו (און דאס איז דער אויפטו פון מחצית השקל), אז ביי אידן איז אויך די נתינה געבונדן מיט'ן „אש שבנשמה\", אז די אמיתיות ופנימיות פון זיין כח העשי' והנתינה איז די התגלות פון „תחת כסא כבודו\" וואס איז „מטבע של אש\", עצם נשמתו.\nיא. ע\"פ כהנ\"ל איז פארשטאנדיק די שייכות צווישן די צוויי ענינים הנ\"ל אין מחצית השקל — דער דין „ונתנו איש כופר נפשו\" (דער דין אין נתינה, אז דאס איז „כופר נפשו\", א קרבן) און „זה יתנו\" (דער דין אין חפצא, אז דאס איז ניט א גדר שוויות וערך, נאר א מציאות פון א מטבע מחצית השקל כסף) — וואָרום ביידע דריקן אויס די זעלבע נקודה, אז די נתינה פון מחצית השקל איז פון „אש\" (מתחת כסא כבודו) ועצם הנשמה:\nוויבאלד עצם הנשמה איז העכער פון התפשטות גילויים והתחלקות, איז מובן אז אויך די נתינה שמצד עצם הנשמה איז בדוגמא לזה: בבת אחת — אן התחלקות, און דער שיעור פון דער מטבע איז ניט א כמות'דיקער (וואס מעסט זיך מיט שוויות און משקל), נאר אן איכות'דיקע עצם־נקודה;\nאון מהאי טעמא איז די כפרה פון מחצית השקל אין אן אופן פון „אש\" (העכער פון דער כפרה פון קרבנות, כנ\"ל סעיף ז), וואס מאכט איבער דעם מענטשן אין א מציאות חדשה, ווייל מצד התגלות פון עצם הנשמה ווערן נשתנה אלע זיינע כחות84 ביז ער ווערט א מציאות חדשה.\nיב. אט דער ענין וואס „מטבע של אש הוציא הקב\"ה .. והראהו למשה\", איז אבער געקומען ערשט נאכדעם85 ווי משה „נבהל ונרתע לאחוריו\"; דוקא ווען בחי' משה — חכמה86 דקדושה — ווערט נבהל כו', ניט קענענדיק באַ־נעמען ווי אזוי אן עשי' ופעולה חיצונית קען זיין א כפרה, איז דאס85 מעורר אז דער אויבערשטער זאל באווייזן, מגלה וממשיך זיין מלמעלה למטה, די דרגא פון „אש\" שבנשמה ביז אין בחי' „משקל\", ד.ה. ווי עצם הנשמה זאגט זיך ארויס בגלוי אין די כחות הנשמה ביז אין מעשה המצות פון א אידן.\nאון דאס איז אויך א הוראה אין עבודת כאו\"א: עס טרעפט אמאל אז א איד פילט ניט קיין געשמאק און חיות אין לימוד התורה וקיום המצות, עס איז א מצות אנשים מלומדה, כגוף בלי נשמה87; ביז נאכמער, אז דאס איז ביי אים גאר א טירחא ועול, ער דארף זיך",[["84","84","ראה קונטרס העבודה פ\"ה (ע' 32 ואילך)."],["85","85","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061038\" data-slug=\"likkutei-sichot\" data-id=\"1300061038\">לקו\"ש ח\"ו ע' 38</a> ואילך."],["86","86","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380683\" data-slug=\"likkutei-torah\" data-id=\"4001380683\">לקו\"ת מסעי פט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380692\" data-slug=\"likkutei-torah\" data-id=\"4001380692\">צב, רע\"א</a>. ועוד."],["87","87","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח</a>."]]],[1300161405,"כופה זיין צו מקיים זיין דעם אויבערשטנ'ס רצון, און אויך דער נויטן זיך איז ביי אים ניט בדרך עבודת עבד, נאר ווייל ער האט ניט קיין ברירה —\nדארף ער וויסן, אז דאס וואס ער וועט זיך ארייין טראכטן אין דעם, מיט א התבוננות אליבא דנפשי', און בחי' משה שבו — חכמה שבנפש88 — „גיט זיך א טרייסל\" דערפון וואס ער האט ניט קיין חיות און הרגש אין עבודת השם, און אין מקיים זיין דעם אויבערשטנ'ס רצון — דאס89 גופא איז מעורר דעם ענין פון „הראהו מטבע של אש כו'\", אז הקב\"ה עוזרו, דער אויבערשטער איז ממשיך און באווייזט בחי' „משה\" שבנפשו דעם אש שבנפשו, עצם הנשמה, און דאס ווערט נמשך אין „משקלה\", אין אלע כחות הנפש ביז אין מעשה בפועל, און אין אן אופן גלוי.\nיג. לאידך האט מען פון דעם די הוראה: בשעת ס'איז דא א איד, וואס לעתה פירט ער זיך ניט אזוי ווי עס דארף זיך פירן א בן אברהם יצחק ויעקב און עס ליגט א חיוב אויף יעדן אידן צו מקרב זיין אים צו תומ\"צ — זיינען אבער דא אזעלכע וואס טענה'ן: וואס פאר אן ארט האט צו זאגן דעם אידן אז איצט דארף ער לייגן תפילין, אדער\nלייענען ק\"ש וכיו\"ב, בעת ער האלט נאך ניט דערביי, ער פארשטייט ניט וואס דאס מיינט און ער האט קיין שום רצון ניט דאס צו טאן. און וואס פאר א תועלת איז צו מכריח זיין אים אנטאן תפילין, בשעת ער וועט עס טאן נאר דערפאר וואס ער איז אן איידעלער מענטש און קען ניט אפזאגן — אבער די מעשה המצוה גופא מיינט ביי אים גאר־ניט?\nדער סדר דארף זיין — טענה'ן זיי — אז די ערשטע זאך דארף מען אים אויפ־קלערן שריט נאך שריט, א טאג נאך א טאג און געבן צו פארשטיין ביז ביי אים זאל זיך אפלייגן אין זיין שכל אז ער דארף מקיים זיין מצוות, און דעמאלט וועט ער שוין אליין אנהייבן מקיים זיין מצוות, וואָרום ער וועט האבן אין דעם א רצון און געשמאק.\nאויף דעם איז דא די הוראה פון מחצית השקל: בשעת א איד איז מקיים א מצוה אפילו נאר אין אן אופן פון „משקלה\", אן קיין שום תענוג און אן א רצון, און אפילו בדרך כפי', באוויזט דער אויבערשטער אז באמת'ן איז דאס „מטבע של אש\", דאס איז מצד דעם „אש\" פון עצם הנשמה, ובמילא איז דאס זיין אמת'ער רצון ותענוג.\nואדרבה — דורך דעם וואס ער וועט פועלן אויפן צווייטן מקיים זיין די מצוה אפילו נאר בדרך כפי', וויבאלד באמיתית איז דאס פארבונדן מיט'ן „אש\" שבנשמה, וועט דאס פועלן אז סו\"ס וועט די מטבע של אש אראפקומען בגלוי ביז אין „משקלה\", אין זיין מעשה בפועל, ביז אז דאס וועט ווערן זיין רצון ותענוג בגלוי, סוף־סוף וועט ער מקיים זיין די מצוה מיט'ן גאנצן ברען און פייער פון דער נשמה.\nאון וועט אויך צואיילן די הקרבת",[["88","88","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב</a>."],["89","89","ויתירה מזו י\"ל: זה שהאדם הוא במדרי' נמוכה כזו שאינו מרגיש כו' ואינו רוצה לקיים רצון העליון, זה גופא בא מלמעלה בכדי לעורר בחי' משה שבו, ועי\"ז לבוא ל„הראה .. מטבע של אש\" — גילוי עצם הנשמה, במשקלה — במחדרי\"מ שלו. *) ובמכש\"כ מענין החטאים כו', כידוע בענין נורא עלילה על בנ\"א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051078\" data-slug=\"likkutei-sichot\" data-id=\"1300051078\">לקו\"ש ח\"ה ע' 66</a> ואילך <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181404\" data-slug=\"likkutei-sichot\" data-id=\"1300181404\">לקו\"ש חי\"ח ע' 395־6</a>. וש\"נ."]]],[1300161406,"הקרבנות (וואס מ'האט געבראכט90 פון מחצית השקל) אין דעם ביהמ\"ק השלישי אין ירושלים עיר הקודש, וואס „באש אתה עתיד לבנותה\"91 „ואני אהי' לה נאם ה' חומת אש סביב\"92, במהרה בימינו ממש.\n(משיחות פ' שקלים, פ' זכור, פ' פרה תשל\"ג)",[["90","90","דלכאורה קרבנות ציבור הראשונים דלעת\"ל יהיו ע\"י שיחידים ימסרום לציבור יפה יפה (ר\"ה ז, סע\"א ואילך. רמב\"ם הל' כלי המקדש פ\"ח ה\"ז) עד שיגבו מחה\"ש."],["91","91","נוסח נחם — ירושלמי ברכות פ\"ד ה\"ג."],["92","92","זכרי' ב, ט."]]],[1300161407,"<h3>תשא ב</h3>\nאַ. ביים ציווי אין אונזער פרשה<sup data-n=\"1\">1</sup> איף דער עשיית שמן המשחה שטייט אין פסוק<sup data-n=\"2\">2</sup> — נאַכן אויסרעכענען די אלע מיני בשמים וואָס מען האָט געדארפט האבן פארן שמן המשחה צוליב זייער „ריח טוב וטעם\"<sup data-n=\"3\">3</sup> — „ושמן זית הין\", איז רש\"י מעתיק הין — און איז מפרש: „י\"ב לוגין ונחלקו בו חכמי ישראל ר' מאיר אומר בו שלקו את העקרין אמר לו ר' יהודה והלא לסוך את העקרין אינו סיפק אלא שראום במים שלא יבלעו את השמן ואח\"כ הציף עליהם השמן עד שקלט הריח וקפחו לשמן מעל העקרין\".\nדארף מען פארשטיין: דרכו של רש\"י איז, אַז צווי באזונדערע ענינים וואָס ער איז מפרש אויפן זעלבן וואָרט — צו פאנאנדערטיילן זיי יעדערן אין אַ באזונדער דיבור המתחיל<sup data-n=\"4\">4</sup>: היינט פארוואָס דאָ איז רש\"י מצרף די צווי פארשידענע ענינים — (א) די מאָס פונעם שמן „י\"ב לוגין\", (ב) דער אופן ווי מ'האָט געמאכט דעם שמן המשחה (אַז „בו שלקו כו'\" אדער „הציף עליהם השמן כו'\") — אין דעם זעלבן דיבור? ובפרט אַז רש\"י<sup data-n=\"1\">1</sup> שרייבט „ונחלקו בו כו'\" מיט אַ ו\"אי המוסיף,<sup data-n=\"2\">2</sup> איז מדגיש „בו\" — אין דעם הין שמן, ניט „בו שלקו\" אלס פירוש פון „ועשית\" וואָס שטייט אין פסוק שלאחריו.\nב. אויך זיינען דאָ כמה דיוקים אין לשון רש\"י:\nא) איידער רש\"י בריינגט די צווי דיעות פון ר\"מ און ר\"י איז ער מקדים: „ונחלקו בו חכמי ישראל\" — איז בשלמא דאָס וואָס ער איז בכלל מקדים אַז אין דעם ענין איז דאָ אַ פלוגתא, איז עס (ווי גערעדט שוין כמה פעמים) מיט דער כוונה צו באווארענען אַז די געבראכטע צווי פירושים זיינען שקולים אין דרך הפשט [אָן דער הקדמה וואלט געווען משמע אַז דער ערשטער פירוש וואָס רש\"י בריינגט איז דער „ערשטער\" אויך במעלה — נעענטער צום דרך פרש\"י, דרך הפשט]:\nס'איז אבער ניט מובן, וואָס רש\"י איז דאָ מדגיש „(ונחלקו בו) חכמי ישראל\" (צי דען איז דאָ נויטיק צו שולל זיין די חכמי האומות?) און זאגט ניט „(ונחלקו בו) רבותינו\" וכיו\"ב (וכדרכו בכ\"מ)?\nב) צוליב וואָס איז רש\"י מעתיק אויך די נעמען פון ר' מאיר און ר' יהודה, (וואָרום, ווי גערעדט פיל מאל, בריינגט רש\"י דעם נאמען פון דעם „מאן דאמר\" נאר דאן ווען דורך דעם קומט צו ביאור אין זיין פירוש)?\nג) נאָך שטארקער איז דער דיוק אין דעם: אין בבלי<sup data-n=\"5\">5</sup> איז די גירסא אַז ר' יהודה זאגט „שולקים בו את העקרים\", און ר' יוסי זאגט „שורין<sup data-n=\"6\">6</sup> את העקרים במים ומציף עליו שמן וקולט את הריח וקפחו\" — און רש\"י קלייבט אויס די",[["1","1","ל, כב ואילך."],["2","2","שם, כד."],["3","3","ל' רש\"י (שם, כג) — לענין „וקנמן בשם\". ולהעיר שרש\"י כותב גם „טעם\" וכן לקמן בפירוש „מרקחת\" — ועיין לקו\"ת ס\"פ נשא. ואכ\"מ."],["4","4","ראה לדוגמא פרשתנו ל, יג."],["5","5","הוריות יא, ב. כריתות ה, סע\"א."],["6","6","בכריתות שם: ושלקום. אבל ברש\"י (וכן בשטמ\"ק) שם גריס „ושראן\"."]]],[1300161408,"גירסא פון ירושלמי<sup data-n=\"7\">7</sup> אַז ר' מאיר זאגט „בו שלקו את העקרין\" און ר' יהודה זאגט „שראום<sup data-n=\"8\">8</sup> במים כו'\"<sup data-n=\"9\">9</sup> ?\nג. אויף דער אויבענדערמאנטער ערשטער שאלה (ס\"א) וואלט מען לכאורה געקענט ענטפערן אין פשטות: נאכדעם ווי רש\"י זאגט אַז ס'זיינען געווען בלויז י\"ב לוגין פון שמן, װערט דאך שווער: אזאַ מאָס שמן איז דאך\nזייער קליין אין פארגלייך צום ריבוי גדול פון די בשמים וואָס זיינען געניצט געווארן מיט'ן שמן — היינט ווי איז שייך אַז נאכדעם זאל בלייבן שמן פאר „משחת קודש\" און נאך אזוי פיל אַז „ומשחת בו את אהל מועד גו'\"? דערפאר מוז רש\"י גלייך ממשיך זיין און בריינגען די דיעות וואָס ערקלערן ווי אזוי ס'איז געווען די עשיית שמן המשחה.\nס'איז אבער ניט מובן: אט די קשיא ווערט, לכאורה, פארענטפערט נאר לויט דעת ר' יהודה אַז „שראום במים שלא יבלעו את השמן\", אבער לויט ר' מאיר בלייבט די קשיא — און ווי רש\"י בריינגט גלייך דעם אפפרעג פון ר' יהודה: „והלא לסוך את העקרין אינו סיפק\"?\nאון דערפון, צו דער תמי' גדולה אין פרש\"י: רש\"י ברענגט די שיטה פון ר\"מ אַז „בו שלקו את העקרין\" און תיכף די קושיא פון ר\"י אויף אים — „והלא לסוך את העקרין אינו סיפק\" — ניט צוגעבנדיק קיין תירוץ אויף ר\"י'ס קשיא? [וואָרום, ס'איז דאך פשוט אַז רש\"י מיינט ניט צו זאגן אַז שיטת ר\"מ איז אפגעפרעגט, ווייל דעמאלט וואלט ער די שיטה פון ר\"מ איבערהויפט ניט געבראכט].\nנאכמער איז תמוה, וויבאלד אַז רש\"י איז מקדים „ונחלקו בו חכמי ישראל\", איז רש\"י דערמיט מדגיש, כנ\"ל, אַז (ניט נאר ווערט ר' מאיר'ס דיעה ניט אפגע-פרעגט דורך ר\"י'ס קשיא — נאר) ביידע דיעות זיינען שקולים אין פשוטו של מקרא!\nד. אין בבלי<sup data-n=\"10\">10</sup> ווערט טאקע גע-בראכט, אַז ר\"י האָט אויף דער קשיא",[["7","7","שקלים פ\"ו ה\"א. סוטה פ\"ח ה\"ג. ולכאורה משמע דמצא רש\"י גירסא כזו בבבלי * (וראה רמב\"ן כאן), שהרי: א) בירושלמי אין התיבות „אי\"ל והלא לסוך את העקרין אינו סיפק\" בדברי ר\"י (כ\"א בתני ר\"י בי רבי אילעי שלאח\"ז). ב) בירושלמי הגירסא: „שולקן ** הי' במים\". ג) ל' רש\"י „הציף עליהם השמן עד שקלט הריח וקפחו כו'\" הוא ע\"ד הלשון שבבבלי. אבל גם עפ\"ז צריך ביאור למה נקט רש\"י הגירסא דאינה הנפוצה בהש\"ס שלפנינו ובשני מקומות."],["8","8","אלא שבירושלמי איתא „שולקן הי' במים\", כנ\"ל בהערה הקודמת."],["9","9","במלבי\"ם כאן כ' (דהרמב\"ם ס\"ל) דר' יהודה שבירושלמי ור' יוסי הם ב' דיעות — לר' יהודה שלקו העקרים במים והשמן למעלה [וגם בבבלי — כוונתו ששלקן במים ושמן ע\"ג] ור' יוסי ס\"ל דלאחר שקלטו המים את הריח העביר את העקרין ונתן השמן על המים לחוד — אבל בפרש\"י בש\"ס (כריתות שם, סע\"א. וכ\"מ מפירש\"י הוריות שם ד\"ה ומציף) מפורש דגם לדעת ר' יוסי „קנחו משה לשמן מעל העקרין\". *) ועפ\"ז צ\"ל שגם אח\"כ גרים „א\"ל ר\"מ וכי נס אחד נעשה כו'\". וכן בברייתא שהובאה תיכף לאח\"ז („שמן המשחה כו' הרבה נסים נעשה בו כו' כמה יורה בולעת כמה עקרין בולעין כמה האור שורף כו'\") גרים ר\"מ — ובפרט את\"ל דרש\"י ס\"ל, דלשיטת ר\"י היתה רק שריי' במים, ולא שלוק ע\"ג אש (כבשוה\"ג הבא). וראה לקמן הערה 10. **) ברמב\"ן כאן, שגם לדעת ר\"י „אין השרייי' שיהיו במים לבדן אבל נתנו כו' ונתנו על אש כו'\", ומביא ראי' מדברי ר\"י שבירושלמי. עיי\"ש (וראה רמב\"ם הל' כלי המקדש פ\"א ה\"ב) — אבל בפרש\"י כאן לא נזכר כלל שגם לדעת ר\"י שלקו כו'."],["10","10","שם. ואף שבירושלמי לא הובא בפירוש"]]],[1300161409,"געענטפערט ר' יוסי'ן: „וכי נס אחד נעשה בשמן המשחה והלא תחלתו י\"ב לוגין וממנו הי' נמשח משכן וכליו אהרן ובניו . . וכולו קיים לעתיד לבוא וכו'\", ד. ה. אַז ביי דער עשיית השמן איז טאקע געשען אַ נס און דער שמן איז ניט איינגעזאפט געווארן אין די עקרין.\nאין פרש\"י אבער קען מען אזוי ניט איינלערנען, ווייל אין רש\"י דאָ ווערט בכלל ניט דערמאנט (אפי' ניט ברמז) אַז לשיטת ר\"מ איז פארגעקומען אַ נס:\nנאכמער: פון דעם וואָס רש\"י זאגט שפעטער (אויפן פסוק 11 „שמן גו' לדו-רותיכם\") „מכאן למדו רבותינו שכולו קיים לעתיד לבוא\", איז משמע, אַז אינעם תוכן הכתובים ביזן פסוק „לדורותיכם\" דארף מען ניט אנקומען צו אט דעם חידוש אַז ביים שמן המשחה איז געווען אַ נס.\nמוז מען זאגן, אַז רש\"י נעמט אן אַז לשיטת ר\"מ איז לכתחילה ניט שווער די\nשאלה פון ר\"י „והלא לסוך כו'\" — איז ניט מובן: א) לכאורה איז דאָס אַ שטארקע קושיא אין פשטות הדברים? ואדרבא — ע\"ד לימוד הש\"ס קען מען ענטפערן, כנ\"ל, „וכי נס אחד נעשה כו'\", אבער ע\"ד הפשט איז דאך ניטא קיין רמז אפילו אויף דעם. ב) און לאידך: אויב רש\"י האלט אַז דער תירוץ אויף דעם איז אזוי פשוט אַז ער דארף עס גארניט באווארענען — היינט ווי איז ער מעתיק די קשיא בפירושו?\nה. דער ביאור אין דעם:\nלשיטת ר\"מ, אַז מ'האט די עקרין שולק געווען אינעם שמן, איז (לשיטת רש\"י — ע\"ד הפשט) מלכתחילה ניטא קיין ארט אויף דער שאלה „והלא לסוך את העקרין אינו סיפק\" — ס'מאכט ניט אויס וואָס דורך דער שליקת העקרין איז דער שמן נבלע געווארן אין זיי — ווייל ער האלט אַז דער שמן המשחה האט ניט געמוזט זיין שמן פאר זיך נאר צוזאמען מיט די עקרין (וואָס זיינען געווארן פעט און געגאסן זיך ווי אַ משקה — דורך דעם שולקן בשמן): און כאטש עס ווערט אנגערופן שמן המשחה, און עס שטייט אויף דער לשון „ויצקת\" „והזית\"<sup data-n=\"12\">12</sup> — וויבאלד אַז די עקרין האט מען געקאכט אין אן אופן פון „שולקן\" וואָס איז מער ווי בישול — פאנאנדער-געקאכט — איז פארשטאנדיק אַז ס'האט ניט געהאט קיין אויסזען פון עקרין, נאר, בלשון רש\"י<sup data-n=\"13\">13</sup> „נימוחין\", ווי אַ משקה.",[["","","שר\"מ ס\"ל דמעשה נסים הי' בו — הרי מביא שם * בהמשך לפלוגתת ר\"מ ור\"י: „תני ר\"י בי רבי אילעי אומר שמן המשחה שעשה משה במדבר מעשה נסים נעשה בו מתחלה . . י\"ב לוגין כו' אם לסוך בו את העצים לא הי' מספיק עאכו\"כ שהאור בולע והעצים בולעין והיורה בולעת וממנו נמשחו וכו'\" — דמפשטות לשונו („שהאור בולע והעצים בולעין והיורה בולעת\") משמע דבא לתרץ השיטה (כדעת ר\"מ) ** דבו שלקו את העקרין (וכמ\"ש בפני משה לירושלמי הוריות פ\"ג ה\"ב. וראה מראה הפנים לירושלמי סוטה שם. ובפ\"מ שם ד\"ה חדא. אבל ראה שירי קרבן שם. פ\"מ שם ד\"ה שולקן). ואכ\"מ."],["11","11","שם, לא. *) הובא גם בתו\"כ צו ח, י. ירושלמי הוריות פ\"ג ה\"ב. ויקר' פ\"י, ח. בהוריות וכריתות שם בשינוי לשון. **) אבל לפי גירסת הירושלמי „שולקן הי' במים\" — י\"ל דאתי כר\"י, כי גם לאחרי שילוק במים בולע שמן (וראה מלבי\"ם הנ\"ל), והוי נס דכולו קיים."],["12","12","תצוה כט, ז. שם כט, כא."],["13","13","פסחים (לט, א) ד\"ה שלוקין. וראה בכורות מה, א: ששלקו כר' — ומדלא פרש\"י מאומה מוכח דס\"ל שפי' כבכ\"מ בש\"ס ולא כבמשנה שבסדר זרעים (מעשרות פ\"א מ\"ה — לדעת מוסף הערוך). ולהעיר מברה\"נ (שבסידור) ספ\"ז (ובמ\"מ שם)."]]],[1300161410,"אבער ר\"י וויל אזוי ניט לערנען, ווייל ער האלט אַז דער שמן המשחה האָט געמוזט זיין כשמו — שמן, און ניט (רובו) עקרין שנימוחו — וואָס זיינען געווארן אַ פעטע משקה ווייל מ'האט זיי שולק געווען אין שמן. און דערפאר לערנט ער אַז „שראום במים כו' וקפחו לשמן מעל העקרין\".\nאון דאָס איז אויך דער טעם פארוואָס רש\"י איז מעתיק אויך ר' יהודה'ס קשיא אויף שיטת ר\"מ און איז דערביי מדייק צו זאגן „והלא לסוך את העקרין אינו סיפק\" (הגם לויט שיטת ר\"מ ווערט דער שמן נבלע אין עקרין און איז ניט „לסוך\" את העקרין: במילא זעט ער זיך ניט אן (בפ\"ע) כלל — האט דאך געדארפט זיין קושיית ר\"י'ס עיקר: ווי אזוי רופט מען עס „שמן\", כנ\"ל), ווייל „לסוך\" איז מדגיש אַז די זאך מיט וועלכע מ'איז סך איז טפל ובטל לגמרי צו דער זאך וואָס מ'איז סך (עקרין) — ופשיטא אַז ס'קען ניט אנגערופן ווערן ע\"ש דבר הבטל (דער שמן).\nו. דער טעם הפלוגתא צווישן ר\"מ און ר\"י:\nאין פסוק 14 שטייט „ועשית אותו שמן משחת קודש רקח מרקחת מעשה רוקח שמן משחת קודש יהי'\" — ד. ה. אַז עס זיינען דאָ אין דעם צווי חלקים, זמנים: א) בשעת מעשה — „ועשית אותו (דעם שמן זית) . . רקח מרקחת מעשה רוקח\", אַן עשי' איז דעם שמן און אין אַן אופן פון מרקחת גו' — ווי רש\"י טייטשט עס אפ: „וכל דבר המעורב בחבירו עד שזה קופח מזה או ריח או טעם קרוי מרקחת\". ב) נאָך דער עשי' — עס דארף ווערן „שמן משחת קודש יהי'\" (אלעמאל).\nאון אין דעם באשטייט דער חילוק צווישן ר\"מ און ר\"י — אין וועלכן פרט פון די צווי איז דער עיקר הדגשה:\nלויט שיטת ר\"מ („בו שלקו\") איז דער ענין פון עשי' בשמן און פון „מרקחת\" געווען בתכלית השלימות: דער פולסטער אופן צונויפצומישן צווי זאכן („דבר המעורב בחבירו\"), איז ווען זיי ווערן געקאכט צוזאמען<sup data-n=\"15\">15</sup> — האלט ר\"מ אַז כדי מקיים זיין דעם ציווי „ועשית אותו גו' מרקחת גו'\" בתכלית השלימות, האט עס געמוזט זיין אויף דעם אופן פון „בו שלקו את העקרין\":\nכאטש אלס תוצאה דערפון לאחר זה, איז דער פרט פון „שמן משחת קודש יהי'\" האט ניט די שלימות פון שמן (בפ\"ע) נאר ווי ער איז צוזאמען מיט די עקרין.\nדאקעגן לשיטת ר' יהודה, הגם אַז דורך „שראום במים כו' ואח\"כ הציף עליהם השמן עד כו' וקפחו כו'\", איז די עשי' בשמן מער ניט ווי „הציף וקפחו\" און „מרקחת\" („דבר המעורב בחבירו\") איז ניט בשלימות — וואָרום די קליטת הריח אינעם שמן איז ניט געקומען דורך קאכן דעם שמן צוזאמען מיט די עקרין — איז אבער די תוצאה דערפון בשלימות: דער „שמן משחת קודש יהי'\" קומט בתכלית — ס'איז ריכטיגער שמן (און לגמרי בפ\"ע).\nאון וויבאלד אַז פון פשטות הכתובים, איז ניטא קיין הוכחה וועלכער פון די צווי איז דאָ מכריע — דער ענין פון „ועשית גו' מרקחת גו'\" אדער דער ענין פון „שמן משחת קודש יהי'\" — דערפאר איז רש\"י מקדים (פארן אראפבריינגען דעם גוף הפלוגתא): „ונחלקו בו כו'\",",[["14","14","פסוק כה."],["15","15","להעיר ממש\"נ בקטורת (פרשתנו ל, לה) „רקח מעשה רקח ממלח גו'\" ופרש\"י שם."]]],[1300161411,"בכדי דערמיט צו באווארענען אַז ביידע דיעות זיינען שקולים בפשוטו של מקרא.\nז. דערמיט קען מען אויך מסביר זיין דעם דיוק הלשון אין פרש\"י: „ונחלקו בו חכמי ישראל\", ווייל די צווי דיעות פון ר\"מ און ר\"י אינעם אופן עשיית שמן המשחה, שפיגלען אפ צווי פארשידענע אופנים ווי עס קאן זיין דער צוגאנג פון אַ אידן צו קיום המצות — ווי דאָ באם קיום הציווי ועשית שמן גו'; און דערפאר איז עס אַ פלוגתא פון „חכמי ישראל\":\nתכלית השלימות בהווה, הגם אַז דורך דעם וועט פעלן אין דער שלימות פון לאחר זמן; אדער אַז בעיקר איז נוגע די שלימות בגמר הענין לאחר זה (ולתמיד), אפילו ווען דאָס קען ווערן דערגרייכט נאר דאן ווען די עשי' בהווה איז ניט בשלימות<sup data-n=\"16\">16</sup>.\nאזוי ווי אויך בנדו\"ד: אין דעם ציווי פון דעם אויבערשטן איז „לא פירש מה דינו\" פון די פרטי אופני עשיית השמן<sup data-n=\"17\">17</sup>, נאר בכללות „ועשית גו' מרקחת גו' (און דורכדעם זאל) שמן משחת קודש יהי'\" — און במילא איז עס אפהענגיק אין דער דעה פון חכמי ישראל באופן קיום המצות:\nר\"מ זאגט, אַז ווען אידן האבן\nגעדארפט מאכן דעם שמן, האבן זיי זיך גערעכנט בעיקר מיט'ן שלימות ווי דאָס איז בהווה ביים עשיית השמן — אַז עס דארף זיין „ועשית אותו\" און „מרקחת גו'\", און דערפאר איז „בו שלקו את העקרין כו'\": כאטש ס'וועט דורך דעם פעלן אין דער שפעטערדיקער תוצאה פון „שמן משחת קודש יהי'\", ווייל עס וועט זיך ניט אנזען קיין שמן באזונדער.\nדאקעגן ר\"י נעמט אן אַז עס דארף זיין בהווה די הכנה צום שלימות בעתיד — און דערפאר קען מען ניט זאגן אַז „בו שלקו את העקרין\", ווייל דעמאלט וועט דאך שפעטער פעלן אין דער שלימות פון „שמן משחת קודש יהי'\":\nדערפאר זאגט ר\"י אַז „שראום במים כו'\", וואָס הגם אַז דער „ועשית אותו\" און די „מרקחת\" (דער הווה) איז דאן ניט בשלימות, דערפאר איז אבער נאכדעם דער שמן (בעתיד) בשלימות<sup data-n=\"18\">18</sup>.\nח. עפ\"ז איז אויך פארשטאנדיק וואָס רש\"י בריינגט די נעמען פון די חכמי ישראל און וואָס רש\"י קלייבט אויס די גירסא „ר' מאיר אומר בו שלקו כו' א\"ל ר' יהודה כו' שראום במים כו'\" (און ניט ר' יהודה ור' יוסי), ווייל רש\"י האט שוין פריער אראפגעבראכט אַ פלוגתא צווישן ר\"מ און ר\"י, וואָס אויך דארטן איז זייער מחלוקת מיוסד אויף דער זעלבער סברא (און אויך דארטן איז רש\"י מקדים „נחלקו בו חכמי ישראל\"):\nוועגן דעם דין פון שוכר, שרייבט רש\"י אין פ' משפטים<sup data-n=\"19\">19</sup>: „ולא פירש מה",[["16","16","מעין זה — השקו\"ט זריזין מקדימין למצות וברוב עם הדרת מלך מאי עדיף (ראה שד\"ח כללים מע' ד' כלל ג'). וראה שד\"ח אסיפת דינים מע' יו\"כ ס\"א' סק\"י — השקו\"ט אם מותר (וצריך) להתענות בצום גדלי', באם עי\"ז יהי' לו קושי בהתענות ביו\"כ שלאחריו. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191073\" data-slug=\"likkutei-sichot\" data-id=\"1300191073\">לקו\"ש חי\"ט ע' 73</a> ואילך."],["17","17","ועפ\"ז יומתק ל' המחלוקת „בו שלקו כו'\", „שראום במים כו'\" — בסגנון של סיפור (ולא פליגי איך הי' הציווי) — כי לא הי' ציווי מפורט בהעשי', ותלוי בדעת חכמי ישראל, כבפנים."],["18","18","ובפרט בנדו\"ד, אשר אף ששני ציווים הם „ועשית\" „שמן גו' יהי'\" — הרי 1) הראשון הוא הכנה להשני (ובפרט — בפשטות הענין), 2) הראשון הוא לשעתו והשני — לתמיד."],["19","19","כב, יד. מב\"מ פ, ב. וש\"נ. ולהעיר, שלדעת רבה בר אבוה שם מוחלפת השיטה."]]],[1300161412,"דינא אם כשומר חנם (און איז מחוייב נאר אויף פשיעה) או כשומר שכר (און דארף באצאלן אויך פאר גניבה ואבידה) לפיכך נחלקו בו חכמי ישראל שוכר כיצד משלם ר' מאיר אומר כשומר חנם ור' יהודה אומר כשומר שכר\".\nאין פשטות זיינען זייערע טעמים: ר' יהודה האלט שוכר כשומר שכר ווייל ער באנוצט זיך מיט דעם שור, באקומט ער דאך שכר פאר זיין שמירה; ר' מאיר האלט אבער, אַז וויבאלד ער צאלט פאר זיין הנאה, קומט דאך אויס אַז ער באקומט ניט קיין שכר, ובמילא האט ער אַ דין פון שומר חנם<sup data-n=\"20\">20</sup>.\nולכאורה איז ניט פארשטאנדיק ר' יהודה'ס טעם וואָס ער איז מדמה אַ שוכר צו שומר שכר: דאָס וואָס אַ שומר שכר איז מחוייב אויף גניבה ואבידה איז דאָס ווייל ער באקומט שכר פאר זיין שמירה, ד. ה. דער מפקיד גיט אים שכר ער זאל היטן דעם חפץ מיט אַ שמירה מעולה יותר, צו פארהיטן דעם חפץ אויך פון גניבה ואבידה; און וויבאלד אַז דאָס וואָס דער משכיר גיט דעם שוכר רשות צו נוצן דעם שור איז עס (ניט פאר דער שמירה, נאר) פאר דעם שכר וואָס ער באקומט פאר דעם נוצן — איז פארוואָס זאל דאָס ארויפלייגן אויף דעם שוכר אַ חיוב שמירה (מעולה) פון אַ שומר שכר ווען ער באקומט ניט קיין שכר פאר זיין שמירה ?\nט. איז די הסברה אין דעם: די פלוגתא פון ר\"מ און ר\"י איז תלוי אין זייער פלוגתא הכללית, וואָס איז מכריע: הווה אדער עתיד *<sup data-n=\"20\">20</sup>.\nאַז מען נעמט אַן אַז דער משכיר רעכנט זיך בעיקר מיט'ן „הווה\" — דאָס וואָס ער וויל פארדינען געלט (דורך פארדינגען זיין שור) און דערביי זאל דער שור אויך זיין געהיט — דאן דארף זיין, אַז דער משכיר באנוגנט זיך אויך ווען דער שוכר וועט היטן זיין חפץ (ניט מיט דער שמירה מעולה פון אַ שומר שכר, בכדי צו פארהיטן אַ דבר בלתי רגיל וואָס קען פאסירן לעתיד, נאר) מיט דער שמירה רגילה פון אַ שומר חנם, וויבאלד אַז אויך דורך דער שמירה איז דער חפץ משומר בהווה וע\"ד הרגיל; און דער חשש אַז בעתיד וועט פאסירן אן ענין של גניבה ואבידה וועט ניט אים אפהאלטן פון צו (פארדינגען דעם חפץ און) פארדינגען געלט גלייך בהווה.\nאון דעריבער, לשיטת ר\"מ אַז „הווה\" איז מכריע לגבי „עתיד\" — דארף אויס-קומען אַז די שמירה אויף וועלכער דער משכיר האט זיך פארלאזן איז די שמירה רגילה פון אַ שומר חנם.\nמשא\"כ לשיטת ר\"י, אַז דער „עתיד\" איז מכריע לגבי „הווה\" איז כל זמן דער משכיר איז ניט פארזיכערט אַז דער חפץ וועט זיין אפגעהיט בשמירה מעולה באופן אַז אויך לעתיד זאל דער חפץ זיין גאנץ — וועט ער ניט מוותר זיין אויף דעם אפילו צוליב די געלט וואָס ער באקומט בהווה.",[["20","20","ראה פרש\"י ב\"מ שם (ד\"ה ר\"י אומר וד\"ה ר\"מ אומר). *20) במשנה ריש ע\"ז: ר' יהודה אומר נפרעין מהן מפני שמיצר הוא לו א\"ל אע\"פ שמיצר הוא עכשיו שמח הוא לאחר זמן (וראה ב' התירוצים בגמ' שם ו, ב) — אבל שם, הרי הטעם (כפרש\"י על אתר) שביום אידו יודה להעכו\"ם ואך זהו כל האיסור לכ\"ע. ועוד להוסיף (וג\"ז עיקר) — צער תלוי ברצון ורגש האדם (תענית חלום בשבת (ראה שו\"ע אדה\"ז או\"ח סי' רפח ס\"ג וד'), כיבוד אם דר\"י (ירושלמי קדושין פ\"א ה\"ז. הובא בב\"י יו\"ד סי' ר\"מ) וכו'), וכיון ששמח לאח\"ז — גם בהווה אינו צער."]]],[1300161413,"און וויבאלד אַז דער שוכר איז ניט קיין שומר חנם וואָס טוט אַ טובת חנם דעם מפקיד, נאר ער דינגט דעם חפץ און איז זיך משתמש מיט אים, נעמט מען אן אַז דער משכיר האט זיך פארלאזן אַז ער זאל היטן דעם חפץ מיט אַ שמירה מעולה<sup data-n=\"21\">21</sup>.\nיו\"ד. לחיזוק ההסברה אַז דאָס איז אַ לשיטתי' פון ר\"מ און ר\"י — נעתיק נאך אַן ארט וואו מען געפינט די זעלבע מחלוקת צווישן ר\"מ און ר\"י: „עד כמה מזמנין (ר\"מ האלט) עד כזית ור\"י אומר עד כביצה\"<sup data-n=\"22\">22</sup>.\nאיז די גמרא<sup data-n=\"23\">23</sup> מסביר זייער מחלוקת, אַז „בקראי פליגי ר\"מ סבר ואכלת זו אכילה ושבעת זו שתי' ואכילה בכזית, ור\"י סבר ואכלת ושבעת אכילה שיש בה שביעה ואיזו זו כביצה\".\nזאגט אבער דארט תוס'<sup data-n=\"24\">24</sup>, אַז „הני קראי אסמכתא בעלמא נינהו דמדאו-רייתא בעינן שביעה גמורה\" — מוז מען זאגן אַז דאָס וואָס יעדערער דרש'נט דעם פסוק אין זיין אופן איז דאָס מצד די רבנן, מצד זייער מחלוקת בסברא:\nלויט ר\"מ, אַז מ'רעכנט זיך מיט דעם „הווה\", דארף אויסקומען אַז (מדרבנן) בשעת ס'איז דאָ אן ענין פון אכילה דארף מען שוין בהווה מחוייב ווערן בזימון, און וויבאלד אַז שיעור אכילה בכזית<sup data-n=\"25\">25</sup>, דארף מען לערנען (באסמכ-תא) אַז דער „ואכלת\" איז אן ענין בפ\"ע, גלייך בהווה בשעת האכילה, וואָס „אכילה בכזית\" און מ'איז מחוייב בזימון.\nדאקעגן לויט ר\"י, אַז מען דארף נעמען אין באטראכט דעם עתיד, איז ניט מכריע דער ענין האכילה בהווה — נאר די פעולת ותוצאות האכילה, וואָס דער תכלית האכילה איז דאך צו ווערן זאט, און דאָס בריינגט דעם חיוב וברכת — עס דארף זיין „אכילה שיש בה שביעה ואיזו זו כביצה\".\nיא. שוין גערעדט פיל מאל — ווען מ'געפינט אַ מחלוקת צווישן תנאים (און גדולי ישראל בכלל) אין איין און דער זעלבער סברא אין עטליכע ערטער<sup data-n=\"26\">26</sup>, מוז מען זאגן אַז „וצריכא\", ס'איז דאָ אַ חידוש אין יעדן ארט באזונדער. ד. ה. אין יעדן ארט באזונדער איז דאָ אַ סברא אויף צו מחלק זיין און זאגן אַז דאָ גייט ניט אן דער „לשיטתי'\", און דערפאר ווערט די מחלוקת איבערגע'חזר'ט בא יעדן ענין באזונדער.\nובנדו\"ד:\nא) וויבאלד די עשיית שמן המשחה איז אַ ציווי פון אויבערשטן, וואָס ביי אים איז דאך הי' הווה ויהי' כאחד<sup data-n=\"27\">27</sup>, איז",[["21","21","ולהעיר מב' האופנים שי\"ל בחיובי השומרים: א) דבשעה שפושע (ועד\"ז גניבה ואבידה בשומר שכר וכו') אזי חל החיוב לשלם, ב) משעה שנמסר לו הפקדון נשתעבד ומתחייב להחזירו לו, אלא שגניבה ואבידה ואונס הוי פטור לש\"ח (ועד\"ז אונס בש\"ש וכו') — ראה בכ\"ז שו\"ע אדה\"ז או\"ח סתמ\"ג (קו\"א סק\"ב). קצוה\"ח סשמ\"מ סק\"ד. ולהעיר מהאריכות בפרש\"י ב\"מ שם (בדעת ר\"י): „דאי לא יהיב שכר הוי שואל כו' השתא דיהיב לי' אגרא לא הוי שואל והוי ש\"ש\" — כי לשיטת ר\"י שהעתיד מכריע, שומר מתחייב (לא רק על שמירת החפץ בהווה, אלא) „להחזיר לו בשלימות כשיגיע הזמן\", אלא ששומר חנם „חסה עליו התורה ופטרתו\" מגניבה ואבידה וכו', משא\"כ בשוכר."],["22","22","ברכות מה, א (במשנה). וש\"נ."],["23","23","שם מט, ב. וש\"נ."],["24","24","ד\"ה רבי מאיר סבר."],["25","25","בל' רש\"י: „ואכילה בכזית\". וכדמצינו בכ\"מ."],["26","26","ולהעיר, שבנדו\"ד יש דיעה דמוחלפת השיטה בכל ג' המקומות (בשמן המשחה — רק בדעת ר\"י) — ראה לעיל בפנים ס\"ב. הערה 19. לקמן הערה 32."],["27","27","שער היחוד והאמונה פ\"ז (פב, א) — ע\"פ זח\"ג (ברע\"מ) רנז, סע\"ב."]]],[1300161414,"דאך דער עתיד שוין פאראן בהווה.\nובפרט לויט דער הדגשה פון תוספתא<sup data-n=\"28\">28</sup> „שהימים והשעות כחוט השערה לפני המקום\" און ווי דער ראגאצאווער איז דאָס מפרש<sup data-n=\"29\">29</sup> אַז דאָס איז „כנקודה\", „חלק שאינו מתחלק\".\nאון הגם אַז דער קיום הציווי איז תלוי אין אידן — וויבאלד אבער עס האנדלט זיך וועגן מקיים זיין אַ ציווי פון אויבערשטן, דארף מען אים טאן ווי עס טראגט אויס מצד אים כביכול, וואָס הי' הווה ויהי' כאחד<sup data-n=\"30\">30</sup>.\nב) ביים פאל פון שוכר איז דאך ניטא קיין וודאות אַז בעתיד וועט זיין אַ גניבה או אבידה, ובפרט אַז עס איז דאך דאָ אַ שמירה (באופן פון שומר חנם, עכ\"פ) ס'איז בלויז אַ חשש רחוק (ניט ווי ביי „שמן המשחה\" און „עד כמה מזמנין\" וואו דער „עתיד\" איז אַ ודאי), ובמילא האט אן ארט צו זאגן, אַז דאָ דארף מען זיך רעכענען נאר מיטן הווה.\nנאכמער: ביי שוכר איז די גניבה בעתיד און די שכירה בהווה באזונדערע זאכן וואָס האבן ניט קיין שייכות צווישן זיך, וואלט מען פון דעם ניט געוואוסט בנוגע צו שמן המשחה — און אזוי אויך אין פאל פון זימון — וואָס דער עתיד איז דער תכלית און תוצאה פון דער פעולה שבהווה, וואָס דארטן קען מען זאגן אַז אלע האלטן אַז מען דארף זיך רעכענען בהווה אויך מיטן עתיד.\nג) ווען ס'וואלט געשטאנגען ביים פאל פון „עד כמה מזמנין\", וואלט מען דער-פון ניט געוואוסט ביי די אנדערע פאלן, ווייל דאָ איז די שאלה וואָס איז דער גדר פון אכילה (שבפסוק זה)<sup data-n=\"31\">31</sup>, ובמילא וואלט מען געקענט זאגן אַז דאָס האט בכלל ניט קיין שייכות צו די פלוגתא הנ\"ל<sup data-n=\"32\">32</sup> וואָס איז מכריע „הווה\" צי „עתיד\".\nדעריבער דארפן די דיעות דר\"מ ור\"י געבראכט ווערן אין אלע דריי ערטער.\n(משיחת ש\"פ תשא תשל\"ה)",[["28","28","עדיות פ\"א, יא."],["29","29","מהד\"ת ע' 20. תרומות ע' 116. ועוד. ראה מפענ\"צ פ\"ג סט\"ו."],["30","30","אבל לאידך אפ\"ל, שמכיון שהשלימות שבעתיד (שמן בפ\"ע) היא בניגוד ובסתירה להשלימות שבהווה (מרקחת), הי' אפ\"ל שבנדו\"ד מכריע ההווה שעל אתר — משא\"כ בשוכר וזימון שהווה (שמירה רגילה דש\"ח, ושיעור אכילה דכזית) אינה בניגוד להעתיד (שמירה דש\"ש, ואכילה בכביצה)."],["31","31","ועוד: מכיון שבלא\"ה אין כאן שביעה גמורה (שאז מחוייב מה\"ת) אפי' שלכו\"ע מחוייב רק על האכילה, או מכיון שמצינו שכל חיוב זימון מה\"ת היא רק בשביעה גמורה, צ\"ל שגם החיוב שמדרבנן הוא רק כשיש כדי שביעה (וע\"ד כל דתקון רבנן כעין דאורייתא כו')."],["32","32","ולהעיר שלדעת ר' יוחנן (ברכות שם. וש\"נ) מוחלפת השיטה."]]],[1300161415,"<h3>תשא ג</h3>\nא. אינעם פסוקי¹ „ויחל משה את פני ה' אלקיו ויאמר למה ה' יחרה אפך בעמך וגו'\", איז רש\"י מפרש די ווערטער „למה ה' וגו'\": „כלום מתקנא אלא חכם בחכם גבור בגבור\".\nבפשטות איז דאָ רש\"י אויסן צו באַווארענען בפירושו — ווי מפרשים² זיינען מבאר: וויבאַלד אַז אידן זיינען באַגאַנגען אַזאַ האַרבן חטא — ע\"ז (חטא העגל), איז דאָך מובן פארוואָס ס'איז געווען דער חרון אף — איז וואָס פרעגט משה רבינו „למה ה' יחרה אפך בעמך\"?\nאון צוליב דער תמי', זאָגן אַנדערע מפרשי התורה³, אַז דער מיין פון „למה\" דאָ איז (ניט „פארוואָס\", נאָר) „לא\"; ד.ה. משה האָט געבעטן בא דעם אויבערשטן „אל יחרה אפך בעמך\". רש\"י אָבער, וואָס איז מפרש פשש\"מ, טייטשט אויך דאָ דעם וואָרט „למה\" כפשוטו: פאַר־וואָס; דעריבער איז רש\"י מפרש אַז דער טעם הטענה „למה ה' יחרה אפך\" איז ווייל „כלום מתקנא אלא חכם בחכם גבור בגבור\".\nמען דאַרף אָבער פארשטיין: רש\"י האָט דאָך מסביר געווען אין פ' יתרו⁴, אַז דער טעם וואָס דער אויבערשטער האָט געזאָגט „אנכי ה' אלקיך\" — „לשון יחיד\" — איז כדי „ליתן פתחון פה למשה ללמד סניגורי' במעשה העגל וזהו שאמר למה ה' יחרה אפך בעמך לא להם צוית לא יהי' לכם אלקים אחרים אלא לי לבדי\" — היינט פארוואָס זוכט רש\"י דאָ אַן אנדער הסברה אויף משה רבינו'ס טענה „למה ה' יחרה אפך בעמך\"?\nמען קען ניט זאָגן, אַז רש\"י מיינט צו מפרש זיין דעם פסוק לויט ביידע הסברות⁵ און ער ברענגט דאָ ניט די הסברה פון פ' יתרו דערפאָר ווייל ער האָט עס שוין געזאָגט פריער — וואָרום עס איז ניט מסתבר אַז רש\"י זאָל דאָ בפרשתנו ביים מקור הענין אינגאַנצן ניט דערמאָנען דעם פירוש (אפילו בקיצור בלשון „ד\"א\" וכיו\"ב) און זיך פארלאָזן אויף דעם וואָס ער האָט עס מפרש געווען בדרך אגב ושלא במקומו אין פ' יתרו. ובפרט אַז יענע הסברה איז אַ שטארקערע — זי איז שולל אינגאַנצן אַ טענה צו אידן — ניט נאָר חרון אף וואָס קומט פון מתקנא.\nמוז מען זאָגן אַז די צוויי פירושים פון רש\"י זיינען מבאר צוויי באַזונדערע ענינים, כדלקמן.\nב. אויך דאַרף מען פארשטיין:\nפון פשטות לשון רש\"י „כלום מתקנא אלא חכם בחכם גבור בגבור\" איז מובן, אַז דער ענין פון „מתקנא\", איז בשייכות",[["1","1","פרשתנו לב, יא."],["2","2","רא\"ם. גו\"א. באר מים חיים כאן. ועוד."],["3","3","ראה (עה\"פ) דרשות ר\"י אבן שועיב „ובשביל זה פי' הגאון\". פי' רס\"ג עה\"ת (קאפח). וראה שם הערה 3. פשיטא — תרגום הסורי. וראה ראב\"ע „והנה למה ה' יחרה אפך בעמך כמו אל תשחת עמך כו'\". וברמב\"ן „כי זאת התפלה היא אשר הזכיר במשנה תורה כו' אל תשחת עמך כו'\"."],["4","4","כ, ב."],["5","5","ברא\"ם כאן „וזה וזה יכשר\". ובריב\"א „הרי לך פתרון המקרא בשני פנים מפי רש\"י\"."]]],[1300161416,"צו דער ע\"ז גופא — און אַזאַ טענה כלפי דעם אויבערשטן איז דאָך היפך הכבוד.\nנאָכמער: די טענה „כלום מתקנא וכו'\" איז די קשיא וואָס אגריפס (אַ גוי⁶) האָט געפרעגט ביי ר' גמליאל'ן⁷ (אויף דעם וואָס דער אויבערשטער ווערט אנגע־רופן „א־ל קנא\"⁸) און ר\"ג האָט דערויף געענטפערט (מיט אַ משל) אַז דער „מתקנא\" איז ניט אין דער ע\"ז, נאָר אין די עובדי ע\"ז⁹.\nאיז דאָך לפי\"ז תמוה:\nא) נניח אַז רש\"י האָט אַ הכרח אַז „כלום מתקנא וכו'\" איז געווען דער תוכן פון טענת משה — פארוואָס אָבער לערנט ער אַז די טענה איז געווען בנוגע דער ע\"ז גופא (ווי די קשיא הנ\"ל פון אגריפס), און ניט ווי דער מדרש¹⁰ (על אתר) טייטשט אויס די טענה פון משה: „אמר רבון העולם עשו לך סיוע ואתה כועס עליהם העגל הזה שעשו יהי' מסייעך כו'. אמר הקב\"ה משה אף אתה טועה כמותם והלא אין בו ממש אמר לו א\"כ למה אתה כועס על בניך כו'\" — וואָס דאָס איז: (א) מער אַ לשון של כבוד; (ב) אין דעם איז מודגש נאָר דער כעס „עליהם\", „על בניך\"?\nב) וויבאַלד אַז אויף דער טענה פון משה צום אויבערשטן „כלום מתקנא אלא חכם בחכם גבור בגבור\" געפינט מען ניט, בפשוטו של מקרא, קיין ענטפער, איז ניט גלאַטיק: וואָס איז דער שטורעם פון איסור ע\"ז, „לא יהי' לך אלקים אחרים גו' לא תעשה גו'\", וויבאַלד אַז זיי זיינען קיין שום מציאות ניט?\nג. אויך איז ניט מובן, פארוואָס זאָגט רש\"י די צוויי ענינים: „(כלום מתקנא אלא) חכם בחכם גבור בגבור\"¹¹?\nמ'קען ניט זאָגן אַז דאָס איז דערפאַר וואָס אזוי איז דער לשון אין פסוק¹² („אל יתהלל חכם בחכמתו גו' הגבור בגבורתו\") און אזוי אויך אין דעם סיפור הנ\"ל — ווייל:\n(א) אין פסוק, און אין דעם סיפור הנ\"ל, איז דאָ אויך אַ דריטער ענין „עשיר בעשרו¹³ (בעשיר)\", און רש\"י איז דאָס משמיט.",[["6","6","פרש\"י במס' ע\"ז שבהערה הבאה."],["7","7","ע\"ז נה, א. ובמכילתא יתרו כ, ה השאלה בשינוי לשון קצת. וראה הערה 9."],["8","8","ואתחנן ד, כד. ומה שלא הקשה עה\"פ בעשה\"ד יתרו כ, ה — מובן בפשטות ממה שמביא גם התחלת הכתוב כי ה\"א אש אוכלה הוא (דלכאורה רק על סיומו „א־ל קנא\" מקשה) — דזהו מגדיל ה„מתקנא\". ועד שקשור ב„אש אוכלה\". ולהוסיף כי ביתרו ממשיך „פוקד עון אבות על בנים גו'\". שמפורש שה„קנא\" הוא בעובדי', משא\"כ בואתחנן, שלא נאמר עונש לעובדי', ואדרבא, מדבר בגדולת ה' „כי ה\"א אש אוכלה הוא\". אבל להעיר דגם לפנ\"ז בגמרא שם (נד, ב) „שאל פלוספוס אחד את ר\"ג כו' מפני מה מתקנא בעובדי' ואין מתקנא בה\" הביא הכתוב דואתחנן. ולהעיר משינוי לשון רש\"י ביתרו ובואתחנן שם. ואכ\"מ."],["9","9","כן מובן מפרש\"י שם ד\"ה אין מתקנא „לשנוא את בעלה\". ובמכילתא מפורש זה בתוכן המענה, ע\"ד תשובת ר\"ג שהוזכרה בגמרא לפנ\"ז „שאל פלוספוס אחד את ר\"ג כו' מפני מה מתקנא בעובדי' ואין מתקנא בה\". ובמכילתא לפנינו בהשאלה „וכי יש כח בע\"ז להתקנאות בה\" נזכר „שאל פלוסופוס אחד\". וראה חדא\"ג שם."],["10","10","שמו\"ר פרשתנו פמ\"ג, ו (בסופו). וראה שם, ז (במדב\"ר פ\"ב, טו. פס\"ר פי\"א, ו). תנחומא פרשתנו כב. וראה הערה הבאה."],["11","11","כ\"ה ברוב הדפוסים, ובדפוס שני. אבל בדפוס ראשון ובכו\"כ כת\"י רש\"י איתא רק „גבור בגבור\". בפי' תוס' (הדר זקנים), ובפי' הרא\"ש הובא תוכן מדרשים הנ\"ל שבהערה שלפנ\"ז. ומפרשים „כלום גבור מתקנא אלא בגבור כמוהו\"."],["12","12","ירמי' ט, כב."],["13","13","וכ\"כ בעקידה כאן (שער שלשה וחמשים)."]]],[1300161417,"(ב) כידוע באַנוצט רש\"י אַ כפל (ואריכות — בכלל) דווקא ווען זיי ביידע (אָדער — די אריכות) זיינען נוגע צום פירוש פון פשוטן של כתובים — און ניט דערפאַר ווייל אזוי איז דער לשון אין פסוק און מאמרי רז\"ל.\nדאַרף מען פארשטיין: וואָס זיינען דאָ די צוויי ענינים נוגע אין פשוטו של מקרא?\nד. דער ביאור בזה:\nדער הכרח פון רש\"י אויף זיין פירוש „כלום מתקנא וכו'\" איז פון דעם וואָס אויף די ווערטער „למה ה' וגו'\" (אָדער, ווי אין אנדערע דפוסים, „למה ה' יחרה אפך\"¹⁴) וואָס ער איז מעתיק איז ניט גלאַטיק: נאָכדעם אַז דער אויבערשטער האָט געזאָגט צו משה „ועתה הניחה לי ויחר אפי בהם ואכלם גו'\", האָט דאָך משה געדארפט צום אלעם ערשטן באַוואַרענען דעם „ואכלם\" און טענה'ן „למה ה' תכלה את עמך\" (וכיו\"ב) און ערשט דערנאָך „למה ה' יחרה אפך\", ובפועל — האָט ער פריער געטענה'ט „למה ה' יחרה\" און דערנאָך — געגען „לכלותם\"?\nדי הסברה אין דעם:\nאויף דעם עצם חיוב מיתה פארן חטא העגל, איז ביי משה רבינו קיין קשיא ניט געווען. עס שטייט שוין פריער אין דער תורה, אַז עס זיינען דאָ כו\"כ עבירות פאַר וועלכע ס'קומט דער עונש מיתה ר\"ל — און מ'געפינט ניט קיין טענה ותמי' אויף דעם. און דער טעם דערפון איז מובן בפשטות: פאַר אַ האַרבער עבירה קומט אַ האַרבער עונש — מיתה ר\"ל.\nדי תמי' דאָ איז שייך בנוגע דעם אופן העונש — „ואכלם\" — וואָס מוז זיין פארבונדן מיט אַ סיבה מיוחדת:\nס'איז אַ כלל אין תורה, אַז דער חיוב ועונש מיתה קען זיין דווקא ווען ס'זיינען געווען עדות (נאָכדעם ווי ס'איז געווען התראה) און נאָך דער חקירה ודרישה פון ב\"ד¹⁵. אפילו ווען תורה זאָגט דעם לשון¹⁶ „מכשפה לא תחי'\", וואָס כפשוטו מיינט דאָס אַז מ'טאָר ניט דערלאָזן די „מכשפה\" זאָל לעבן¹⁷, באַוואַרנט אָבער רש\"י, אַז דאָס מיינט ניט אַז מ'זאָל הרג'ענען יעדע „מכשפה\" וואָס מ'זעט, „אלא תומת בב\"ד\".\nנאָכמער: אפילו ביים ערשטן חטא — חטא עץ הדעת, ביי וועלכן דער אויבערשטער האָט בפירוש געזאָגט אין דער אזהרה צו אדם הראשון¹⁸ „לא תאכל ממנו כי ביום אכלך ממנו מות תמות\", זעט מען פונדעסטוועגן, אַז אדה\"ר איז פאַר זיין עובר זיין ניט באַשטראָפט געווארן מיטן עונש מיתה און מיתה תיכף ומיד, נאָר ערשט נאָך דעם וואָס ער האָט געלעבט ניין הונדערט דרייסיג יאָר.\nמשא\"כ דאָ, ביים חטא העגל, האָט דער אויבערשטער געזאָגט „ועתה הניחה לי גו' ואכלם\" — דער עונש איז מיתה און באַלד נאָכן חטא¹⁹; און נאָכמער: „ואכלם\" מיינט אַלע אידן, אויך די וואָס האָבן ניט געדינט דעם עגל²⁰ —",[["14","14","ובדפוס שני „למה ה' יחרה\". ובדפוס ראשון ובכמה כתבי יד רש\"י נעתק גם „בעמך\". וכ\"ה ברא\"ם."],["15","15","ופשוט הוא עד כ\"כ שאין רש\"י צריך לפרשו בכל פעם שנאמר עונש מיתה."],["16","16","משפטים כב, יז."],["17","17","ועפ\"ז מובן הטעם שהוצרך רש\"י לפרש שם. וראה נח ט, ה-ו. פרש\"י שם. ובכ\"מ."],["18","18","בראשית ב, יז."],["19","19","ראה פרש\"י לקמן לב, כ: עדים בלא התראה במגפה כו' לא עדים ולא התראה בהדרוקן כו'."],["20","20","ראה פרש\"י לב, כו. — בנוגע לנשים וילדים"]]],[1300161418,"ווי ס'איז אויך מובן פון דעם ווייטער־דיקן המשך הדיבור „ואעשה אותך לגוי גדול\"²¹ (און ווי רש\"י זאָגט²² „אם כסא של ג' רגלים אינו עומד לפניך בשעת כעסך ק\"ו לכסא של רגל אחד\") —\nוואָס אַזאַ עונש קען ניט זיין מצד דער עבירה אליין²³, נאָר ווייל ס'איז „ויחר אפי בהם\" (און דערפאַר דער חומר העונש — נאָכמער ווי דאָס קומט פאַר דער עצם עבירה).\nאון דאָס איז געווען טענת משה: „למה ה' יחרה אפך — כלום מתקנא אלא חכם בחכם וכו'\": ס'לאָזט זיך פארשטיין וואָס עס קומט אַן עונש חמור פארן הארבן חטא ע\"ז, ובפרט אַז דאָס דינען „אלקים אחרים\" האָט קיין אַרט ניט אין שכל צו מיינען אַז זיי זיינען עפעס אַ ממשות ח\"ו (און אויך ניט קיין אַרט אין מידות, צו האָבן אַ תאוה דערצו)²⁴, ווי רש\"י איז פריער מפרש²⁵: „שאינן אלקות אלא אחרים עשאום אלקים עליהם\", איז\nבמילא מובן, אַז פאַר אַזאַ חטא קומט אַ עונש חמור:\nאָבער פון דעם וואָס דער אויבערשטער האָט געזאָגט „ואכלם\" — (א) אָן ב\"ד, (ב) תיכף ומיד, (ג) אַלע אידן — איז דאָך מוכח, אַז דאָס איז אַן עונש וואָס ער קומט ניט נאָר מצד (ובהתאם צום חטא פון) די עובדי העגל, נאָר דאָס איז מצד אַ חרון אף בשייכות צו דער ע\"ז גופא²⁶.\nאון דעריבער האָט משה געטענה'ט „למה ה' יחרה אפך\" — מצד דעם עגל הזהב — „כלום מתקנא אלא חכם בחכם וכו'\": דער עגל איז דאָך קיין מציאות ניט אַז דאָס זאָל גורם זיין דעם „מתקנא\" (דעם חרון אף) אין דער ע\"ז און דאָס זאָל אַרויסרופן דעם עונש „ואכלם\" אויף אַלע אידן און תיכף ומיד.\nה. עפ\"ז איז מובן פארוואָס רש\"י ברענגט דאָ ניט דעם פירוש וואָס ער זאָגט אין פ' יתרו „ליתן פתחון פה למשה .. וזהו שאמר למה ה' יחרה אפך בעמך לא להם צוית כו'\":\nדארטן איז רש\"י מפרש די הדגשה פון משה'ס טענה (לויטן פירוש וואָס איז נוגע דאָרט על אתר פון ציווי), אַז ס'איז דאָ אַ „פתחון פה\" אפילו פאַר די עובדי העגל עצמם, אַז אויך זיי זיינען ניט מחוייב כלל קיין עונש צוליבן ציווי „לא יהי' לך אלקים אחרים גו'\". אָבער לערנענדיק פשוטו של מקרא דאָ — בסיפור כל המאורע, איז מוכח פון דעם לשון „למה ה' יחרה אפך גו'\", אַז די טענה איז ניט אויפן עצם עונש פון די עובדי העגל, נאָר אויפן ענין פון „יחרה",[["","","להעיר מפרש\"י פרשתנו שם, ב „אמר אהרן בלבו הנשים והילדים חסים בתכשיטיהן כו' והם לא המתינו ופרקו מעל עצמן\" (בדפוס א', „ופרקו של עצמם\". ובדפוס ב' — „שעל\"). ולהעיר מפרש\"י שם, ו."],["21","21","לב, י."],["22","22","שם, יג."],["23","23","בעונש עיר הנדחת (ראה פרש\"י פרשתנו שם, כ) נאמר (ראה יג, טז) „הכה תכה את יושבי העיר ההוא גו' החרם אותה ואת כל אשר בה ואת בהמתה גו'\". ויל\"ע עפ\"י פשש\"מ איך הדין באנשים נשים וטף שלא הודחו עמה (ע\"ד ההלכה — ראה רמב\"ן שם. ובכ\"מ). אבל גם שם: א) צ\"ל „ודרשת וחקרת ושאלת היטב גו'\" „שבע חקירות\" (שם, טו וברש\"י). ב) נאמר (שם, יח) „חרון אפו\". ואכ\"מ."],["24","24","להעיר מיומא (סט, ב) ביצרי' דע\"ז. אבל ע\"פ פשש\"מ לא מצינו לכאורה שינוי בזה (שאז הי' להם יצה\"ר לע\"ז). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111152\" data-slug=\"likkutei-sichot\" data-id=\"1300111152\">לקו\"ש חי\"א ע' 144</a> ואילך שבקשו ממוצע במקום משה אלא שאח\"כ בא מזה חטא ע\"ז."],["25","25","יתרו כ, ג."],["26","26","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171206\" data-slug=\"likkutei-sichot\" data-id=\"1300171206\">לקו\"ש חי\"ז (ע' 206</a> ואילך) בחרון אף דע\"ז (ע\"ד ההלכה)."]]],[1300161419,"אפך\" בשייכות צו דער ע\"ז אליין²⁷, וכנ\"ל בארוכה.\nו. עפ\"ז איז אויך מובן וואָס רש\"י זאָגט דאָ די צוויי ענינים „חכם בחכם גבור בגבור\": אין דעם אויבערשטנ'ס דיבור צו משה „לך רד כי שחת עמך גו'\" האָט ער געזאָגט „סרו מהר מן הדרך אשר צויתים עשו להם עגל מסכה וישתחוו לו ויזבחו לו ויאמרו אלה אלקיך ישראל אשר העלוך מארץ מצרים\" — וואָס הגם אַז די אידן²⁸ האָבן דאָס טאַקע געזאָגט, אָבער צוליב וואָס ברייענגט עס דער פסוק — וואָס איז נוגע צום גודל החטא פון „עשו להם עגל מסכה וישתחוו לו ויזבחו לו\" אַז זיי האָבן דערביי געזאָגט „אלה אלקיך ישראל אשר העלוך מארץ מצרים\"? און עד\"ז געפינט מען אויך אין משה'ס טענה צום אויבערשטן „למה ה' יחרה אפך בעמך\" אַז ער פירט אויס „אשר הוצאת מארץ מצרים בכח גדול וביד חזקה\".\nנאָר פון דעם גופא איז אַ הוכחה, אַז דער חרון אף (דער ענין פון „מתקנא\") האָט געהאַט אַ שייכות (אויך) מיט דעם וואָס זיי האָבן געזאָגט „אלה אלקיך ישראל אשר העלוך מארץ מצרים\", און אַז אויף דעם איז געווען טענת משה „כלום מתקנא\" אין ביידע פרטים פון „חכם\" און „גבור\".\nוהביאור: אויף צו אַרויספירן די אידן פון מצרים און פירן זיי אין מדבר האָבן זיך געפאָדערט צוויי זאַכן — „חכמה\" און „גבורה\", אָבער ניט (אַ קיין הכרח פון) עשירות ווי ס'איז מובן, אַז די פרטים פון יצי\"מ וכו' מיט די נסים ונפלאות זיינען געווען פארבונדן מיט גרויס חכמה (ווי זיי דורכפירן)²⁹ און גבורה (ביים דורכפירן לפועל).\nועוד: דאָס וואָס עובדי העגל האָבן געוואָלט הילף וכו' איז ניט בנוגע עשירות ווייל ווי רש\"י האָט שוין מודיע געווען האָבן זיי שוין געהאַט אַן עשירות מופלגה פון ביזת מצרים און נאָכמער פון ביזת הים³⁰.\nאון דאָס האָט משה רבינו געזאָגט: „למה ה' יחרה אפך\", דער „מתקנא\" אין דעם עגל האָט דאָך קיין אַרט ניט, וואָרום „כלום מתקנא אלא חכם בחכם גבור בגבור\" — דער אמת איז דאָך אַז דער אויבערשטער האָט זיי אַרויס־גענומען פון „מצרים בכח גדול וביד חזקה\", און ניט דער עגל ח\"ו, די ע\"ז האָט דאָך ניט קיין חכמה אָדער גבורה, טאָ ווי איז שייך צו „מתקנא\" זיין אין דער ע\"ז!\nז. מ„יינה של תורה\" בפרש\"י:\nלכאורה דאַרף מען נאָך אלץ פאַר־שטיין: כאָטש אַז בנוגע דער ע\"ז האָט קיין אַרט ניט צו זיך „מתקנא\" זיין, וואָרום „כלום מתקנא אלא חכם בחכם גבור בגבור\", אָבער מצד די וואָס האָבן געדינט דעם עגל און געזאָגט „אלה אלקיך ישראל אשר העלוך מארץ מצרים\", איז דאָך לכאורה דאָ אַן אַרט",[["27","27","ועפ\"ז מובן גם זה שלא פרש\"י שטענת משה היתה „למה ה' יחרה אפך בעמך\" — באותם שלא עבדו העגל וכיו\"ב, ועפמש\"כ לפנ\"ז „שחת עמך — ערב רב שקבלת מעצמך כו' הם שחתו והשחיתו\", וככמה מפרשי התורה (ראה ספורנו. אברבנאל (אופן הא'). אוה\"ח. ריב\"א. ועוד) — כי ע\"ז הו\"ל לטעון למה ה' יכלה גו' וכיו\"ב."],["28","28","ראה פרש\"י לב, ד. ומסיים „ואח\"כ הטעו את ישראל אחריהן\"."],["29","29","וכן אמרו לפנ\"ז (לב, א) „עשה לנו אלקים אשר ילכו לפנינו\"."],["30","30","בשלח טו, כב."]]],[1300161420,"ח\"ו פארן ענין פון „מתקנא\" — „א־ל קנא\" — אין די עובדי העגל, וויבאַלד אַז זיי האָבן דאָך געמיינט אַז דער עגל איז אַ „חכם\" און אַ „גבור\".\nאיז דער ביאור אין דעם:\nאַ איד מצד עצמו האָט ניט קיין טעות אין ע\"ז³¹, ער ווייס אַז דאָס איז נאָר אַן עץ ואבן און ער גיט ניט קיין שום חשיבות צו ע\"ז, אפילו ביים עובר זיין אויף דעם חטא, וואָרום „גם בשעת החטא היתה באמנה אתו ית'\"³², וכמאמר אדמו\"ר הזקן: אַ איד ניט ער וויל און ניט ער קען זיין אפגעריסן פון אלקות³³. און דאָס וואָס דער עובד ע\"ז האָט געזאָגט „אלה אלקיך ישראל\" איז דאָס נאָר דער־פאַר וואָס „נכנס בו רוח שטות\"³⁴ (און דערפון קומען אזעלכע רייד), וואָס דער רוח שטות איז אַ באַזונדער זאַך פון דעם אידן אליין (נכנס בו).\nאון דאָס איז די טענה פון משה „למה ה' יחרה אפך בעמך\" — אויך מצד „עמך\"³⁵, מצד די אידן, דאַרף ניט זיין קיין אַרט אויף „מתקנא\", ווייל מצד מהותם איז בײ זיי אינגאַנצן מושלל צו מחשיב זיין ח\"ו די ע\"ז אַלס „חכם\" אָדער „גבור\" — און דעריבער איז „כלום מתקנא³⁶ אלא חכם בחכם גבור בגבור\", און דאָס האָט געפועל'ט אַז וינחם הוי' גו'.\n(משיחת ש\"פ תשא תשל\"ב)",[["31","31","<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט</a>."],["32","32","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ\"ד</a>."],["33","33","ראה ד\"ה באתי לגני ה'שי\"ת פ\"ג. היום יום ע' עג."],["34","34","ובמכש\"כ משאר עבירות — סוטה ג, א. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310030\" data-slug=\"tanya\" data-id=\"3401310030\">תניא שם</a> ופכ\"ה. ולהעיר מסנה' (קו, א. הובא בפרש\"י בלק (כה, ב)): וישתחוו לאלהיהן. כשתקף יצרו עליו (דג\"ע)."],["35","35","גם אלה שהם כמו (גחלים) עוממות (שער היחוד והאמונה פ\"ז)."],["36","36","ואף שמצד המעשה והבפועל דעובדי ע\"ז הי' צ\"ל קנאה — י\"ל עפ\"י משנ\"ת באוה\"ת בראשית (ריט, ב) „הקנאה שנוגע בהעצמות והעצמיות\", וא\"כ נוגע בעיקר מה שבפנימיותם ובעצמיותם."]]],[1300161421,"<h3>תשא ד</h3>\nא. אין פסוק<sup data-n=\"1\">1</sup> „וידבר ה' אל משה לך עלה מזה אתה והעם אשר העלית מארץ מצרים גו'\", איז רש\"י מפרש (אין דעם צווייטן דבור המתחיל): „אתה והעם, כאן לא אמר ועמך\".\nבפשטות, קומט דער פירוש רש\"י בהמשך צום (צווייטן פירוש אין) פריער־דיקן דבור המתחיל „לך עלה מזה\" — „כלפי שא\"ל בשעת הכעס לך רד<sup data-n=\"2\">2</sup> א\"ל בשעת רצון לך עלה\"; און בהמשך צו דעם זאגט רש\"י, אז פונקט ווי בנוגע צו משה'ן האט דער אויבערשטער, דורכן זאגן „לך עלה\", „מרפא\" געווען דאס וואס ער האט פריער („בשעת הכעס\") געזאגט „לך רד\" — אזוי אויך בנוגע צו אידן: תמורת זה וואס פריער האט דער אויבערשטער געזאגט „(לך רד) כי שחת עמך אשר העלית מארץ מצרים\", וואס איז אן אויסשפראך ניט אין דעם שבח פון אידן (ווי רש\"י<sup data-n=\"3\">3</sup> טייטשט דארט „שחת עמך, שחת העם לא נאמר אלא עמך ערב רב שקבלת מעצמך כו' הם שחתו והשחיתו\"), האט דער אויבערש־טער איצטער געזאגט „(לך עלה מזה..) אתה והעם גו'\" (ניט „ועמך\").\nמען דארף אבער פארשטיין: בשלמא אין דעם פריערדיקן פסוק, וואו עס רעדט זיך וועגן דעם ערב רב, וואס „הם שחתו והשחיתו\", איז מובן פארוואס רש\"י דארף מפרש זיין דעם דיוק וואס דער פסוק זאגט „עמך\" און ניט „העם\", וואָרום ביז איצט האט מען נאך ניט\nגעלערנט אז נאר ערב רב ווערן אנגע־רופן „עמך\": אבער נאכדעם — אין אונזער פסוק, וואו עס רעדט זיך וועגן דעם גיין קיין ארץ ישראל — „עלה גו' אל הארץ אשר נשבעתי גו'\" — רעדט זיך דאך בפשטות וועגן אלע אידן, היינט פארוואס זאל גאר זיין א קס\"ד אז עס זאל שטיין „עמך\" און רש\"י זאל דאס דארפן באוארענען (אז „כאן לא אמר ועמך\")?\nולאידך: אויב עס איז דא א סברא אז אלע אידן זאלן אנגערופן ווערן (אויך) „עמך\" און בענין זה זאלן זיי דערמאנט ווערן מיט דעם נאמען דוקא, וואס דער־פאר איז עס א חידוש והדגשה אז „כאן לא אמר ועמך\" — האט זיך רש\"י געדארפט שטעלן אויף „לך נחה את העם אל אשר דברתי לך\" — וואס שטייט (מיט צוויי פסוקים) פריער<sup data-n=\"4\">4</sup> — און זאגן דארט „כאן לא אמר עמך\"<sup data-n=\"5\">5</sup>?\nב. איז דער ביאור אין דעם: רש\"י וויל דא באוארענען (נאך) אן ענין בלתי מובן: בשלמא וואס דער פסוק דארף דא זאגן „לך עלה מזה\" בנוגע צו משה'ן („אתה\"), איז עס ווייל ביז איצט געפינט",[["1","1","פרשתנו לג, א."],["2","2","פרשתנו לב, ז."],["3","3","עה\"פ שם."],["4","4","לב, לד."],["5","5","ובפרט שה„שעת רצון\" שבפרש\"י כאן כבר הותחלה לכאורה מהדיבור „לך נחה גו'\" — ראה פרש\"י עקב (י, יא), דמשמע, שהדיבור „לך נחה גו'\" הי' במ' יום האחרונים *, עיי\"ש (ומתורצת עפ\"ז קושיית המשכיל לדוד כאן). *) ולהעיר שגם הפסוקים לג, ז־יא הם הנהגת משה „מיום הכפורים עד שהוקם המשכן\" (פרש\"י שם, יא)."]]],[1300161422,"מען ניט אז עס זאל פון אים אראפ־גענומען ווערן דער „לך רד\":\nאבער בנוגע צו אלע אידן, צום „עם\": וויבאלד עס שטייט שוין פריער „לך נחה את העם אל אשר דברתי לך\", וואס איז מוסיף דער „לך עלה גו' אל הארץ גו'\" אויף דעם וואס איז שוין געשטאנען פריער<sup data-n=\"6\">6</sup>? ועד כדי כך — אז דאס איז געווען א באזונדערן דיבור פון אויבערשטן — „וידבר ה' אל משה לך עלה גו'\", ובהפסק הסיפור „ויגוף ה' את העם גו'\"?\nדעריבער לערנט רש\"י, אז די צוויי פסוקים ריידן וועגן צוויי באזונדערע סוגים: „לך נחה את העם גו'\" רעדט וועגן די בני אברהם יצחק ויעקב (און די אנדערע „אשר חטא לי — אמחנו מספרי\"), און דערנאך נאך „ויגוף ה' גו' (קצת מפרעון) על אשר עשו את העגל\" *<sup data-n=\"6\">6</sup> קומט א חידוש (און דערפאר — אין א באזונדער דיבור) „לך עלה מזה גו' והעם גו'\" רעדט נאר וועגן דעם ערב רב<sup data-n=\"7\">7</sup>, וואס זיי דארפן א באזונדער באוארעניש (און תיקון), כדלקמן סעיף ה'.\n[עפ\"ז איז אויך גלאטיג וואס דער פסוק זאגט דא „והעם אשר העלית\nמארץ מצרים\" (אז משה האט זיי ארויס־גענומען פון מצרים) — דער זעלבער לשון וואס שטייט פריער „שחת עמך אשר העלית מארץ מצרים\" (וואס מיינט דעם „ערב רב שקבלת מעצמך\" כנ\"ל) — ווייל אויך דא מיינט דער פסוק נאך דעם ערב רב].\nג. דער חילוק צווישן די צוויי סוגים הנ\"ל בשייכות צו די עובדי העגל בפועל — איז מפורש אין פסוק:\nרש\"י האט שוין פריער<sup data-n=\"8\">8</sup> מפרש געווען: „שלש מיתות נדונו שם אם יש עדים והתראה בסייף .. עדים בלא התראה במגפה .. לא עדים ולא התראה בהדרוקן שבדקום המים וצבו בטניהם\".\nביי די „שלש מיתות\" ווי זיי ווערן דערציילט אין פסוק, געפינט מען א שינוי בולט: ביי „סייף\" שטייט<sup data-n=\"9\">9</sup> „ויפול מן העם גו'\", אויך ביי דער מגפה שטייט<sup data-n=\"10\">10</sup> „ויגוף ה' את העם\", דאקעגן ביי די וואס „בדקום המים וצבו בטניהם\" שטייט<sup data-n=\"8\">8</sup>: וישק את בני ישראל.\nדער חילוק צווישן „עם\" און „בני ישראל\" איז אין פשטות: „עם\" איז כולל דעם גאנצן פאלק — אויך די גרים כו', „בני ישראל\" (ווען עס קומט בניגוד צו „עם\") מיינט — בני אברהם יצחק ויעקב<sup data-n=\"11\">11</sup>; און ווי דאס איז אויך אין פסוק<sup data-n=\"12\">12</sup> ביי יצי\"מ: „ויסעו בני ישראל גו' כשש מאות אלף רגלי הגברים גו' וגם ערב רב עלה אתם\" — זעט מען אז דער",[["6","6","וגם זה ד„ושלחתי לפניך מלאך\" (לג, ב) כבר נאמר לפנ\"ז — „הנה מלאכי ילך לפניך\" (וראה גם משפטים כג, כ (וברש\"י) ואילך). ועיקר: גם את\"ל שנתוסף איזה פרט בהדיבור „לך עלה גו'\" — למה נאמר בפ\"ע ולא כללו יחד עם הדיבור „לך נחה גו'\"? ואף ש„לך נחה את העם\" קאי על משה ו„לך עלה גו' והעם\" מדבר אל בנ\"י (שהם יעלו) — מ\"מ, מכיון שתוכן הענין אחד הוא (ההליכה אל הארץ גו'), הו\"ל לכללם יחד. ולהעיר מעקב שם ובפרש\"י. *6) וראה רמב\"ן לב, לד־לה."],["7","7","אף שעפ\"ז צע\"ק מה שדוקא בפסוק זה ממשיך „נשבעתי לאברהם גו' לזרעך אתננה\"."],["8","8","לב, כ."],["9","9","שם, כח."],["10","10","שם, לה."],["11","11","ואף שבכ\"מ פשוט שקאי על כל ישראל, גם הגרים (וברובם כבכולם דהצוויים נאמר „דבר אל בנ\"י\" וכיו\"ב) — מ\"מ, במקום שהפסוק משנה מ„עם\" ל„בנ\"י\" כבנדו\"ד משמע שהתוכן שונה — כבפנים."],["12","12","בא יב, לז־לח."]]],[1300161423,"ערב רב גייט ניט אריין אין דעם מספר פון (די ס' רבוא<sup data-n=\"13\">13</sup> פון) בנ\"י<sup data-n=\"14\">14</sup>.\nועפ\"ז קומט ארויס א חידוש גדול: ווייבאלד אז דער פסוק זאגט „וישק את בני ישראל\", איז דערפון מוכח, אז דעם ערב רב האט מען ניט משקה געווען; ובמילא דארף מען זאגן, אז די פון ערב רב וואס האבן געדינט דעם עגל בלא עדים ובלא התראה זיינען געבליבן לעבן<sup data-n=\"15\">15</sup>,\nאון דער „אמחנו מספרי\" — איז ניט געווען „לכלותם יחד\" — נאר „וביום פקדי ופקדתי\" ווי בא בנ\"י, וואַרעם אויך אויך דעם ערב רב האט משה רבנו געבעטן און דער אויבערשטער האט דאך געענטפערט „שמעתי אליך\"<sup data-n=\"16\">16</sup>.\nד. פארוואס האט מען טאקע דעם ערב רב ניט משקה געווען? איז רש\"י דאס מבאר אין זיין פירוש אויף „וישק את בני ישראל\"<sup data-n=\"8\">8</sup> און אין זיין פירוש בהמשך הפרשה:\nאויף „וישק את בני ישראל\"<sup data-n=\"8\">8</sup> זאגט רש\"י „נתכוין לבדקם כסוטות\" — ווי\nפאסט דא דער ענין פון „סוטות\" *<sup data-n=\"16\">16</sup>? איז עס מובן פון פירוש רש\"י אין המשך הפרשה. אויף „פסל לך\"<sup data-n=\"17\">17</sup> זאגט רש\"י: „משל למלך כו' והניח ארוסתו עם השפחות כו' כך המלך זה הקב\"ה השפחות אלו ערב רב והשושבין זה משה ארוסתו של הקב\"ה אלו ישראל\" — ד.ה. אז דער חטא העגל איז בדוגמת דעם קלקול פון אן ארוסה<sup data-n=\"18\">18</sup>, און דער־פאר — „נתכוין לבדקם כסוטות\".\nועפ\"ז איז מובן בפשטות פארוואס דעם ערב רב האט מען ניט משקה געווען — וואָרום ווייבאלד אז „השפחות אלו ערב רב\", ד.ה. זיי זיינען ניט „ארוסתו של הקב\"ה\", איז דאך ביי זיי ניט שייך דער ענין פון „לבדקם כסוטות\".\nה. ע\"פ כהנ\"ל איז פארשטאנדיק דער אויפטו אין פסוק „לך עלה גו' והעם גו'\" בהוספה אויף „לך נחה את העם גו'\":\n„לך נחה את העם גו'\" רעדט זיך דאך וועגן די אידן וואס האבן ניט געדינט דעם עגל [וואָרום די עובדי העגל מבנ\"י נדונו בשלש מיתות], און זייער חטא איז באשטאנען אין דעם וואס זיי האבן ניט מוחה געווען (וכיו\"ב)<sup data-n=\"19\">19</sup>;\nדאקעגן ביים פסוק „לך עלה גו'\" האט דער אויבערשטער מודיע געווען משה'ן א דבר חדש, אז אפילו די פון ערב רב",[["13","13","וכדמוכח ג\"כ מהמנין דפ' במדבר ופ' פינחס שלא נמנו כ\"א בני השבטים."],["14","14","ראה תיב\"ע ומכילתא בא שם."],["15","15","ודוחק גדול לומר שלא הי' אף א' מהערב רב שחטא בלא עדים ובלא התראה (ולא הי' מי להשקות). ולהעיר: מפשטות לשון רש\"י „עמך ערב רב .. הם שחתו והשחיתו\" (ועד\"ז מפרש\"י לעיל לב, ד. לקמן לד, א) משמע לכאור', שכל הערב רב חטאו בעגל, ומכיון שמצינו מהערב רב גם לאחרי חטא העגל (פרש\"י בהעלותך יא, א. שם, ד), עכצ\"ל כבפנים (שלא מתו כולם)."],["16","16","אלא שהסדר בזה הוא שתחלה צ\"ל „ויגוף גו'\" פרעון קצת — ואח\"כ דבור (ומחילה) בגלוי „עלה גו' והעם\". *16) ואף שזהו בדרז\"ל (ע\"ז מד, רע\"א) — הרי מכיון שמביאו רש\"י בפירושו עה\"ת מובן שכ\"ה גם ע\"ד הפשט."],["17","17","פרשתנו לד, א."],["18","18","להעיר (ע\"ד הדרוש) מאהבת יהונתן הפטורת במדבר. חת\"ס עה\"ת פרשתנו לב, כח."],["19","19","ולשון רש\"י (לב, יט) „וכל ישראל משומדים (מומרים)\" — בלאה\"כ צ\"ל שהוא לאו דוקא, שהרי כל שבט לוי כשר (פרש\"י שם, כו. ברכה לג, ט)."]]],[1300161424,"וואס האבן חוטא געווען בעגל [און זיינען געבליבן לעבן ווייל עס דערביי ניט געווען קיין עדים והתראה] זאל אויך ביי זיי זיין „לך גו'\", און נאכ־מער — „לך עלה גו'\", אז (אויך) ביי זיי וועט זיין אן ענין פון עלי':\nאין וואס באשטייט זייער עלי' — זאגט רש\"י „כאן לא אמר ועמך\": זיי האבן תשובה געטאן אויף זייער חטא, ובמילא קען מען זיי איצטער אנרופן (ניט „עמך\", נאר א העכערן נאמען) „העם\".\nו. דערמיט איז אויך פארענטפערט וואס דוקא דא איז דער פסוק מדייק און מוסיף (אויף'ן פריערדיקן „לך נחה את העם אל אשר דברתי לך\") „לך עלה מזה אתה והעם גו'\", דלכאורה האט גע־דארפט שטיין „לך עלה אתה והעם גו'\"\nדער דיוק דא איז<sup data-n=\"20\">20</sup> אז דער „עלה\" זאל זיין „מזה\"<sup data-n=\"21\">21</sup> — אוועק (און — העכער) פון דעם חטא העגל [ביי משה'ן — וואס „לא נתתי לך גדולה אלא\nבשבילם\"<sup data-n=\"22\">22</sup>, און ביי דעם ערב רב — וואס האבן געדינט דעם עגל].\nמשא\"כ די בני ישראל (וועגן וועלכע מ'זאגט „לך נחה את העם גו'\") וואס האבן ניט געדינט דעם עגל, דארף ניט זיין די הודעה „לך גו' מזה\" (פון חטא העגל).\nז. סוף סוף איז אבער פארט ניט גלאטיק: ווי קומט עס פארט אז דוקא פון דעם ערב רב, וואס זיי זיינען געווען דער עיקר החוטאים און עובדי העגל („הם שחתו והשחיתו\") — (א) זיינען ניט אלע נידונו במיתה<sup data-n=\"23\">23</sup>, (ב) ביי זיי שטייט (ניט „נחה\", נאר) „עלה\"?\nוי\"ל — בהקדם מחז\"ל<sup data-n=\"24\">24</sup> אז דער משכן איז נצחי ווייל מעשה משה זיינען נצחיים — וואס דער זהב וכסף וגו' איז געווען פון אלע אידן, מעשה המשכן וכליו — איז געווען דורך בצלאל וכו' ניט דורך משה'ן<sup data-n=\"25\">25</sup> — נאר די הקמה איז געווען ע\"י משה (און דער ביאור ווי עס צו מאכן — „אשר הראית\" *<sup data-n=\"25\">25</sup>) — עאכו\"כ „ערב רב<sup data-n=\"26\">26</sup> שקבלת מעצמך",[["20","20","ראה גם רע\"ב כאן."],["21","21","וי\"ל שדיוק זה מתורץ גם לפירוש הראשון ברש\"י על „לך עלה מזה\" — „ארץ ישראל גבוה מכל הארצות\" — כי דוקא מזה שנאמר „לך עלה מזה גו' אל הארץ גו'\" ידעינן ש„א\"י גבוה מכל הארצות\". והביאור: מכיון שמשה הי' אז בהר *), הרי עלייתו לא\"י אינו „מזה\" (מן ההר) שהרי מקודם הוצרך לירד מן ההר: אלא שהפסוק מדגיש „עלה מזה\" ללמדנו שגם ההליכה לא\"י ממקום גבוה (כמו הר) נק' „עלה\", כי „א\"י גבוה מכל הארצות\". *) שהרי בפשטות הי' דיבור זה באותו הזמן של הדיבור „לך נחה גו'\" (וכדמשמע גם מעקב י, יא ובפרש\"י), שהרי כאשר „וישב משה אל ה'\" (פרשתנו לב, לא)."],["22","22","פרש\"י לעיל לב, ז."],["23","23","ע\"ד הפשט אפ\"ל שהוא עדמש\"נ (עמוס ג, ב) „רק אתכם ידעתי גו' על כן אפקוד עליכם את כל עונותיכם\"."],["24","24","סוטה ט, סע\"א (הובא בילק\"ש תהלים רמז תש\"כ), וראה תדבא\"ר פי\"ח. צפע\"נ עה\"ת ר\"פ תרומה. ברכה לד, א."],["25","25","פרש\"י פקודי לט, לג. *25) תרומה כו, ל."],["26","26","וראה ע\"ח שער ש\"ב פ\"ב „הם ניצוצין של משה בסוד כו' שחת עמך כו' ע\"כ טרח בעבורם כ\"כ ומת במדבר בעבורם — כי רצה לתקנם — כנזכר במ\"א\" — וראה שער הפסוקים בפ' שמות בארוכה. *) להעיר מדברים רבה פ\"ב, ט. זח\"ב קנו, סע\"א."]]],[1300161425,"וגיירתם\", וואס דאמאלס איז עס „הנפש אשר עשה\"<sup data-n=\"27\">27</sup>.\nח. דער ביאור פנימי בזה י\"ל: דער שלימות התיקון פון חטא העגל דריקט זיך אויס אין דעם וואס מ'האט דעם ערב רב [ניט מאבד געווען, נאר] מתקן און מעלה געווען, כדלקמן.\nוועט מען דאס פארשטיין בהקדם וואס חז\"ל<sup data-n=\"28\">28</sup> זאגן בנוגע צום חטא העגל „לא ישראל ראוין לאותו מעשה\" און דער חטא העגל „גזירת מלך היתה כו' כדי ליתן פתחון פה לבעלי תשובה\".\nאיז ידוע<sup data-n=\"29\">29</sup> דער ביאור פנימי אין דעם, אז דער ענין פון „ליתן פתחון פה לבעלי תשובה\" מיינט ניט נאר צוליב שפעטערדיקע בעלי תשובה, נאר (אויך) אז אידן אין יענער צייט זאלן צוקומען צום עילוי פון תשובה. וואָרום תשובה איז דאך אן עבודה וואס דער מענטש קען זיך ניט אויסקלייבן לכתחילה — אדרבה: האומר אחטא ואשוב אין מספיקין בידו לעשות תשובה<sup data-n=\"30\">30</sup> — נאר לאחרי ווי איינער איז ר\"ל דורכגע־פאלן, גיט מען אים א געלעגנהייט אז ער קען און ער מוז תשובה טאן.\nאבער צוזאמען דערמיט, איז פאראן אן עילוי גדול אין עבודת התשובה אויף עבודת הצדיקים, ווי חז\"ל<sup data-n=\"31\">31</sup> זאגן „מקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין לעמוד בו\".\nאון דעריבער, בכדי די אידן וואס זיינען געווען ביי מ\"ת זאלן צוקומען\n(אויך) צום עילוי פון תשובה — וואס מצ\"ע זיינען זיי ניט געווען שייך צו דער עבודה (ווארום „שליטים ביצרם היו\"<sup data-n=\"32\">32</sup>) — האט געמוזט זיין א „גזירת מלך\" אז דער יצר הרע זאל קענען שולט זיין אויף זיי לפי שעה און דורך דעם זאלן זיי קענען צוקומען צום עילוי פון תשובה.\nט. פון די עילויים אין עבודת התשובה אויף עבודת הצדיקים איז, וואס דוקא דורך תשובה קען מען מברר זיין די ניצוצות קדושה שנפלו און זיי געפינען זיך אין ג' קליפות הטמאות<sup data-n=\"33\">33</sup>:\nאן אדם ישר הולך, א צדיק קען מעלה זיין די ניצוצות קדושה וואס געפינען זיך אין ענייני רשות ודברי היתר, משא\"כ ענייני איסור דארף ער דוחה זיין<sup data-n=\"34\">34</sup> (ער קען ניט מאכן פון דעם דבר איסור א דבר של קדושה);\nא בעל תשובה אבער איז דורך תשובה שלימה פועל'ט ער אז זיינע זדונות זאלן ווערן זכיות<sup data-n=\"35\">35</sup>; ד.ה. ניט נאר וואס ער איז מבטל דעם רע, נאר נאכמער — ער איז מעלה די ניצוצות קדושה וואס זיינען דא אין זדונות, ביז אז זיי ווערן זכיות (וקדושה).\nיוד. דער חילוק הנ\"ל צווישן א צדיק און א בעל תשובה — אז דוקא א בעל תשובה איז מעלה די ניצוצות פון ג' קליפות הטמאות — איז ניט נאר ווייל א צדיק האט ניט קיין „זדונות\", נאר עס",[["27","27","פרש\"י לך יב, ה."],["28","28","ע\"ז ד, סע\"ב ובפרש\"י שם ד\"ה לא עשו."],["29","29","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091240\" data-slug=\"likkutei-sichot\" data-id=\"1300091240\">לקו\"ש ח\"ט ע' 240</a> ובהערה 28 שם."],["30","30","משנה סוף יומא."],["31","31","רמב\"ם הל' תשובה פ\"ז ה\"ד — כדעת ר' אבהו ברכות לד, ב. וראה לקו\"ש שם הערה 29."],["32","32","לשון רש\"י ע\"ז שם. ולהעיר מד\"ה וירד תרמ\"ג בסופו: ומה שבמ\"ת פסקה זוהמתן אולי י\"ל שהוא כמ\"ש בס\"ש בבינונים שהרע שבהם ישן כו' — והרי ענין השליטה ביצה\"ר הוא בבינוני (כשהרע ישן) — כמ\"ש בתניא שם לפנ\"ז (פי\"ג — יח, ב)."],["33","33","ראה בכ\"ז דרמ\"צ קצא, א. ועוד."],["34","34","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381156\" data-slug=\"likkutei-torah\" data-id=\"4001381156\">לקו\"ת שה\"ש ו, ד</a>."],["35","35","יומא פו, ב."]]],[1300161426,"איז אויך פארבונדן מיט דעם כללות החילוק צווישן עבודת הצדיקים און עבודת התשובה.\nדער ביאור אין דעם: מצד דער אחדות האמיתית פון דעם אויבערשטן איז דאך ניט שייך צו זאגן אז עס איז דא א עפעס א מציאות וואו עס דערגרייכט ניט ח\"ו די אחדות, וכמאמר רז\"ל<sup data-n=\"36\">36</sup> „אין עוד מלבדו .. ואפילו כשפים .. שמכחישין פמליא של מעלה\"; נאר אין דעם — אין דער אחדות — זיינען דא צוויי ענינים:\nא) דער רע איז ניט קיין סתירה צו אחדותו ית' — ווייל ער איז ניט קיין מציאות, ס'איז אן ענין פון „העדר\" — און דאס קומט בגילוי ע\"י העבודה פון דוחה זיין דעם רע;\nב) דער ניצוץ קדושה וועלכער איז מחי' דעם רע ווערט מיוחד בגילוי מיט אלקות — כאטש פריער איז ער „נתרחק ונחשך כ\"כ עד שהוא כמו רע\"<sup data-n=\"37\">37</sup> — ווארום דער תכלית און פנימיות הכוונה פון בריאת הרע [וואס דאס איז דער ענין פון דעם ניצוץ קדושה שבו] איז, אז ער זאל נתהפך ווערן לטוב און נתעלה ווערן לקדושה — און דאס קומט דורך עבודת התשובה וואס דורך דעם איז „זדונות נעשות לו כזכיות\", דער ניצוץ ווערט נתעלה אין קדושה.\nיא. בכללות איז דאס דער חילוק צווישן אחדות ה' ווי עס איז מצד אלקות און ווי דאס ווערט נתגלה אין וועלט<sup data-n=\"38\">38</sup>:\nמצד דער אחדות ה' ווי עס הערט זיך אין וועלט — ד.ה. אז עולם מצד ענינו הוא איז מיוחד מיט אלקות — ווייבאלד אז דער תוכן פון רע ווי ער איז מצד וועלט איז דאס וואס ער איז א מנגד לאלקות, ווערט די אחדות פון אויבערשטן אנטפלעקט דורכן דוחה זיין דעם רע, וואס דאס איז מגלה אז דער רע איז אן ענין פון „העדר\":\nמצד אלקות אבער, איז דאך די אמתית המציאות פון א זאך נאר איר פנימיות וכוונה — דער ניצוץ ודבר ה' וואס איז איר מחי'; און דעריבער, מצד דעם „דבר ה'\" וואס איז מחי' כביכול רע הערט זיך, אז די מציאות פון רע איז דאס וואס ווערט (דורך תשובה) נתעלה אין קדושה.\nיב. און דאס איז דער חילוק צווישן עבודת הצדיקים און עבודת הת־שובה<sup data-n=\"39\">39</sup>:\nעבודת הצדיקים איז בדרך המשכה<sup data-n=\"40\">40</sup> מלמעלה למטה — ממשיך זיין אלקות אין וועלט<sup data-n=\"41\">41</sup>; און אזוי אויך בנוגע צו רע — זיינען זיי מגלה אחדותו ית' אין רע ווי ס'איז מצד וועלט (עולם — מעלים מסתיר ומנגד צו אלקות), וואס דאס איז דורך דחיית הרע כנ\"ל;\nדי עבודה פון בעלי תשובה איז בדרך העלאה<sup data-n=\"40\">40</sup> מלמטה למעלה — ארויסגיין פון וועלט, און מצד דעם הערט זיך ביי",[["36","36","חולין ז, ב."],["37","37","המשך תער\"ב פרק שעד. סה\"מ עת\"ר ע' קג. ובד\"ה ויגדלו הנערים תרס\"ה: ע\"ד חתיכה נעשה נבילה."],["38","38","בהבא לקמן — להעיר מההפרש (תורת שלום ע' 49 ואילך. ע' 184 ואילך. ועוד) בין ב' אופני היחוד, הוי' אחד מלמטה למעלה והוי' אחד מלמעלה למטה."],["39","39","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091119\" data-slug=\"likkutei-sichot\" data-id=\"1300091119\">לקו\"ש ח\"ט ע' 119</a> ואילך בביאור הפלוגתא דרע\"ק ור\"י (מכילתא יתרו כ, א) אם אמרו „על הן הן ועל לאו לאו\" או „על הן ועל לאו הן\". ועיי\"ש בארוכה (ע' 126 הערה 35) ביאור הסיפור דרע\"ק ותלמידיו בברכות (סא, ב)."],["40","40","ראה ד\"ה תקעו תרס\"א. ובכ\"מ."],["41","41","שלכן דוקא ע\"י עבודת הצדיקים נעשה דירה בתחתונים (לקו\"ת שה\"ש ד\"ה מי יתנך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770165\" data-slug=\"or-hatorah-hb\" data-id=\"8316770165\">אוה\"ת שם</a>. המשך תרס\"ו ע' תקלג. ועוד)."]]],[1300161427,"זיי ווי דאס איז מצד „למעלה\": און אזוי אויך בנוגע צו רע — דערהערן זיי די פנימיות און כוונה פון רע, זיין „דבר ה'\" וואס איז מיוחד מיטן אויבערשטן — איז ער מעלה (דורך תשובה) דעם (ניצוץ שב)רע לקדושה.\nיג. דערמיט וועט מען פארשטיין וואס חז\"ל<sup data-n=\"42\">42</sup> זאגן אז די סיבה פון חטא העגל איז געקומען דורך דעם וואס אידן ביי מ\"ת האבן געזען דעם פני שור שבמרכבה. ולכאורה — תמי' הכי גדולה: אמת טאקע אז דער חטא העגל „גזירת מלך היתה\" (כנ\"ל בארוכה) — פארוואס אבער און ווי איז עס מעגלעך אז עס זאל קומען פון זען (פני שור ש)במרכבה און וואס מ'האט געזען ביי מ\"ת?\nוע\"פ הנ\"ל — אז דער ענין פון חטא העגל איז געווען בכדי צו צוברענגען אידן לידי מעלת התשובה — איז עס מובן, ווייל די עבודת התשובה פון אידן איז א המשך צום גילוי פון מתן תורה:\nבשעת מ\"ת איז נתגלה געווארן אחדותו ית' ווי דאס איז מצד „למעלה\"<sup data-n=\"43\">43</sup>, און בכדי אז די אחדות זאל קומען בגילוי אויך בשייכות צו וועלט למטה, ביז מעשה כשפים, ג' קליפות\nהטמאות, איז עס דורך (דער „גזירת מלך\" און) דער תשובה פון אידן אויף חטא העגל.\nיד. דער בירור פון די ניצוצות שברע הכי תחתון דורך דער תשובה אויפן חטא העגל, האט זיך אויסגע־דריקט אין דעם וואס די פון ערב רב וועלכע האבן געדינט דעם עגל און זיינען געבליבן לעבן האבן (אויך) תשובה געטאן:\nוואָרום דער ערב רב, וואס „הם שחתו והשחיתו\" מסיתים ומדיחים, וואס תורת אמת זאגט אז אסור ללמד זכות עליהם *<sup data-n=\"43\">43</sup>, זיינען פון ג' קליפות הטמאות<sup data-n=\"44\">44</sup> ורעות לגמרי ואין בהם טוב כלל *<sup data-n=\"44\">44</sup>, און זייער תשובה איז אן ענין פון „זדונות נעשות לו כזכיות\", אתהפכא חשוכא לנהורא.\nאון דאס איז דער פירוש הפנימי אין „(לך) עלה מזה (אתה והעם אשר העלית מארמ\"צ)\": די עליה איז „מזה\" — די עלי' וואס איז ארויסגעקומען דורך דעם חטא העגל — איז קענטיק אין דעם וואס דער ערב רב איז נתתקן און נתעלה געווארן לקדושה, אז פון „עמך\" איז געווארן — „העם\".",[["42","42","תנחומא פרשתנו כא. שמו\"ר פמ\"ב, ה."],["43","43","הכוונה באחדות ה' מצד „למעלה\" כאן היא [לא לענין ההעלאה כו' (דלעיל בפנים), כי אם] שכללות הגילוי דמ\"ת [שכולל ב' אופני אחדותו דלעיל סי\"א — הן גילוי אחדותו ית' מצד („למעלה\" — היינו הפנימיות והכוונה דהעולם, והן גילוי אחדותו ית' מצד („למטה\" — היינו ענינו דהעולם גופא] הי' לא מצד התחתון כ\"א מצד אלקות, בדרך מלמעלה למטה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380829\" data-slug=\"likkutei-torah\" data-id=\"4001380829\">לקו\"ת ראה כח, ב</a>. ד\"ה וירד שם. המשך תער\"ב ח\"ב ע' תתקל. *43) סנהדרין כט, א. פרש\"י בראשית ג, יד."],["44","44","ובפרט קודם שגיירם משה שהיו מגקה\"ט. ואין זה סותר להמבואר בכ\"מ [רמ\"ז לזהר פרשתנו קצא, א. מארא (וש\"נ) וקהי' ע' ערב רב. ולהעיר מאגה\"ק סכ\"ו (קמד, ב) שהערב רב יונקים מק\"נ] — כי זהו בדוגמת הפי' (החיד\"א במדבר קדמות מע' ג' אות ג') במחז\"ל „גר שנתגייר — שהמתגייר הוא גר מעיקרא [ובכ\"ז קודם שנתגייר הוא מגקה\"ט]. ולהעיר מנבוזראדן שהחריב כו' ולבסוף נתגייר (גיטין נז, ב. סנהדרין צו, ב). ועוד. ואולי החילוק — שזה בחיצונית וזה בהעלם בפנימית. *44) <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא ספ\"ו</a>."]]],[1300161428,"טו. הפטורות זיינען „מענינה של פרשה\" 45 — געפינט מען אט די נקודה אויך אין דער הפטורה<sup data-n=\"46\">46</sup> פון פ' תשא, אין דעם סיפור וועגן אליהו בהר הכרמל:\nוועגן דעם פר „שעלה לשם הבעל\" זאגן חז\"ל<sup data-n=\"47\">47</sup>, אז ער האט ניט געוואלט גיין „ואמר לאליהו כו' (ו)הוא (פרו של אליהו) עולה לחלקו של הקב\"ה ושמו של הקב\"ה מתקדש עליו ואני עליתי לחלק הבעל להכעיס את בוראי\", האט אליהו געענטפערט „כשם ששמו של הקב\"ה מתקדש על יד זה שעמי כך מתקדש על ידך\".\nאין פשטות מיינט עס: כשם ווי פרו של אליהו האט מקדש געווען שמו של הקב\"ה דורכן נס וואס האט פאסירט ביי זיין הקרבה, וואס האט באוויזן בגלוי דעם אמת פון אליהו'ס נבואה — אזוי האט דער פר „שעלה לשם הבעל\" מקדש געווען שמו של הקב\"ה דורך דעם וואס „אין קול ואין עונה\"<sup data-n=\"48\">48</sup> בעת זיין הקרבה — וואס האט באוויזן די פאלשקייט פון די נביאי הבעל (ועי\"ז — דעם אמת ה').\nעס איז אבער נאך אלץ ניט מובן: פון לשון המדרש „כשם ששמו של הקב\"ה מתקדש על יד זה שעמי כך מתקדש על ידך\" איז משמע, אז דער קידוש שמו של הקב\"ה ביי ביידע פרים איז געווען באופן שוה. ולכאורה: דער קידוש השם דורך פר של אליהו איז געווען דורך און\nאין דעם פר, דער אמת ה' איז נתגלה געווארן אין זיין הקרבה; דאקעגן ביי דעם פר „שעלה לשם הבעל\" איז דאך דער קידוש „שמו של הקב\"ה\" ארויס־געקומען באופן שלילי, זיין ניט הקרבה האט באוויזן אז דער בעל איז ניט אמת?\nאיז דער ביאור אין דעם: דורך עבודת אליהו (און זיין פעולה אז אידן זאלן תשובה טאן<sup data-n=\"49\">49</sup>) איז נתגלה געווארן למטה די אחדות פון אויבערשטן („ה' הוא האלקים\"<sup data-n=\"50\">50</sup>) ווי דאס איז מצד „למעלה\"<sup data-n=\"51\">51</sup>; און ווייבאלד אז מצד דער אחדות שטייט בגילוי דער „דבר ה'\", די פנימיות און כוונה פון (יעדער זאך אין וועלט —\nאיז דעריבער „כשם ששמו של הקב\"ה מתקדש על יד זה שעמי כך מתקדש על ידך\" — די זעלבע אחדות<sup data-n=\"52\">52</sup> [וואָרום",[["45","45","טושו\"ע או\"ח רסרפ\"ד. שו\"ע אדה\"ז שם (וסרפ\"ג)."],["46","46","מ\"א יח, כ ואילך (ולמנהג האשכנזים — שם, א ואילך)."],["47","47","במדב\"ר פכ\"ג, ט. יל\"ש מ\"א רמז ריד. הובא ברד\"ק (ופרש\"י) מלכים שם, כו."],["48","48","מלכים שם (ושם, כט)."],["49","49","כאמרם „ה' הוא האלקים ה' הוא האלקים\" (מלכים שם, לט). וראה אוה\"ת עה\"פ (וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011201\" data-slug=\"likkutei-sichot\" data-id=\"1300011201\">לקו\"ש ח\"א ע' 186</a>), שב\"פ „ה' הוא האלקים\" הו\"ע התשובה."],["50","50","מלכים שם."],["51","51","להעיר דאליהו ענינו שם ב\"ן (ראה המשך תרס\"ז ס\"ע קנו ואילך. ד\"ה וה\"ס תש\"ח. ועוד), העלאה מלמטה למעלה, בדוגמת עבודת התשובה (ראה הנסמן לעיל הערה 40)."],["52","52","וע\"ד משנ\"ת (לקו\"ש שנסמן לעיל סיום הערה 39) בשיטת רע\"ק שבנ\"י ענו (בעת מ\"ת) „על הן הן ו(גם) על לאו הן\", עיי\"ש. וי\"ל, דזה שהפר אמר „הוא עולה לחלקו של הקב\"ה כו' ואני עליתי לחלק הבעל להכעיס את בוראי\", אין הכוונה (כפשטות הלשון) שלא רצה בזה משום שעי\"ז הוא נקרב לע\"ז — שא\"כ, מהו אריכות הלשון „אני וחברי יצאנו מבטן אחד כו' והוא עולה כו' ואני עליתי כו'\", והו\"ל רק שלא רצה לילך כו' לעלות לחלק הבעל להכעיס את בוראי\", ולמאי נפק\"מ שחברו „עולה לחלקו של הקב\"ה\"? — כ\"א: אף שגם ע\"י שעולה לבעל מתקדש שמו של הקב\"ה (כי בזה מגלה שנביאי הבעל אינם אמת) — מ\"מ, למה יוגרע חלקו מ„חברו\" (ש„יצאנו מבטן א'"]]],[1300161429,"דורך תשובה איז נתגלה געווארן די פנימיות פון דעם פר שעלה לשם הבעל<sup data-n=\"53\">53</sup> — ווי דער (ניצוץ שב)פר ווערט נתעלה אין קדושה].\nטז. דערפון איז אויך די הוראה בנוגע לפועל: עס זיינען פאראן אזוינע וואס קאכן זיך נאר אין די זאכן וואס זיינען לכתחילה קדושה — אין זיי, טענה'ט ער, ווערט נתקדש „שמו של הקב\"ה\";\nאבער באוארענען און עובר עבירה, ר\"ל — וואס ווי דער אלטער רבי איז מסביר<sup data-n=\"54\">54</sup>, איז יעדע עבירה היפך ממש פון רצון העליון און דאס איז בדוגמת איסור השתחואה לע\"ז — אין דעם טוט ער ניט. ער טענה'ט אז ער וויל ניט האבן צו טאן מיט „פר של ע\"ז\".\nאויף דעם זאגט מען, אז „כשם ששמו של הקב\"ה מתקדש על יד זה שעמי, כך\nמתקדש על ידך\", אט די אחדות ווערט נתגלה דוקא דורך להוציא יקר מזולל<sup data-n=\"55\">55</sup> דורך פארנעמען זיך מיט מחזיר זיין בתשובה די וואס נויטיגען זיך בתשובה, וואס דורך דעם — זדונות נעשות להם כזכיות.\nואדרבה: דער סדר פון אליהו איז געווען אז ער האט פריער געגעבן די נביאי הבעל דעם פר „שעלה לשם הבעל\" אז זיי זאלן פרואוון עס מקריב זיין, און ערשט דערנאך האט ער מקריב געווען זיין פר, ד.ה. די עבודה פון מקדש זיין „שמו של הקב\"ה\" דורך דעם פר „שעלה לשם הבעל\" קומט פאַרן „שמו של הקב\"ה מתקדש על יד זה שעמי\".\nאון אזוי אויך בעבודת כאו\"א: אפילו ווען די עבודה פון מקרב זיין א דער־ווייטערטן אידן איז אמאל פארבונדן מיט אוועקנעמען צייט פון זיין לימוד התורה ועבודה („זה שעמי\") — דארף מען וויסן, אז עס דארף זיין דער שם שמים מתקדש דורך מעלה זיין דעם פר „שעלה לשם הבעל\" — מקרב זיין א אידן וואס איז ווייט פון אידישקייט, כשם ווי „שמו של הקב\"ה מתקדש על יד זה שעמי\", זיין אייגענע תורה ועבודה\nאון די עבודה כפולה בדוגמת פון דעם סיפור התורה וועגן אליהו הנביא מבשר הגאולה, וועט ברענגען די גאולה האמיתית והשלימה בקרוב ממש.\n(משיחות ש\"פ תשא תשל\"א, חגה\"ש תשכ\"ד, ש\"פ שמות תשל\"ו)",[["","","כו'), ששם שמים יתקדש על ידו (לא בו גופא, כ\"א) באופן שלילי („על לאו לאו\"), שמציאות ד„להכעיס את בוראי\" אינה אמיתית (כ\"א — העדר), ולא באופן חיובי — שיוקרב לה', וע\"ז ענה לו אליהו „כשם ששמו של הקב\"ה מתקדש כו' כך מתקדש כו'\" — שמצד עצמותו ית' ה\"ז אותה האחדות, ובאופן חיובי — „על לאו הן\", כבפנים."],["53","53","עפמ\"ש בשו\"ת הרדב\"ז (סי' אלף סו) דהמרים בין אליהו והפר היינו עם „שרו וכחו של פר\" — יומתק ג\"כ מה שגם לאחרי מענה אליהו „כשם כו'\" לא רצה הפר לילך כו' ו„א\"ל כו' עד שתמסרני בידם\" — כי זה „ששמו של הקב\"ה מתקדש כו' על ידך\" הוא דוקא מצד ה„כוונה\" ו„דבר ה'\" של הפר, אבל לא בכחו של הפר כמו\"ש למטה ונקרב לבעל; ולכן נרגש זה (ד„כשם כו'\") רק ב„שרו וכחו של פר\" למעלה, וכדי שהפר למטה ילך כו' הוא דוקא ע\"י שאליהו מסרו בידים."],["54","54","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ\"ד</a>."],["55","55","ע\"פ ירמי' טו, יט. וראה ב\"מ פה, א."]]],[1300161430,"<h3>פ' פרה</h3>\nא. עס שטייט אין ירושלמי1: „בדין הוא שתקדים החודש לפרה, שבאחד בניסן הוקם המשכן ובשני נשרפה הפרה, ולמה פרה קודמת שהיא טהרתן של כל ישראל\". דאס הייסט, אז פריער לייענט מען פרשת פרה „להזהיר את ישראל לטהר, שיעשו פסחיהן בטהרה\"2, און דערנאך — פרשת החודש, „ששם פרשת הפסח\"2.\nפון לשון הירושלמי „שהיא טהרתן של כל3 ישראל\" איז מוכח, אז די טהרה פון פרה אדומה איז נוגע צו אלע אידן. אזוי איז אויך מובן פון דעם תוכן הענין דארט, אז מ'האט מתקן געווען אז מ'זאל לייענען פ' פרה — וואס די תקנת הקריאה איז פאר אלע אידן — פריער פון פ' החודש (כאטש אז „בדין הוא שתקדים החודש לפרה\"), מצד דעם טעם „שהיא (פרה) טהרתן של כל ישראל\".\nוצריך ביאור נוסף והמתקת הענין: אז מען דארף זיך מטהר זיין פון טומאת מת איידער מ'ברענגט דעם קרבן פסח, איז נוגע נאר צו די וואס זיינען טמאי מת, אבער ניט צו „כל ישראל\"; ואדרבה — ווען רוב אידן זיינען טמאי מתים, דארף מען ניט אנקומען צו פרה (וטהרתן של ישראל) אז זיי זאלן קענען ברענגען\nדעם קרבן פסח, ווייל א ציבור4 ברענגט דעם קרבן פסח (אויך<sup data-n=\"5\">5</sup> בטומאה — היינט פארוואס דארפן אלע אידן (וואס נמשכין נאכ'ן רוב, ניט נאכ'ן מיעוט) מקדים זיין (קריאת פ') „פרה\" פאר „החודש\" מצד דעם וואס „היא טהרתן של כל ישראל\"6, און ניט החודש פריער פאר פרה (ווי עס דארף זיין „בדין\")?\nמוז מען זאגן (בפנימיות הענינים), אז דאס וואס פרה איז „טהרתן של כל ישראל\" מיינט ניט נאר די טהרה כפשוטה (פון טומאת מת בפשטות), נאר אזא טהרה וואס „כל ישראל\" דארפן אנ־קומען צו איר, אין וואס פאר א מצב זיי זאלן נאר זיין, און דאס דוקא גרייט זיי צו צום ענין פון „החודש\" (ופסח).\nב. וועט מען דאס פארשטיין בהק־דים, אז מען געפינט א חידוש אין דער מצוה פון פרה אדומה:\nדער רמב\"ם זאגט אין ספר המצות7, אז די מצוה פון פרה אדומה איז — „לעשות פרה אדומה כדי שיהי' אפרה מזומן למי8 שיצטרך אליו לטהרת",[["1","1","מגילה פ\"ג ה\"ה. הובא ברי\"ף ורש\"י למגילה כט, א. ועוד."],["2","2","פרש\"י מגילה שם ד\"ה פרה אדומה וד\"ה ברביעית. וראה ס' הפרדס לרש\"י „סדר פרשיות\"."],["3","3","ברי\"ף ורש\"י שם (וכן בקה\"ע ופני משה לירושלמי שם) ועוד — ליתא תיבת „כל\". אבל בדפוסי ירושלמי לפנינו הוא כבפנים. — והעיקר: השאלה שבפנים היא בתוכן הענין, ולאו דוקא בדיוק הל' „כל\", כדלקמן."],["4","4","פסחים סו, סע\"ב ואילך. שם עט, א ואילך. רמב\"ם הל' קרבן פסח רפ\"ז."],["5","5","אע\"פ שגם אז צריך להשתדל שיעשו בטהרה (כמו בנדו\"ד שפרה נקראת קודם ר\"ח שדי זמן להטהר) ובפרט למ\"ד שטומאה הודחה בצבור (פסחים עז, א. יומא ו, ב. וש\"נ)."],["6","6","בס' הפרדס שם מקשר זה דפרה קודמת מפני שהיא טהרתן של ישראל עם הא דחייב אדם לטהר את עצמו ברגל (ר\"ה טז, ב) — אבל בפשטות, הענין דטהרתן של ישראל דפ' פרה הוא (לא ענין הטהרה (ברגל) בכלל, כ\"א) רק טהרה מטומאת מת (וגם: החיוב לטהר עצמו ברגל אינו שייך לפסח דוקא). וראה לקמן בפנים סעיף ב' ובהערה 12. וראה לקו\"ש חל\"ו ע' 207 ואילך."],["7","7","מ\"ע קיג."],["8","8","בתרגום העליר וקאפח שינויים בלשון (ולא"]]],[1300161431,"טומאת מת\", אז די תכלית המצוה בא־שטייט ניט (נאר) אין נוצן דעם אפר בשעת הצורך — ווען א איד ווערט טמא מת און דארף האבן די טהרה באפרה — נאר דער אפר הפרה דארף זיין מלכתחילה גרייט פאר יעדן וואס וועט עס דארפן, אז צו יעדער צייט וואס א איד וועט זיך נויטיקן אין דער טהרה זאל ער באלד קענען זיך מטהר זיין מיטן אפר הפרה.\nאון דער רמב\"ם ברענגט דערויף דעם פסוק9 „והיתה לעדת בני ישראל למש־מרת\"10. וואס דער פירוש הפשוט איז, אז דער אפר הפרה דארף זיין גרייט, משומר, פאר יעדן „עדת בני ישראל\", כל ישראל — אפשר וועט ער דארפן אנקומען צו דער טהרה באפר הפרה.\nדער חידוש אין דעם איז נאך מער: אויף א טמא מת איז ניטא קיין חיוב (דאורייתא) ער זאל זיך מטהר זיין; אפילו קודם הרגל, ווען ס'איז דא דער חיוב „לטהר את עצמו ברגל\"11, איז (נוסף לזה אז אין דעם איז דא א שקו\"ט12 צי דאס איז דאורייתא אדער דרבנן), דאס חל נאר אויף דעם וואס איז מחוייב בעלי' לרגל; לאפוקי אנדערע — לדוגמא דעם וואס האט ניט קיין קרקע בא\"י (אדער דער וואס גע־פינט זיך אין חו\"ל) וואס ער איז פטור פון עלי' לרגל (און פון קרבן פסח)13, איז ער אויך ניט מחוייב „לטהר את עצמו ברגל\".\nקומט אויס, אז דאס וואס אפר הפרה דארף זיין „מזומן למי שיצטרך אליו לטהרת טומאת מת\" איז עס (ניט דוקא פאר איינעם וואס די טהרה מטומאתו איז ביי אים א חיוב, נאר אויך) פאר אזא וואס זיין טהרה איז תלוי' ברצונו, און ווען ער ווערט נתעורר ברצונו לטהר עצמו14 — מוז (אויך) פאר אים זיין מזומן דער אפר הפרה, אז ער זאל זיך קענען מטהר זיין גלייך ווען ער וויל.\nג. דער ענין איז אויך מודגש אין לשון הרס\"ג (אין זיין ספר המצות<sup data-n=\"15\">15</sup>, וואו ער שרייבט, אז די מצוה פון פרה אדומה איז — „ופרה למשמרת בתדר\", אז דער אפר הפרה דארף זיין גרייט בתדר (— שטענדיק).\nעס זיינען דא אחרונים16 וואס ווילן מדייק זיין פון לשון הרס\"ג „ופרה למש־מרת בתדר\", אז ער מיינט דערמיט (ניט דעם חלק האפר ש„היו ישראל מזין הימנו\"17, נאר) דעם חלק האפר וואס „נותן בחיל\"18. ווייל דוקא אויף דעם",[["","","בתוכן הכללי). ובחינוך מצוה שצז (שידוע שבכ\"מ העתיק לשון הרמב\"ם): לשרוף פרה אדומה להיות אפרה מוכן למי שיצטרך אלי' ומטהרה מטומאת מת. ובמנין המצות בריש ספר היד: לעשות פרה אדומה להיות אפרה מוכן. וראה רמב\"ם ספר המדע (ירושלים תשכ\"ד) שם בשינויי נוסחאות."],["9","9","חוקת יט, ט."],["10","10","כ\"ה בתרגום העליר וקאפח (שהועתקה גם תיבת „למשמרת\"). וכ\"ה בחינוך שם. וראה ס' המדע הנ\"ל בש\"נ (שם)."],["11","11","ר\"ה שם. רמב\"ם הל' טומאת אוכלין פט\"ז ה\"י."],["12","12","ראה משנה למלך לרמב\"ם שם (ושם שקו\"ט בעיקר בנוגע להאזהרה דמגע נבילה כו' קודם הרגל אם הוא איסור תורה או דרבנן). וראה שד\"ח כללים מע' חי\"ת כלל מז. וש\"נ."],["13","13","ראה פסחים ח, ב. תוד\"ה מאלי' — שם ג, ב. שד\"ח שם. וראה בכ\"י הרי\"ף פערלא לסהמ\"צ רס\"ג פרשה מה (קצא, ב)."],["14","14","שהרי אין הכוונה ב„למי שיצטרך אליו לטהרת טומאת מת\", שצריך ומחוייב בטהרתו, כ\"א שצריך להאפר („אליו\") בשביל טהרתו. וכדמוכח ג\"כ מהגירסא (ראה תרגום העליר וקאפח) „למה שיצטרך\"."],["15","15","שם."],["16","16","הרי\"ף פערלא שם (קצ, ד)."],["17","17","לשון התוספתא — פרה אדומה ספ\"ג. רמב\"ם הל' פרה אדומה ספ\"ג (וראה תוי\"ט פרה ספ\"ג)."],["18","18","פרה שם. רמב\"ם שם."]]]]});
